    PutObjectResponse put1 = s3Client.putObject(PutObjectRequest.builder().bucket(TEST_BUCKET).key(key).serverSideEncryption(ServerSideEncryption.AES256).ifNoneMatch("*").build(), RequestBody.fromString("Hello1"));
    // Put a second object with different contents
    PutObjectResponse put2 = s3Client.putObject(PutObjectRequest.builder().bucket(TEST_BUCKET).key(key).serverSideEncryption(ServerSideEncryption.AES256).ifMatch(put1.eTag()).build(), RequestBody.fromString("Hello2"));
    s3Client.close();
    // ETags should differ
    assertNotNull(put1.eTag());
    assertNotNull(put2.eTag());
    assertNotEquals(put1.eTag(), put2.eTag(), "ETags should differ if the content changed");
}

