    when(mockCreator.create(any(), any(), any())).thenReturn(mockService);
    when(mockService.startService()).thenReturn(123);
    EmbeddedTimelineService service1 = EmbeddedTimelineService.getOrStartEmbeddedTimelineService(engineContext, null, writeConfig1, mockCreator);
    HoodieWriteConfig writeConfig2 = HoodieWriteConfig.newBuilder().withPath(tempDir.resolve("table2").toString()).withEmbeddedTimelineServerEnabled(true).withEmbeddedTimelineServerReuseEnabled(true).withFileSystemViewConfig(FileSystemViewStorageConfig.newBuilder().withRemoteTimelineClientRetry(true).build()).build();
