    // StorageBasedLockProvider instantiation (not a reflection failure)
    assertTrue(exception.getCause().getCause().getCause().getMessage().startsWith("Unsupported scheme"), "Exception should mention scheme failure, confirming metrics constructor was successfully found and used");
    lockManager.close();
}

