        // Then: Should not throw exception because regular string is supported
        assertDoesNotThrow(() -> HoodieIndexUtils.validateEligibilityForSecondaryOrExpressionIndex(mockMetaClient, PARTITION_NAME_SECONDARY_INDEX, options, columns, "test_index"));
    }
}

