/**
 * Given: An existing file slice with records and new log files with updates/inserts/deletes
 * When: trackSecondaryIndexStats is called with both existing and new data
 * Then: Should correctly identify unchanged records (no update), updated records (delete old + insert new),
 *       new records (insert), and deleted records (delete)
 */
@Test
public void testTrackSecondaryIndexStats_WithExistingFileSlice() {
    String partitionPath = "2023/01/01";
    String fileId = "file-002";
    List<String> newLogFiles = Arrays.asList(partitionPath + "/.file-002_20231201130000.log.1");
    String instantTime = "20231201130000";
    FileSlice existingFileSlice = new FileSlice(new HoodieFileGroupId(partitionPath, fileId), instantTime);
    HoodieIndexDefinition indexDef = HoodieIndexDefinition.newBuilder().withIndexName(MetadataPartitionType.SECONDARY_INDEX.getPartitionPath() + "_fare_index").withIndexType("SECONDARY_INDEX").withSourceFields(Collections.singletonList("fare")).build();
    try (MockedStatic<SecondaryIndexRecordGenerationUtils> mockedUtils = mockStatic(SecondaryIndexRecordGenerationUtils.class)) {
        // Mock previous file slice
        Map<String, String> previousMap = new HashMap<>();
        previousMap.put("key1", "100.5");
        previousMap.put("key2", "200.75");
        // Will be deleted
        previousMap.put("key3", "300.0");
        // Mock current file slice
        Map<String, String> currentMap = new HashMap<>();
        // Same value
        currentMap.put("key1", "100.5");
        // Updated value
        currentMap.put("key2", "250.0");
        // New record
        currentMap.put("key4", "400.5");
        mockedUtils.when(() -> SecondaryIndexRecordGenerationUtils.getRecordKeyToSecondaryKey(eq(metaClient), eq(readerContext), eq(existingFileSlice), eq(schema), eq(indexDef), eq(instantTime), any(TypedProperties.class), eq(false))).thenReturn(previousMap);
        mockedUtils.when(() -> SecondaryIndexRecordGenerationUtils.getRecordKeyToSecondaryKey(eq(metaClient), eq(readerContext), any(FileSlice.class), eq(schema), eq(indexDef), eq(instantTime), any(TypedProperties.class), eq(true))).thenReturn(currentMap);
        // Test with existing file slice
        SecondaryIndexStreamingTracker.trackSecondaryIndexStats(partitionPath, fileId, Option.of(existingFileSlice), newLogFiles, writeStatus, hoodieTable, Collections.singletonList(indexDef), config, instantTime, schema);
        // Should have: 1 update (delete + insert for key2), 1 insert (key4), 1 delete (key3)
        List<SecondaryIndexStats> stats = writeStatus.getIndexStats().getSecondaryIndexStats().get(indexDef.getIndexName());
        // 2 for update + 1 insert + 1 delete
        assertEquals(4, stats.size());
        // Verify each operation
        long deleteCount = stats.stream().filter(s -> s.isDeleted()).count();
        // key2 old value + key3
        assertEquals(2, deleteCount);
        long insertCount = stats.stream().filter(s -> !s.isDeleted()).count();
        // key2 new value + key4
        assertEquals(2, insertCount);
        // Validate detailed stats content
        // Check key2 update (delete old value + insert new value)
        assertTrue(stats.stream().anyMatch(s -> s.getRecordKey().equals("key2") && s.getSecondaryKeyValue().equals("200.75") && s.isDeleted()), "Should have delete entry for key2's old value");
        assertTrue(stats.stream().anyMatch(s -> s.getRecordKey().equals("key2") && s.getSecondaryKeyValue().equals("250.0") && !s.isDeleted()), "Should have insert entry for key2's new value");
        // Check key3 deletion
        assertTrue(stats.stream().anyMatch(s -> s.getRecordKey().equals("key3") && s.getSecondaryKeyValue().equals("300.0") && s.isDeleted()), "Should have delete entry for key3");
        // Check key4 insertion
        assertTrue(stats.stream().anyMatch(s -> s.getRecordKey().equals("key4") && s.getSecondaryKeyValue().equals("400.5") && !s.isDeleted()), "Should have insert entry for key4");
        // Verify key1 is not in stats (no change)
        assertFalse(stats.stream().anyMatch(s -> s.getRecordKey().equals("key1")), "key1 should not have any stats entries as its value didn't change");
    }
}

