    StoragePath baseFilePath2 = createBaseFileAndMarkerToRollback(partition2, baseFileId2, instantToRollbackTs);
    StoragePath baseFilePath3 = createBaseFileAndMarkerToRollback(partition2, baseFileId3, instantToRollbackTs);
    // Log files to roll back. logFilesToRollback1 is in new file group part of instant being rolled back
    Map<String, Long> logFilesToRollback1 = createLogFilesAndMarkersToRollback(partition2, logFileId1, instantToRollbackTs, instantToRollbackTs, IntStream.of(1));
    // Multiple rollback requests of log files belonging to the same file group
    Map<String, Long> logFilesToRollback2 = IntStream.range(1, ROLLBACK_LOG_VERSION).boxed().flatMap(version -> createLogFilesAndMarkersToRollback(partition2, logFileId2, baseInstantTimeOfLogFiles, instantToRollbackTs, IntStream.of(version)).entrySet().stream()).collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
    HoodieInstant instantToRollback = INSTANT_GENERATOR.createNewInstant(HoodieInstant.State.INFLIGHT, HoodieTimeline.DELTA_COMMIT_ACTION, instantToRollbackTs);
    List<HoodieRollbackRequest> actual = new MarkerBasedRollbackStrategy(table, context, config, rollbackInstantTime).getRollbackRequests(instantToRollback);
    List<HoodieRollbackRequest> expected = new ArrayList<>();
    expected.add(new HoodieRollbackRequest(partition1, baseFileId1, instantToRollbackTs, Collections.singletonList(baseFilePath1.toString()), Collections.emptyMap()));
    expected.add(new HoodieRollbackRequest(partition2, baseFileId2, instantToRollbackTs, Collections.singletonList(baseFilePath2.toString()), Collections.emptyMap()));
    expected.add(new HoodieRollbackRequest(partition2, baseFileId3, instantToRollbackTs, Collections.singletonList(baseFilePath3.toString()), Collections.emptyMap()));
    if (tableVersion.greaterThanOrEquals(HoodieTableVersion.EIGHT)) {
        logFilesToRollback1.keySet().forEach(logFilePath -> expected.add(new HoodieRollbackRequest(partition2, logFileId1, instantToRollbackTs, Collections.singletonList(logFilePath), Collections.emptyMap())));
        logFilesToRollback2.keySet().forEach(logFilePath -> expected.add(new HoodieRollbackRequest(partition2, logFileId2, instantToRollbackTs, Collections.singletonList(logFilePath), Collections.emptyMap())));
    } else {
        String logFile1Path = new StoragePath(new StoragePath(basePath, partition2), logFilesToRollback1.keySet().stream().findFirst().get()).toString();
        // Since logFile1 is part of a new file group, it can be deleted as part of rollback
        // logFile2 would be rolled back using a rollback command block
        expected.add(new HoodieRollbackRequest(partition2, "", "", Collections.singletonList(logFile1Path), Collections.emptyMap()));
        expected.add(new HoodieRollbackRequest(partition2, logFileId2, baseInstantTimeOfLogFiles, Collections.emptyList(), logFilesToRollback2));
    }
    assertRollbackRequestListEquals(expected, actual);
}

