    when(mockedStorage.exists(baseFilePath2)).thenReturn(false);
    // fs.delete throws FileNotFoundException
    when(mockedStorage.deleteFile(baseFilePath3)).thenThrow(new FileNotFoundException("File does not exist"));
    when(timeline.lastInstant()).thenReturn(Option.of(INSTANT_GENERATOR.createNewInstant(HoodieInstant.State.INFLIGHT, HoodieTimeline.ROLLBACK_ACTION, rollbackInstantTime)));
    List<Pair<String, HoodieRollbackStat>> rollbackStats = rollbackHelper.maybeDeleteAndCollectStats(context, INSTANT_GENERATOR.createNewInstant(HoodieInstant.State.INFLIGHT, HoodieTimeline.DELTA_COMMIT_ACTION, instantToRollback), rollbackRequests, true, 5);
    List<Pair<String, HoodieRollbackStat>> expected = new ArrayList<>();
    expected.add(Pair.of(partition1, HoodieRollbackStat.newBuilder().withPartitionPath(partition1).withDeletedFileResult(baseFilePath1.toString(), true).build()));
    expected.add(Pair.of(partition1, HoodieRollbackStat.newBuilder().withPartitionPath(partition1).withDeletedFileResult(baseFilePath2.toString(), true).build()));
    expected.add(Pair.of(partition1, HoodieRollbackStat.newBuilder().withPartitionPath(partition1).withDeletedFileResult(baseFilePath3.toString(), true).build()));
    assertRollbackStatsEquals(expected, rollbackStats);
    // error case, where fs.delete returned false and fs.exists returned true
    rollbackRequests.clear();
    String baseFileId4 = UUID.randomUUID().toString();
    StoragePath baseFilePath4 = addRollbackRequestForBaseFile(rollbackRequests, partition1, baseFileId4, instantToRollback);
    // fs.delete -> false, fs.exists -> true
    when(mockedStorage.deleteFile(baseFilePath4)).thenReturn(false);
    when(mockedStorage.exists(baseFilePath4)).thenReturn(true);
    // execute and assert failure
    assertFailedDeletion(rollbackHelper, context, rollbackInstantTime, instantToRollback, rollbackRequests, baseFilePath4.toString());
}

@ParameterizedTest
@CsvSource(value = { "true,true", "true,false", "false,false" })
void testGroupRollbackRequestsBasedOnFileGroup(boolean nonPartitioned, boolean useNullPartitionPath) {
    // The file names generated here are not compliant to the Hudi format
    // However, that's irrelevant to grouping the rollback requests
    List<HoodieRollbackRequest> inputList = new ArrayList<>();
    String partition1 = nonPartitioned ? (useNullPartitionPath ? null : "") : "partition1";
    String partition2 = nonPartitioned ? (useNullPartitionPath ? null : "") : "partition2";
    String expectedPartition2 = nonPartitioned ? "" : "partition2";
    String baseFileName1 = "basefile1";
    String baseFileName2 = "basefile2";
    String baseFileName3 = "basefile3";
    String baseFileName4 = "basefile4";
    String baseInstantTime1 = "003";
    String baseFileId1 = UUID.randomUUID().toString();
    String baseFileId2 = UUID.randomUUID().toString();
    String baseFileId3 = UUID.randomUUID().toString();
    String logFileId1 = UUID.randomUUID().toString();
    int numLogFiles1 = 10;
    String baseInstantTime2 = "002";
    String logFileId2 = UUID.randomUUID().toString();
    int numLogFiles2 = 5;
    String baseInstantTime3 = "001";
    // Empty
    inputList.add(new HoodieRollbackRequest(partition1, baseFileId1, baseInstantTime1, Collections.emptyList(), Collections.emptyMap()));
    inputList.add(new HoodieRollbackRequest(partition2, baseFileId2, baseInstantTime1, Collections.emptyList(), Collections.emptyMap()));
    // Base Files
    inputList.add(new HoodieRollbackRequest(partition1, baseFileId1, baseInstantTime1, Collections.singletonList(baseFileName1), Collections.emptyMap()));
    inputList.add(new HoodieRollbackRequest(partition2, baseFileId2, baseInstantTime1, Collections.singletonList(baseFileName2), Collections.emptyMap()));
    inputList.add(new HoodieRollbackRequest(partition2, baseFileId3, baseInstantTime1, Collections.singletonList(baseFileName3), Collections.emptyMap()));
    List<HoodieRollbackRequest> expected = new ArrayList<>(inputList);
    Map<String, Long> logFileMap1 = new HashMap<>();
    Map<String, Long> logFileMap2 = new HashMap<>();
    // Log Files
    IntStream.rangeClosed(2, numLogFiles1 + 1).forEach(i -> {
        inputList.add(new HoodieRollbackRequest(partition2, logFileId1, baseInstantTime2, Collections.emptyList(), Collections.singletonMap(logFileId1 + "." + i, i * 2L)));
        logFileMap1.put(logFileId1 + "." + i, i * 2L);
    });
    IntStream.rangeClosed(2, numLogFiles2).forEach(i -> {
        inputList.add(new HoodieRollbackRequest(partition2, logFileId2, baseInstantTime3, Collections.emptyList(), Collections.singletonMap(logFileId2 + "." + i, i * 3L)));
        logFileMap2.put(logFileId2 + "." + i, i * 3L);
    });
    // Base + Log files which should not happen, but should not fail the grouping
    inputList.add(new HoodieRollbackRequest(partition2, logFileId2, baseInstantTime3, Collections.singletonList(baseFileName4), Collections.singletonMap(logFileId2 + "." + (numLogFiles2 + 1), (numLogFiles2 + 1) * 3L)));
    logFileMap2.put(logFileId2 + "." + (numLogFiles2 + 1), (numLogFiles2 + 1) * 3L);
    expected.add(new HoodieRollbackRequest(expectedPartition2, logFileId1, baseInstantTime2, Collections.emptyList(), logFileMap1));
    expected.add(new HoodieRollbackRequest(expectedPartition2, logFileId2, baseInstantTime3, Collections.emptyList(), logFileMap2));
    expected.add(new HoodieRollbackRequest(expectedPartition2, logFileId2, baseInstantTime3, Collections.singletonList(baseFileName4), Collections.emptyMap()));
    assertEquals(5 + numLogFiles1 + numLogFiles2, inputList.size());
    List<HoodieRollbackRequest> actual = RollbackUtils.groupRollbackRequestsBasedOnFileGroup(inputList);
    List<SerializableHoodieRollbackRequest> actualSerializable = groupSerializableRollbackRequestsBasedOnFileGroup(inputList.stream().map(SerializableHoodieRollbackRequest::new).collect(Collectors.toList()));
    assertRollbackRequestListEquals(expected, actual);
    assertSerializableRollbackRequestListEquals(expected.stream().map(SerializableHoodieRollbackRequest::new).collect(Collectors.toList()), actualSerializable);
}

