@Test
void testDowngradeDropsOnlyV2OrAboveIndexes() {
    // Use try-with-resources to ensure the static mock is closed
    try (MockedStatic<UpgradeDowngradeUtils> mockedUtils = Mockito.mockStatic(UpgradeDowngradeUtils.class)) {
        // Mock the static method to do nothing - avoid NPE
        mockedUtils.when(() -> UpgradeDowngradeUtils.rollbackFailedWritesAndCompact(any(HoodieTable.class), any(HoodieEngineContext.class), any(HoodieWriteConfig.class), any(SupportsUpgradeDowngrade.class), anyBoolean(), any(HoodieTableVersion.class))).thenAnswer(// Do nothing
        invocation -> null);
        // Mock the dropNonV1SecondaryIndexPartitions to simulate dropping V2 indexes
        mockedUtils.when(() -> UpgradeDowngradeUtils.dropNonV1IndexPartitions(eq(config), eq(context), eq(table), eq(upgradeDowngradeHelper), any(String.class))).thenAnswer(invocation -> {
            // Get the write client and call dropIndex with expected partitions
            BaseHoodieWriteClient writeClient = upgradeDowngradeHelper.getWriteClient(config, context);
            List<String> partitionsToDrop = Arrays.asList("secondary_index_v2");
            writeClient.dropIndex(partitionsToDrop);
            return null;
        });
        // Arrange
        // Mock index definitions: one V1, one V2, one V3
        Map<String, HoodieIndexDefinition> indexDefs = new HashMap<>();
        indexDefs.put(MetadataPartitionType.SECONDARY_INDEX.getPartitionPath() + "v1", HoodieIndexDefinition.newBuilder().withIndexName(MetadataPartitionType.SECONDARY_INDEX.getPartitionPath() + "v1").withIndexType(MetadataPartitionType.SECONDARY_INDEX.getPartitionPath()).withVersion(HoodieIndexVersion.V1).build());
        indexDefs.put(MetadataPartitionType.SECONDARY_INDEX.getPartitionPath() + "v2", HoodieIndexDefinition.newBuilder().withIndexName(MetadataPartitionType.SECONDARY_INDEX.getPartitionPath() + "v2").withIndexType(MetadataPartitionType.SECONDARY_INDEX.getPartitionPath()).withVersion(HoodieIndexVersion.V2).build());
        indexDefs.put(MetadataPartitionType.FILES.getPartitionPath(), HoodieIndexDefinition.newBuilder().withIndexName(MetadataPartitionType.FILES.getPartitionPath()).withIndexType(MetadataPartitionType.FILES.getPartitionPath()).withVersion(HoodieIndexVersion.V2).build());
        indexDefs.put(MetadataPartitionType.COLUMN_STATS.getPartitionPath(), HoodieIndexDefinition.newBuilder().withIndexName(MetadataPartitionType.COLUMN_STATS.getPartitionPath()).withIndexType(MetadataPartitionType.COLUMN_STATS.getPartitionPath()).withVersion(HoodieIndexVersion.V2).build());
        HoodieIndexMetadata metadata = new HoodieIndexMetadata(indexDefs);
        when(table.getMetaClient()).thenReturn(metaClient);
        when(metaClient.getIndexMetadata()).thenReturn(Option.of(metadata));
        when(metaClient.getTableConfig()).thenReturn(tableConfig);
        Set<String> mdtPartitions = new HashSet<>(indexDefs.keySet());
        when(tableConfig.getMetadataPartitions()).thenReturn(mdtPartitions);
        // Mock write client
        BaseHoodieWriteClient writeClient = mock(BaseHoodieWriteClient.class);
        when(upgradeDowngradeHelper.getWriteClient(config, context)).thenReturn(writeClient);
        // Act
        handler.downgrade(config, context, "20240101120000", upgradeDowngradeHelper);
        // Assert: dropIndex should be called with only index with version v2 or higher.
        ArgumentCaptor<List<String>> argumentCaptor = ArgumentCaptor.forClass(List.class);
        verify(writeClient, times(1)).dropIndex(argumentCaptor.capture());
        List<String> capturedIndexes = argumentCaptor.getValue();
        assertEquals(new HashSet<>(Arrays.asList("secondary_index_v2")), new HashSet<>(capturedIndexes));
    }
}

