@ParameterizedTest
@EnumSource(HoodieTableType.class)
void testOccWithMultipleWriters(HoodieTableType tableType) throws IOException {
    StorageConfiguration<Configuration> storageConf = getDefaultStorageConf();
    final String tableTypeName = tableType.name();
    final String tableName = "hudiTestTable";
    final String basePath = tablePath.toAbsolutePath().toString() + "/" + tableTypeName;
    HoodieTableMetaClient.newTableBuilder().setTableType(tableTypeName).setTableName(tableName).setPayloadClassName(HoodieAvroPayload.class.getName()).setRecordKeyFields("ph").setPartitionFields("id,name").setKeyGeneratorType(KeyGeneratorType.COMPLEX.name()).initTable(storageConf, basePath);
    final Schema schema = SchemaBuilder.record("user").doc("user").namespace("example.avro").fields().name("id").doc("Unique identifier").type().intType().noDefault().name("name").doc("Nome").type().nullable().stringType().stringDefault("Unknown").name("favorite_number").doc("number").type().nullable().intType().intDefault(0).name("favorite_color").doc("color").type().nullable().stringType().stringDefault("Unknown").name("ph").doc("mobile").type().nullable().intType().noDefault().name("entryTs").doc("tiebreaker on duplicates").type().nullable().longType().noDefault().endRecord();
    // The below means we create 20 records with keys ranging from integer values 0-10 to
    // mimic contention. i.e: Each key will be repeated 2 times.
    int recordCountToProduce = 20;
    int range = 10;
    ConcurrentLinkedQueue<HoodieAvroRecord<HoodieAvroPayload>> hoodieAvroRecords = new ConcurrentLinkedQueue<>();
    IntStream intStream = IntStream.range(0, recordCountToProduce);
    intStream.parallel().forEach(i -> {
        try {
            final GenericRecord user = new GenericData.Record(schema);
            user.put("id", i % range);
            user.put("name", "test");
            HoodieAvroPayload record = new HoodieAvroPayload(user, 0);
            final HoodieAvroRecord<HoodieAvroPayload> hoodieAvroRecord = new HoodieAvroRecord<>(new HoodieKey(user.get("id").toString(), createPartitionPath(user)), record);
            hoodieAvroRecords.add(hoodieAvroRecord);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    });
    HoodieWriteConfig cfg = HoodieWriteConfig.newBuilder().withEngineType(EngineType.JAVA).withPath(basePath).withSchema(schema.toString()).forTable(tableName).withIndexConfig(HoodieIndexConfig.newBuilder().withIndexType(HoodieIndex.IndexType.BLOOM).build()).withFileSystemViewConfig(FileSystemViewStorageConfig.newBuilder().withStorageType(FileSystemViewStorageType.MEMORY).build()).withLockConfig(HoodieLockConfig.newBuilder().withLockProvider(FileSystemBasedLockProvider.class).withClientNumRetries(240).withNumRetries(240).withClientRetryWaitTimeInMillis(1000L).build()).withWriteConcurrencyMode(WriteConcurrencyMode.OPTIMISTIC_CONCURRENCY_CONTROL).withCleanConfig(HoodieCleanConfig.newBuilder().withFailedWritesCleaningPolicy(HoodieFailedWritesCleaningPolicy.LAZY).build()).build();
    BlockingQueue<HoodieJavaWriteClient> writerQueue = new LinkedBlockingQueue<>();
    // Number of writers to mock a distributed setup
    int numHudiWriteClients = 3;
    IntStream.range(0, numHudiWriteClients).forEach(i -> {
        HoodieJavaWriteClient writer = new HoodieJavaWriteClient<>(new HoodieJavaEngineContext(storageConf), cfg);
        try {
            writerQueue.put(writer);
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
    });
    hoodieAvroRecords.stream().parallel().forEach(record -> {
        LOGGER.info("Inserting record = {}", record);
        HoodieJavaWriteClient writer;
        LOGGER.info("Entering while loop");
        try {
            writer = writerQueue.take();
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
        String startCommitTime = writer.startCommit();
        List<WriteStatus> s = writer.upsert(Collections.singletonList(record), startCommitTime);
        writer.commit(startCommitTime, s);
        LOGGER.info("Completed commit");
        synchronized (writerQueue) {
            try {
                writerQueue.put(writer);
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
        }
    });
}

