 * Should go back to C2.
 * C3, C4 (RB_C3) should be cleaned up.
 */
@ParameterizedTest
@ValueSource(booleans = { true, false })
void testCleaningRollbackInstants(boolean commitRollback) throws Exception {
    HoodieWriteConfig hoodieWriteConfig = getConfigBuilder(HoodieFailedWritesCleaningPolicy.EAGER).// eager cleaning
    withRollbackUsingMarkers(true).build();
    try (SparkRDDWriteClient client = getHoodieWriteClient(hoodieWriteConfig)) {
        String savepointCommit = null;
        String prevInstant = HoodieTimeline.INIT_INSTANT_TS;
        final int numRecords = 10;
        for (int i = 1; i <= 2; i++) {
            String newCommitTime = WriteClientTestUtils.createNewInstantTime();
            // Write 4 inserts with the 2nd commit been rolled back
            insertBatch(hoodieWriteConfig, client, newCommitTime, prevInstant, numRecords, SparkRDDWriteClient::insert, false, true, numRecords, numRecords * i, 1, Option.empty(), INSTANT_GENERATOR);
            prevInstant = newCommitTime;
            if (i == 2) {
                // trigger savepoint
                savepointCommit = newCommitTime;
                client.savepoint("user1", "Savepoint for 2nd commit");
            }
        }
        assertRowNumberEqualsTo(20);
        // write another pending instant
        insertBatchWithoutCommit(numRecords);
        // rollback the pending instant
        if (commitRollback) {
            client.rollbackFailedWrites(metaClient);
        } else {
            HoodieInstant pendingInstant = metaClient.getActiveTimeline().filterPendingExcludingCompaction().lastInstant().orElseThrow(() -> new HoodieException("Pending instant does not exist"));
            HoodieSparkTable.create(client.getConfig(), context).scheduleRollback(context, WriteClientTestUtils.createNewInstantTime(), pendingInstant, false, true, false);
        }
        Option<String> rollbackInstant = metaClient.reloadActiveTimeline().getRollbackTimeline().lastInstant().map(HoodieInstant::requestedTime);
        assertTrue(rollbackInstant.isPresent(), "The latest instant should be a rollback");
        // write another batch
        insertBatch(hoodieWriteConfig, client, WriteClientTestUtils.createNewInstantTime(), rollbackInstant.get(), numRecords, SparkRDDWriteClient::insert, false, true, numRecords, numRecords * 3, 1, Option.empty(), INSTANT_GENERATOR);
        // restore
        client.restoreToSavepoint(Objects.requireNonNull(savepointCommit, "restore commit should not be null"));
        assertRowNumberEqualsTo(20);
    }
}

