@ValueSource(booleans = { true, false })
public void testSimpleTransactionDirectMarkerBasedDetectionStrategy(boolean partitioned) throws Exception {
    setUp(partitioned);
    final String nextCommitTime1 = "00000000000001";
    final SparkRDDWriteClient client1 = getHoodieWriteClient(config);
    Function2<List<HoodieRecord>, String, Integer> recordGenFunction1 = generateWrapRecordsFn(false, config, dataGen::generateInserts);
    final List<HoodieRecord> records1 = recordGenFunction1.apply(nextCommitTime1, 200);
    final JavaRDD<HoodieRecord> writeRecords1 = jsc.parallelize(records1, 1);
    // Finish first base commit
    WriteClientTestUtils.startCommitWithTime(client1, nextCommitTime1);
    JavaRDD<WriteStatus> writeStatusList1 = client1.insert(writeRecords1, nextCommitTime1);
    assertTrue(client1.commit(nextCommitTime1, writeStatusList1), "Commit should succeed");
    final SparkRDDWriteClient client2 = getHoodieWriteClient(config, true);
    // We do not want to close client2 so setting shouldCloseOlderClient to false while creating client3
    final SparkRDDWriteClient client3 = getHoodieWriteClient(config, false);
    final Function2<List<HoodieRecord>, String, Integer> recordGenFunction2 = generateWrapRecordsFn(false, config, dataGen::generateUniqueUpdates);
    // Prepare update records
    final String nextCommitTime2 = "00000000000002";
    final List<HoodieRecord> records2 = recordGenFunction2.apply(nextCommitTime2, 200);
    final JavaRDD<HoodieRecord> writeRecords2 = jsc.parallelize(records2, 1);
    // start to write commit 002
    WriteClientTestUtils.startCommitWithTime(client2, nextCommitTime2);
    JavaRDD<WriteStatus> writeStatusList2 = client2.upsert(writeRecords2, nextCommitTime2);
    assertNoWriteErrors(writeStatusList2.collect());
    // start to write commit 003
    // this commit 003 will failed quickly because early conflict detection before create marker.
    final String nextCommitTime3 = "00000000000003";
    assertThrows(SparkException.class, () -> {
        final List<HoodieRecord> records3 = recordGenFunction2.apply(nextCommitTime3, 200);
        final JavaRDD<HoodieRecord> writeRecords3 = jsc.parallelize(records3, 1);
        WriteClientTestUtils.startCommitWithTime(client3, nextCommitTime3);
        JavaRDD<WriteStatus> writeStatusList3 = client3.upsert(writeRecords3, nextCommitTime3);
        client3.commit(nextCommitTime3, writeStatusList3);
    }, "Early conflict detected but cannot resolve conflicts for overlapping writes");
    // start to commit 002 and success
    assertDoesNotThrow(() -> {
        client2.commit(nextCommitTime2, writeStatusList2);
    });
    client2.close();
    client3.close();
}

@Test
public void testPartitioner() {
    List<HoodieRecord> records = new ArrayList<>();
    BiConsumer<String, Integer> initRecords = (fileGroupId, count) -> {
        while (count-- > 0) {
            HoodieRecord r = HoodieMetadataPayload.createPartitionListRecord(Collections.EMPTY_LIST);
            r.unseal();
            r.setCurrentLocation(new HoodieRecordLocation("001", fileGroupId));
            r.seal();
            records.add(r);
        }
    };
    // Assume there are 5 fileGroups in MDT partition FILES.
    initRecords.accept(MetadataPartitionType.FILES.getFileIdPrefix() + "000", 3);
    initRecords.accept(MetadataPartitionType.FILES.getFileIdPrefix() + "001", 5);
    initRecords.accept(MetadataPartitionType.FILES.getFileIdPrefix() + "002", 7);
    // Intentionally skipping fileGroup 003
    initRecords.accept(MetadataPartitionType.FILES.getFileIdPrefix() + "004", 9);
    // repeated fileGroups
    initRecords.accept(MetadataPartitionType.FILES.getFileIdPrefix() + "002", 11);
    SparkHoodieMetadataBulkInsertPartitioner partitioner = new SparkHoodieMetadataBulkInsertPartitioner(new DefaultMetadataTableFileGroupIndexParser(5));
    JavaRDD<HoodieRecord> partitionedRecords = partitioner.repartitionRecords(jsc().parallelize(records, records.size()), 0);
    // Only 5 partitions should be there corresponding to 5 unique fileGroups in MDT
    assertEquals(5, partitionedRecords.getNumPartitions(), "Only 5 partitions should be there corresponding to 3 unique fileGroups in MDT");
    // Records must be sorted as we are writing to HFile
    assertTrue(partitioner.arePartitionRecordsSorted(), "Must be sorted");
    // Each partition should only have records for a single fileGroup
    partitionedRecords.foreachPartition(recordIterator -> {
        HoodieRecordLocation location = null;
        while (recordIterator.hasNext()) {
            HoodieRecord record = recordIterator.next();
            HoodieRecordLocation recordLocation = record.getCurrentLocation();
            if (location == null) {
                location = recordLocation;
            } else {
                assertEquals(recordLocation, location, "Records should have the same location in a partition");
            }
        }
    });
    // Record count should match
    assertEquals(records.size(), partitionedRecords.count(), "Record count should match");
    // Number of records in each partition should be correct
    Map<String, Integer> recordsPerFileGroup = partitionedRecords.mapToPair(r -> new Tuple2<>(r.getCurrentLocation().getFileId(), 1)).reduceByKey(Integer::sum).collectAsMap();
    assertEquals(3, recordsPerFileGroup.get(MetadataPartitionType.FILES.getFileIdPrefix() + "000"), "Number of records in each partition should be correct");
    assertEquals(5, recordsPerFileGroup.get(MetadataPartitionType.FILES.getFileIdPrefix() + "001"), "Number of records in each partition should be correct");
    assertEquals(7 + 11, recordsPerFileGroup.get(MetadataPartitionType.FILES.getFileIdPrefix() + "002"), "Number of records in each partition should be correct");
    assertEquals(9, recordsPerFileGroup.get(MetadataPartitionType.FILES.getFileIdPrefix() + "004"), "Number of records in each partition should be correct");
    assertEquals(-1, recordsPerFileGroup.getOrDefault(MetadataPartitionType.FILES.getFileIdPrefix() + "003", -1), "No records in skipped file group");
    // fileIDPrefixes should match the name of the MDT fileGroups
    Set<String> fileIDPrefixes = IntStream.of(0, 1, 2, 4).mapToObj(partitioner::getFileIdPfx).collect(Collectors.toSet());
    assertEquals(fileIDPrefixes, recordsPerFileGroup.keySet(), "fileIDPrefixes should match the name of the MDT fileGroups");
}

@Test
public void testWritesViaMetadataWriteClient() throws Exception {
    HoodieWriteConfig hoodieWriteConfig = getConfigBuilder().withMetadataConfig(HoodieMetadataConfig.newBuilder().enable(true).withMetadataIndexColumnStats(false).withEnableRecordIndex(true).withRecordIndexFileGroupCount(1, 1).withStreamingWriteEnabled(true).build()).build();
    // trigger end to end write to data table so that metadata table is also initialized.
    initDataTableWithACommit(hoodieWriteConfig);
    // fetch metadata file slice info
    HoodieWriteConfig mdtWriteConfig = HoodieMetadataWriteUtils.createMetadataWriteConfig(hoodieWriteConfig, HoodieFailedWritesCleaningPolicy.EAGER, HoodieTableVersion.EIGHT);
    Map<String, List<String>> mdtPartitionsFileIdMapping = new HashMap<>();
    List<HoodieFileGroupId> nonFilesPartitionFileGroupIdList = new ArrayList<>();
    List<HoodieFileGroupId> filesPartitionFileGroupIdList = new ArrayList<>();
    HoodieTableMetaClient metadataMetaClient = HoodieTableMetaClient.builder().setBasePath(mdtWriteConfig.getBasePath()).setConf(context.getStorageConf()).build();
    fetchMetadataFileSliceInfo(metadataMetaClient, filesPartitionFileGroupIdList, nonFilesPartitionFileGroupIdList, mdtPartitionsFileIdMapping);
    List<HoodieRecord> filesPartitionExpectedRecords = new ArrayList<>();
    Map<String, HoodieRecord> filesPartitionExpectedRecordsMap = new HashMap<>();
    List<String> expectedAllPartitions = new ArrayList<>();
    List<HoodieRecord> rliRecords = new ArrayList<>();
    Map<String, HoodieRecord> rliPartitionExpectedRecordsMap = new HashMap<>();
    String commitTimeOfInterest = null;
    // create Write client to SparkRDDMetadataWriteClient and trigger writes.
    try (SparkRDDMetadataWriteClient client = new SparkRDDMetadataWriteClient(context, mdtWriteConfig)) {
        commitTimeOfInterest = WriteClientTestUtils.createNewInstantTime();
        // prepare FILES partition records.
        prepareFilesPartitionRecords(mdtPartitionsFileIdMapping.get(MetadataPartitionType.FILES.getPartitionPath()).get(0), commitTimeOfInterest, filesPartitionExpectedRecords, filesPartitionExpectedRecordsMap, expectedAllPartitions);
        // prepare RLI records.
        prepareRliRecords(commitTimeOfInterest, mdtPartitionsFileIdMapping, expectedAllPartitions, rliRecords, rliPartitionExpectedRecordsMap);
        // ingest RLI records to metadata table.
        client.startCommitForMetadataTable(metadataMetaClient, commitTimeOfInterest, DELTA_COMMIT_ACTION);
        JavaRDD<WriteStatus> partialWriteStatusesRDD = client.firstUpsertPreppedRecords(jsc.parallelize(rliRecords), commitTimeOfInterest, nonFilesPartitionFileGroupIdList);
        List<WriteStatus> partialWriteStatuses = partialWriteStatusesRDD.collect();
        // assert that isMetadataTable is rightly set
        partialWriteStatuses.forEach(writeStatus -> assertTrue(writeStatus.isMetadataTable()));
        // validate that the commit is still pending since we are streaming write to metadata table.
        HoodieActiveTimeline reloadedMdtActiveTimeline = metadataMetaClient.reloadActiveTimeline();
        // files, rli instantiaton and 1 write to data table.
        assertEquals(reloadedMdtActiveTimeline.filterCompletedInstants().getInstants().stream().count(), 3);
        String finalCommitTimeOfInterest = commitTimeOfInterest;
        assertTrue(reloadedMdtActiveTimeline.filterInflightsAndRequested().getInstants().stream().anyMatch(instant -> instant.requestedTime().equals(finalCommitTimeOfInterest)));
        // write to FILES partition
        JavaRDD<WriteStatus> filePartitionWriteStatusesRDD = client.secondaryUpsertPreppedRecords(jsc.parallelize(filesPartitionExpectedRecords), commitTimeOfInterest);
        List<WriteStatus> filesPartitionWriteStatus = filePartitionWriteStatusesRDD.collect();
        // assert that isMetadataTable is rightly set
        filesPartitionWriteStatus.forEach(writeStatus -> assertTrue(writeStatus.isMetadataTable()));
        List<HoodieWriteStat> allWriteStats = new ArrayList<>();
        allWriteStats.addAll(partialWriteStatuses.stream().map(writeStatus -> writeStatus.getStat()).collect(Collectors.toList()));
        allWriteStats.addAll(filesPartitionWriteStatus.stream().map(writeStatus -> writeStatus.getStat()).collect(Collectors.toList()));
        client.commitStats(commitTimeOfInterest, allWriteStats, Option.empty(), DELTA_COMMIT_ACTION);
    }
    // validate
    readFromMetadataTableAndValidateRecords(metadataMetaClient, hoodieWriteConfig, filesPartitionExpectedRecordsMap, rliPartitionExpectedRecordsMap, commitTimeOfInterest);
}

