void testWriteClientReleaseResourcesShouldOnlyUnpersistRelevantRdds(HoodieTableType tableType, boolean shouldReleaseResource, boolean metadataTableEnable) throws IOException {
    final HoodieTableMetaClient metaClient = getHoodieMetaClient(storageConf(), URI.create(basePath()).getPath(), tableType, new Properties());
    final HoodieWriteConfig writeConfig = getConfigBuilder(true).withPath(metaClient.getBasePath()).withReleaseResourceEnabled(shouldReleaseResource).withMetadataConfig(HoodieMetadataConfig.newBuilder().enable(metadataTableEnable).build()).build();
    HoodieTestDataGenerator dataGen = new HoodieTestDataGenerator(0xDEED);
    String instant0 = getCommitTimeAtUTC(0);
    List<GenericRecord> extraRecords0 = dataGen.generateGenericRecords(10);
    HoodieJavaRDD<GenericRecord> persistedRdd0 = HoodieJavaRDD.of(jsc().parallelize(extraRecords0, 2));
    persistedRdd0.persist("MEMORY_AND_DISK", context(), HoodieDataCacheKey.of(writeConfig.getBasePath(), instant0));
    String instant1 = getCommitTimeAtUTC(1);
    List<GenericRecord> extraRecords1 = dataGen.generateGenericRecords(10);
    HoodieJavaRDD<GenericRecord> persistedRdd1 = HoodieJavaRDD.of(jsc().parallelize(extraRecords1, 2));
    persistedRdd1.persist("MEMORY_AND_DISK", context(), HoodieDataCacheKey.of(writeConfig.getBasePath(), instant1));
    SparkRDDWriteClient writeClient = getHoodieWriteClient(writeConfig);
    List<HoodieRecord> records = dataGen.generateInserts(instant1, 10);
    JavaRDD<HoodieRecord> writeRecords = jsc().parallelize(records, 2);
    WriteClientTestUtils.startCommitWithTime(writeClient, instant1);
    List<WriteStatus> writeStatuses = writeClient.insert(writeRecords, instant1).collect();
    assertNoWriteErrors(writeStatuses);
    String metadataTableBasePath = HoodieTableMetadata.getMetadataTableBasePath(writeConfig.getBasePath());
    List<Integer> metadataTableCacheIds0 = context().getCachedDataIds(HoodieDataCacheKey.of(metadataTableBasePath, instant0));
    List<Integer> metadataTableCacheIds1 = context().getCachedDataIds(HoodieDataCacheKey.of(metadataTableBasePath, instant1));
    writeClient.commitStats(instant1, writeStatuses.stream().map(WriteStatus::getStat).collect(Collectors.toList()), Option.empty(), metaClient.getCommitActionType());
    writeClient.close();
    if (shouldReleaseResource) {
        assertEquals(Collections.singletonList(persistedRdd0.getId()), context().getCachedDataIds(HoodieDataCacheKey.of(writeConfig.getBasePath(), instant0)), "RDDs cached for " + instant0 + " should be retained.");
        assertEquals(Collections.emptyList(), context().getCachedDataIds(HoodieDataCacheKey.of(writeConfig.getBasePath(), instant1)), "RDDs cached for " + instant1 + " should be cleared.");
        assertTrue(jsc().getPersistentRDDs().containsKey(persistedRdd0.getId()), "RDDs cached for " + instant0 + " should be retained.");
        assertFalse(jsc().getPersistentRDDs().containsKey(persistedRdd1.getId()), "RDDs cached for " + instant1 + " should be cleared.");
        assertFalse(jsc().getPersistentRDDs().containsKey(writeRecords.id()), "RDDs cached for " + instant1 + " should be cleared.");
        if (metadataTableEnable) {
            assertEquals(metadataTableCacheIds0.stream().sorted().collect(Collectors.toList()), context().getCachedDataIds(HoodieDataCacheKey.of(metadataTableBasePath, instant0)).stream().sorted().collect(Collectors.toList()), "RDDs cached for metadataTable " + instant0 + " should be retained.");
            assertEquals(Collections.emptyList(), context().getCachedDataIds(HoodieDataCacheKey.of(metadataTableBasePath, instant1)), "RDDs cached for metadataTable " + instant1 + " should be cleared.");
            metadataTableCacheIds0.forEach(cacheId -> assertTrue(jsc().getPersistentRDDs().containsKey(cacheId), "RDDs cached for metadataTable cacheId " + cacheId + " should be retained."));
            metadataTableCacheIds1.forEach(cacheId -> assertFalse(jsc().getPersistentRDDs().containsKey(cacheId), "RDDs cached for metadataTable cacheId " + cacheId + " should be cleared."));
        }
    } else {
        assertEquals(Collections.singletonList(persistedRdd0.getId()), context().getCachedDataIds(HoodieDataCacheKey.of(writeConfig.getBasePath(), instant0)), "RDDs cached for " + instant0 + " should be retained.");
        assertEquals(3, context().getCachedDataIds(HoodieDataCacheKey.of(writeConfig.getBasePath(), instant1)).size(), "RDDs cached for " + instant1 + " should be retained.");
        assertTrue(jsc().getPersistentRDDs().containsKey(persistedRdd0.getId()), "RDDs cached for " + instant0 + " should be retained.");
        assertTrue(jsc().getPersistentRDDs().containsKey(persistedRdd1.getId()), "RDDs cached for " + instant1 + " should be retained.");
        assertTrue(jsc().getPersistentRDDs().containsKey(writeRecords.id()), "RDDs cached for " + instant1 + " should be retained.");
        if (metadataTableEnable) {
            metadataTableCacheIds0.forEach(cacheId -> assertTrue(jsc().getPersistentRDDs().containsKey(cacheId), "RDDs cached for metadataTable cacheId " + cacheId + " should be retained."));
            metadataTableCacheIds1.forEach(cacheId -> assertTrue(jsc().getPersistentRDDs().containsKey(cacheId), "RDDs cached for metadataTable cacheId " + cacheId + " should be retained."));
        }
    }
}

