@ParameterizedTest
@ValueSource(booleans = { true, false })
public void testTagLocation(boolean isInsert) throws Exception {
    String rowKey1 = UUID.randomUUID().toString();
    String rowKey2 = UUID.randomUUID().toString();
    String rowKey3 = UUID.randomUUID().toString();
    HoodieRecord<IndexedRecord> record1 = createSimpleRecord(rowKey1, "2016-01-31T03:16:41.415Z", 12);
    HoodieRecord<IndexedRecord> record2 = createSimpleRecord(rowKey2, "2016-01-31T03:20:41.415Z", 100);
    HoodieRecord<IndexedRecord> record3 = createSimpleRecord(rowKey3, "2016-01-31T03:16:41.415Z", 15);
    HoodieRecord<IndexedRecord> record4 = createSimpleRecord(rowKey1, "2015-01-31T03:16:41.415Z", 32);
    JavaRDD<HoodieRecord<IndexedRecord>> recordRDD = jsc.parallelize(Arrays.asList(record1, record2, record3, record4));
    HoodieWriteConfig config = makeConfig();
    HoodieTable table = HoodieSparkTable.create(config, context, metaClient);
    HoodieSimpleBucketIndex bucketIndex = new HoodieSimpleBucketIndex(config);
    HoodieData<HoodieRecord<IndexedRecord>> taggedRecordRDD = bucketIndex.tagLocation(HoodieJavaRDD.of(recordRDD), context, table);
    assertFalse(taggedRecordRDD.collectAsList().stream().anyMatch(r -> r.isCurrentLocationKnown()));
    HoodieSparkWriteableTestTable testTable = HoodieSparkWriteableTestTable.of(table, SCHEMA);
    if (isInsert) {
        testTable.addCommit("001").withInserts("2016/01/31", getRecordFileId(record1), record1);
        testTable.addCommit("002").withInserts("2016/01/31", getRecordFileId(record2), record2);
        testTable.addCommit("003").withInserts("2016/01/31", getRecordFileId(record3), record3);
    } else {
        testTable.addCommit("001").withLogAppends("2016/01/31", getRecordFileId(record1), record1);
        testTable.addCommit("002").withLogAppends("2016/01/31", getRecordFileId(record2), record2);
        testTable.addCommit("003").withLogAppends("2016/01/31", getRecordFileId(record3), record3);
    }
    taggedRecordRDD = bucketIndex.tagLocation(HoodieJavaRDD.of(recordRDD), context, HoodieSparkTable.create(config, context, metaClient));
    assertFalse(taggedRecordRDD.collectAsList().stream().filter(r -> r.isCurrentLocationKnown()).filter(r -> BucketIdentifier.bucketIdFromFileId(r.getCurrentLocation().getFileId()) != getRecordBucketId(r)).findAny().isPresent());
    assertTrue(taggedRecordRDD.collectAsList().stream().filter(r -> r.getPartitionPath().equals("2015/01/31") && !r.isCurrentLocationKnown()).count() == 1L);
    assertTrue(taggedRecordRDD.collectAsList().stream().filter(r -> r.getPartitionPath().equals("2016/01/31") && r.isCurrentLocationKnown()).count() == 3L);
}

@Test
public void testYearFunction() {
    // Create a test DataFrame
    Dataset<Row> df = sparkSession.createDataFrame(Arrays.asList(RowFactory.create(Timestamp.valueOf("2021-03-15 12:34:56")), RowFactory.create(Timestamp.valueOf("2022-07-10 23:45:01"))), DataTypes.createStructType(Arrays.asList(DataTypes.createStructField("timestampColumn", DataTypes.TimestampType, false))));
    // Register the DataFrame as a temp view so we can query it
    df.createOrReplaceTempView("testData");
    // Initialize the HoodieSparkExpressionIndex with the year function
    String mdtPartitionName = "expr_index_yearIndex";
    HoodieIndexDefinition indexDefinition = HoodieIndexDefinition.newBuilder().withIndexName(mdtPartitionName).withIndexFunction("year").withIndexType(PARTITION_NAME_COLUMN_STATS).withVersion(HoodieIndexVersion.getCurrentVersion(HoodieTableVersion.current(), mdtPartitionName)).withSourceFields(Arrays.asList("timestampColumn")).withIndexOptions(new HashMap<>()).build();
    HoodieSparkExpressionIndex index = new HoodieSparkExpressionIndex(indexDefinition);
    // Apply the function using the index
    Column yearColumn = index.apply(Arrays.asList(col("timestampColumn")));
    // Add the result as a new column to the DataFrame
    Dataset<Row> resultDf = df.withColumn("year", yearColumn);
    // Collect and assert the results
    List<Row> results = resultDf.select("year").collectAsList();
    assertEquals("2021", results.get(0).getAs("year").toString());
    assertEquals("2022", results.get(1).getAs("year").toString());
}

