@ParameterizedTest
@ValueSource(booleans = { true, false })
public void testPartitionMetafileFormat(boolean partitionMetafileUseBaseFormat) throws Exception {
    // By default there is no format specified for partition metafile
    HoodieWriteConfig config = HoodieWriteConfig.newBuilder().withPath(basePath).withSchema(TRIP_EXAMPLE_SCHEMA).build();
    HoodieSparkCopyOnWriteTable table = (HoodieSparkCopyOnWriteTable) HoodieSparkTable.create(config, context, metaClient);
    assertFalse(table.getPartitionMetafileFormat().isPresent());
    if (partitionMetafileUseBaseFormat) {
        // Add the setting to use datafile format
        Properties properties = new Properties();
        properties.setProperty(HoodieTableConfig.PARTITION_METAFILE_USE_BASE_FORMAT.key(), "true");
        initMetaClient(HoodieTableType.COPY_ON_WRITE, properties);
        metaClient = HoodieTableMetaClient.reload(metaClient);
        assertTrue(metaClient.getTableConfig().getPartitionMetafileFormat().isPresent());
        table = (HoodieSparkCopyOnWriteTable) HoodieSparkTable.create(config, context, metaClient);
        assertTrue(table.getPartitionMetafileFormat().isPresent());
    }
    SparkRDDWriteClient writeClient = getHoodieWriteClient(config);
    String instantTime = writeClient.startCommit();
    // Insert new records
    final JavaRDD<HoodieRecord> inputRecords = generateTestRecordsForBulkInsert(jsc, 50);
    JavaRDD<WriteStatus> writeStatusJavaRDD = writeClient.bulkInsert(inputRecords, instantTime);
    writeClient.commit(instantTime, writeStatusJavaRDD, Option.empty(), COMMIT_ACTION, Collections.emptyMap(), Option.empty());
    // Partition metafile should be created
    StoragePath partitionPath = new StoragePath(basePath, HoodieTestDataGenerator.DEFAULT_FIRST_PARTITION_PATH);
    assertTrue(HoodiePartitionMetadata.hasPartitionMetadata(storage, partitionPath));
    Option<StoragePath> metafilePath = HoodiePartitionMetadata.getPartitionMetafilePath(storage, partitionPath);
    if (partitionMetafileUseBaseFormat) {
        // Extension should be the same as the data file format of the table
        assertTrue(metafilePath.get().toString().endsWith(table.getBaseFileExtension()));
    } else {
        // No extension as it is in properties file format
        assertTrue(metafilePath.get().toString().endsWith(HoodiePartitionMetadata.HOODIE_PARTITION_METAFILE_PREFIX));
    }
    // Validate contents of the partition metafile
    HoodiePartitionMetadata partitionMetadata = new HoodiePartitionMetadata(storage, partitionPath);
    partitionMetadata.readFromFS();
    assertTrue(partitionMetadata.getPartitionDepth() == 3);
    assertTrue(partitionMetadata.readPartitionCreatedCommitTime().get().equals(instantTime));
}

@Test
public void testMetadataTableUpsertCommitActionExecutor() throws IOException {
    HoodieTableMetaClient metaClient = getHoodieMetaClient(HoodieTableType.MERGE_ON_READ);
    HoodieWriteConfig writeConfig = getConfigBuilder(false).build();
    HoodieTable table = HoodieSparkTable.create(writeConfig, context(), metaClient);
    HoodieTestDataGenerator dataGen = new HoodieTestDataGenerator();
    List<HoodieRecord> records = dataGen.generateInserts("0001", 100);
    HoodieData<HoodieRecord> recordHoodieData = context().parallelize(records, 1);
    List<HoodieFileGroupId> hoodieFileGroupIdList = new ArrayList<>();
    hoodieFileGroupIdList.add(new HoodieFileGroupId(MetadataPartitionType.RECORD_INDEX.getPartitionPath(), "record-index-00001"));
    HoodieData<WriteStatus> statusHoodieData = mock(HoodieData.class);
    // create requested in timeline
    metaClient.getActiveTimeline().createNewInstant(metaClient.createNewInstant(HoodieInstant.State.REQUESTED, DELTA_COMMIT_ACTION, "0001"));
    BaseSparkCommitActionExecutor commitActionExecutor = new MockSparkMetadataTableFirstDeltaCommitActionExecutor(context(), writeConfig, table, "0001", recordHoodieData, hoodieFileGroupIdList, statusHoodieData);
    commitActionExecutor.execute(recordHoodieData);
    // since this is initial call, inflight instant should be added.
    assertTrue(metaClient.reloadActiveTimeline().getWriteTimeline().filterInflights().containsInstant("0001"));
    hoodieFileGroupIdList.clear();
    hoodieFileGroupIdList.add(new HoodieFileGroupId(MetadataPartitionType.FILES.getPartitionPath(), "files-00001"));
