@Test
void testComparingPrimitiveTypes() {
    // Tests comparison of all primitive Avro types against each other
    // Validates that each primitive type is equal only to other avro schema sharing the same
    // primitive type.
    Schema.Type[] primitiveTypes = { Schema.Type.NULL, Schema.Type.BOOLEAN, Schema.Type.INT, Schema.Type.LONG, Schema.Type.FLOAT, Schema.Type.DOUBLE, Schema.Type.BYTES, Schema.Type.STRING };
    for (Schema.Type primitiveType : primitiveTypes) {
        for (Schema.Type type : primitiveTypes) {
            if (primitiveType == type) {
                assertTrue(AvroSchemaComparatorForSchemaEvolution.schemaEquals(Schema.create(primitiveType), Schema.create(type)));
            } else {
                assertFalse(AvroSchemaComparatorForSchemaEvolution.schemaEquals(Schema.create(primitiveType), Schema.create(type)), String.format("Types %s and %s should not be equal", primitiveType, type));
            }
        }
    }
}

