@ParameterizedTest
@MethodSource("javaValueParams")
public void testWrapAndUnwrapJavaValues(Comparable value, Class expectedWrapper) {
    Object wrapperValue = wrapValueIntoAvro(value);
    assertTrue(expectedWrapper.isInstance(wrapperValue));
    if (value instanceof Timestamp) {
        assertEquals(((Timestamp) value).getTime() * 1000L, ((GenericRecord) wrapperValue).get(0));
        assertEquals(((Timestamp) value).getTime(), ((Timestamp) unwrapAvroValueWrapper(wrapperValue)).getTime());
    } else if (value instanceof Date) {
        assertEquals((int) ChronoUnit.DAYS.between(LocalDate.ofEpochDay(0), ((Date) value).toLocalDate()), ((GenericRecord) wrapperValue).get(0));
        assertEquals(((Date) value).toString(), ((Date) unwrapAvroValueWrapper(wrapperValue)).toString());
    } else if (value instanceof LocalDate) {
        assertEquals((int) ChronoUnit.DAYS.between(LocalDate.ofEpochDay(0), (LocalDate) value), ((GenericRecord) wrapperValue).get(0));
        assertEquals(value, unwrapAvroValueWrapper(wrapperValue));
    } else {
        assertEquals("0.000000000000000", ((BigDecimal) value).subtract((BigDecimal) unwrapAvroValueWrapper(wrapperValue)).toPlainString());
    }
}

