@ParameterizedTest
@EnumSource(value = ExternalSpillableMap.DiskMapType.class)
public void testSpillableMapUsage(ExternalSpillableMap.DiskMapType diskMapType) throws Exception {
    Map<String, String> writeConfigs = new HashMap<>(getCommonConfigs(RecordMergeMode.COMMIT_TIME_ORDERING, true));
    try (HoodieTestDataGenerator dataGen = new HoodieTestDataGenerator(0xDEEF)) {
        List<HoodieRecord> recordList = dataGen.generateInserts("001", 100);
        long timestamp = (long) ((GenericRecord) recordList.get(0).getData()).get("timestamp");
        commitToTable(recordList, INSERT.value(), true, writeConfigs);
        String baseMapPath = Files.createTempDirectory(null).toString();
        HoodieTableMetaClient metaClient = HoodieTestUtils.createMetaClient(getStorageConf(), getBasePath());
        Schema avroSchema = new TableSchemaResolver(metaClient).getTableAvroSchema();
        List<FileSlice> fileSlices = getFileSlicesToRead(getStorageConf(), getBasePath(), metaClient, true, 0);
        List<T> records = readRecordsFromFileGroup(getStorageConf(), getBasePath(), metaClient, fileSlices, avroSchema, RecordMergeMode.COMMIT_TIME_ORDERING, false, false);
        HoodieReaderContext<T> readerContext = getHoodieReaderContext(getBasePath(), avroSchema, getStorageConf(), metaClient);
        for (Boolean isCompressionEnabled : new boolean[] { true, false }) {
            try (ExternalSpillableMap<Serializable, BufferedRecord<T>> spillableMap = new ExternalSpillableMap<>(16L, baseMapPath, new DefaultSizeEstimator(), new HoodieRecordSizeEstimator(avroSchema), diskMapType, new DefaultSerializer<>(), isCompressionEnabled, getClass().getSimpleName())) {
                Long position = 0L;
                for (T record : records) {
                    String recordKey = readerContext.getRecordContext().getRecordKey(record, avroSchema);
                    //test key based
                    BufferedRecord<T> bufferedRecord = BufferedRecords.fromEngineRecord(record, avroSchema, readerContext.getRecordContext(), Collections.singletonList("timestamp"), false);
                    spillableMap.put(recordKey, bufferedRecord.toBinary(readerContext.getRecordContext()));
                    //test position based
                    spillableMap.put(position++, bufferedRecord.toBinary(readerContext.getRecordContext()));
                }
                assertEquals(records.size() * 2, spillableMap.size());
                //Validate that everything is correct
                position = 0L;
                for (T record : records) {
                    String recordKey = readerContext.getRecordContext().getRecordKey(record, avroSchema);
                    BufferedRecord<T> keyBased = spillableMap.get(recordKey);
                    assertNotNull(keyBased);
                    BufferedRecord<T> positionBased = spillableMap.get(position++);
                    assertNotNull(positionBased);
                    assertRecordsEqual(avroSchema, record, keyBased.getRecord());
                    assertRecordsEqual(avroSchema, record, positionBased.getRecord());
                    assertEquals(keyBased.getRecordKey(), recordKey);
                    assertEquals(positionBased.getRecordKey(), recordKey);
                    assertEquals(avroSchema, readerContext.getRecordContext().getSchemaFromBufferRecord(keyBased));
                    assertEquals(readerContext.getRecordContext().convertValueToEngineType(timestamp), positionBased.getOrderingValue());
                }
            }
        }
    }
}

@Test
public void testCowBootstrapWithPositionMerge() {
    when(hoodieTableConfig.populateMetaFields()).thenReturn(true);
    HoodieReaderContext<String> readerContext = createReaderContext(hoodieTableConfig, true, false, true, false, null);
    Schema requestedSchema = generateProjectionSchema("begin_lat", "tip_history", "_hoodie_record_key", "rider");
    FileGroupReaderSchemaHandler schemaHandler = createSchemaHandler(readerContext, DATA_SCHEMA, requestedSchema, true);
    assertTrue(readerContext.getNeedsBootstrapMerge());
    //meta cols must go first in the required schema
    Schema expectedRequiredSchema = generateProjectionSchema("_hoodie_record_key", "begin_lat", "tip_history", "rider");
    assertEquals(expectedRequiredSchema, schemaHandler.getRequiredSchema());
    Pair<List<Schema.Field>, List<Schema.Field>> bootstrapFields = schemaHandler.getBootstrapRequiredFields();
    assertEquals(Arrays.asList(getField("_hoodie_record_key"), getPositionalMergeField()), bootstrapFields.getLeft());
    assertEquals(Arrays.asList(getField("begin_lat"), getField("tip_history"), getField("rider"), getPositionalMergeField()), bootstrapFields.getRight());
    schemaHandler = createSchemaHandler(readerContext, DATA_SCHEMA, DATA_COLS_ONLY_SCHEMA, true);
    assertFalse(readerContext.getNeedsBootstrapMerge());
    assertEquals(DATA_COLS_ONLY_SCHEMA, schemaHandler.getRequiredSchema());
    bootstrapFields = schemaHandler.getBootstrapRequiredFields();
    assertTrue(bootstrapFields.getLeft().isEmpty());
    assertEquals(Arrays.asList(getField("begin_lat"), getField("tip_history"), getField("rider")), bootstrapFields.getRight());
    schemaHandler = createSchemaHandler(readerContext, DATA_SCHEMA, META_COLS_ONLY_SCHEMA, true);
    assertFalse(readerContext.getNeedsBootstrapMerge());
    assertEquals(META_COLS_ONLY_SCHEMA, schemaHandler.getRequiredSchema());
    bootstrapFields = schemaHandler.getBootstrapRequiredFields();
    assertEquals(Arrays.asList(getField("_hoodie_commit_seqno"), getField("_hoodie_record_key")), bootstrapFields.getLeft());
    assertTrue(bootstrapFields.getRight().isEmpty());
}

