@Test
public void testSubtaskFails() throws Exception {
    conf.set(FlinkOptions.WRITE_COMMIT_ACK_TIMEOUT, 1L);
    // open the function and ingest data
    preparePipeline().checkpoint(1).assertEmptyEvent().subTaskFails(0).assertInstantRecommit().// write a commit and check the result
    consume(TestData.DATA_SET_INSERT).checkpoint(2).assertNextEvent().checkpointComplete(2).checkWrittenData(EXPECTED1).// triggers task 0 failover, there is no pending instant that needs to recommit,
    // the task sends an empty bootstrap event to trigger cleaning of legacy events.
    subTaskFails(0, 1).assertEmptyEvent().checkpoint(3).assertEmptyEvent().// 1. triggers a new checkpoint;
    // 2. triggers task 0 failover, there is no pending instant that needs to recommit,
    // the task sends an empty bootstrap event to trigger cleaning of legacy events;
    // 3. triggers a checkpoint ack to simulate a following-up checkpoint success,
    // the handling of the checkpoint ack event would recommit 3.
    subTaskFails(0, 2).assertEmptyEvent().checkpointComplete(4).checkCompletedInstantCount(3).// rollback the last complete instant to inflight state, to simulate an instant commit failure
    // while executing the post action of a checkpoint success notification event, the whole job should then
    // trigger a failover.
    rollbackLastCompleteInstantToInflight().jobFailover().assertNextEvent().// another checkpoint ack event would trigger the recommit of restored instant.
    checkLastPendingInstantCompleted().end();
}

