// Only when Job level fails with INSERT operationType can we roll back the unfinished instant.
// Task level failed retry, we should reuse the unfinished Instant with INSERT operationType
@Test
public void testPartialFailover() throws Exception {
    conf.set(FlinkOptions.WRITE_COMMIT_ACK_TIMEOUT, 1L);
    conf.set(FlinkOptions.OPERATION, "INSERT");
    // open the function and ingest data
    preparePipeline().// triggers subtask failure for multiple times to simulate partial failover, for partial over,
    // a metadata event should be sent to override the corrupt metadata on coordinator
    subTaskFails(0, 1).assertEmptyEvent().// the subtask reuses the pending instant
    checkpoint(3).assertNextEvent().// if the write task can not fetch any pending instant when starts up(the coordinator restarts),
    // it will send an event to the coordinator
    restartCoordinator().subTaskFails(0, 2).assertEmptyEvent().// the subtask can still fetch the instant to write, an instant request is issued during checkpoint
    checkpoint(4).assertNextEvent().subTaskFails(0, 3).// the last checkpoint instant was not rolled back by subTaskFails(0, 2)
    // with LAZY cleaning strategy
    assertEmptyEvent().checkpoint(5).assertNextEvent().subTaskFails(0, 4).// the last checkpoint instant can not be rolled back by subTaskFails(0, 4) with INSERT write operationType
    // because last data has been snapshot by checkpoint complete but instant has not been committed
    // so we need recommit it
    assertEmptyEvent().end();
}

