    expected.put("par1", "[id1,par1,id1,Danny,23,1,par1]");
    TestHarness testHarness = preparePipeline().consume(TestData.DATA_SET_INSERT_DUPLICATES).assertDataBuffer(1, 2).checkpoint(1).allDataFlushed().handleEvents(2);
    Thread t1 = new Thread(() -> {
        try {
            Thread.sleep(3000);
            testHarness.checkpointComplete(1);
            testHarness.checkWrittenData(expected, 1);
        } catch (Exception e) {
            throw new HoodieException(e);
        }
    });
    t1.start();
    testHarness.// new records coming and flushing while cp1 is not completed yet,
    // bucket assign function will upsert(U) new records to previous fg stored in state.
    // If async instant generation is used , HoodieMergedHandle will either throw exception
    // or get the wrong base file in the file group, since cp1 is not committed yet.
    consume(TestData.DATA_SET_INSERT_DUPLICATES).consume(TestData.DATA_SET_INSERT).checkpoint(2).allDataFlushed();
    t1.join();
    testHarness.handleEvents(3).checkpointComplete(2).checkWrittenData(EXPECTED1, 4).end();
}

