    HoodieTimeline commitsTimeline = metaClient.reloadActiveTimeline().getCommitsTimeline().filterCompletedInstants();
    List<HoodieInstant> instants = commitsTimeline.getInstants();
    String lastInstant = commitsTimeline.lastInstant().map(HoodieInstant::requestedTime).get();
    List<HoodieCommitMetadata> metadataList = instants.stream().map(instant -> WriteProfiles.getCommitMetadata(tableName, new Path(basePath), instant, commitsTimeline)).collect(Collectors.toList());
    List<StoragePathInfo> pathInfoList = WriteProfiles.getFilesFromMetadata(new Path(basePath), (org.apache.hadoop.conf.Configuration) metaClient.getStorageConf().unwrap(), metadataList, metaClient.getTableType());
    HoodieTableFileSystemView fileSystemView = new HoodieTableFileSystemView(metaClient, commitsTimeline, pathInfoList);
    Map<String, String> fileIdToBaseInstant = fileSystemView.getAllFileSlices("par1").collect(Collectors.toMap(FileSlice::getFileId, FileSlice::getBaseInstantTime));
    IncrementalInputSplits iis = IncrementalInputSplits.builder().conf(conf).path(new Path(basePath)).rowType(TestConfigurations.ROW_TYPE).partitionPruner(null).build();
