    expressions.add(new ValueLiteralExpression(10));
    ResolvedExpression equalsExpression = CallExpression.permanent(BuiltInFunctionDefinitions.EQUALS, expressions, DataTypes.BOOLEAN());
    CallExpression greaterThanExpression = CallExpression.permanent(BuiltInFunctionDefinitions.GREATER_THAN, expressions, DataTypes.BOOLEAN());
    CallExpression orExpression = CallExpression.permanent(BuiltInFunctionDefinitions.OR, Arrays.asList(equalsExpression, greaterThanExpression), DataTypes.BOOLEAN());
