    assertTrue(size2 > size1, "We just wrote a new block - size2 should be > size1");
    assertEquals(size2, storage.getPathInfo(writer.getLogFile().getPath()).getLength(), "Write should be auto-flushed. The size reported by FileStatus and the writer should match");
    writer.close();
    // Close and Open again and append 100 more records
    writer = HoodieLogFormat.newWriterBuilder().onParentPath(partitionPath).withFileExtension(HoodieLogFile.DELTA_EXTENSION).withFileId("test-fileid1").withLogVersion(1).withInstantTime("100").withStorage(storage).build();
    ((HoodieLogFormatWriter) writer).withOutputStream((FSDataOutputStream) storage.append(writer.getLogFile().getPath()));
    records = SchemaTestUtil.generateTestRecords(0, 100);
    header.put(HoodieLogBlock.HeaderMetadataType.SCHEMA, getSimpleSchema().toString());
    dataBlock = getDataBlock(dataBlockType, records, header);
    writer.appendBlock(dataBlock);
    long size3 = writer.getCurrentSize();
    assertTrue(size3 > size2, "We just wrote a new block - size3 should be > size2");
    assertEquals(size3, storage.getPathInfo(writer.getLogFile().getPath()).getLength(), "Write should be auto-flushed. The size reported by FileStatus and the writer should match");
    writer.close();
    // Cannot get the current size after closing the log
    final Writer closedWriter = writer;
    assertThrows(IllegalStateException.class, closedWriter::getCurrentSize, "getCurrentSize should fail after the logAppender is closed");
}

