    writer.appendBlock(dataBlock);
    // Delete 50 keys
    List<DeleteRecord> deletedRecords = copyOfRecords1.stream().map(s -> (DeleteRecord.create(((GenericRecord) s).get(HoodieRecord.RECORD_KEY_METADATA_FIELD).toString(), ((GenericRecord) s).get(HoodieRecord.PARTITION_PATH_METADATA_FIELD).toString()))).collect(Collectors.toList()).subList(0, 50);
