    scanner = HoodieMergedLogRecordScanner.newBuilder().withStorage(storage).withBasePath(basePath).withLogFilePaths(allLogFiles).withReaderSchema(schema).withLatestInstantTime("103").withMaxMemorySizeInBytes(1024000L).withReverseReader(false).withBufferSize(BUFFER_SIZE).withSpillableMapBasePath(spillableBasePath).withDiskMapType(diskMapType).withBitCaskDiskMapCompressionEnabled(isCompressionEnabled).withOptimizedLogBlocksScan(enableOptimizedLogBlocksScan).build();
