public void testGetRecordPositions(boolean recordWithPositions, boolean allValidPositions, boolean addBaseFileInstantTimeOfPositions) throws IOException {
    Map<HeaderMetadataType, String> header = new HashMap<>();
    List<Long> positions = new ArrayList<>();
    if (recordWithPositions) {
        positions.addAll(TestLogReaderUtils.generatePositions());
        if (!allValidPositions) {
            positions.add(INVALID_POSITION);
            positions.set(positions.size() / 2, INVALID_POSITION);
        }
    }
    List<Pair<DeleteRecord, Long>> deleteRecordList = positions.isEmpty() ? IntStream.range(0, 10).boxed().map(i -> Pair.of(DeleteRecord.create("key" + i, "partition"), INVALID_POSITION)).collect(Collectors.toList()) : IntStream.range(0, positions.size()).boxed().map(i -> Pair.of(DeleteRecord.create("key" + i, "partition"), positions.get(i))).collect(Collectors.toList());
    List<HoodieRecord> recordList = positions.isEmpty() ? IntStream.range(0, 10).boxed().map(i -> new HoodieAvroRecord(new HoodieKey("key" + i, "partition"), null, HoodieOperation.INSERT, new HoodieRecordLocation("001", "file1", INVALID_POSITION), null)).collect(Collectors.toList()) : IntStream.range(0, positions.size()).boxed().map(i -> new HoodieAvroRecord(new HoodieKey("key" + i, "partition"), null, HoodieOperation.INSERT, new HoodieRecordLocation("001", "file1", positions.get(i)), null)).collect(Collectors.toList());
    header.put(HeaderMetadataType.SCHEMA, NULL_SCHEMA);
    if (addBaseFileInstantTimeOfPositions) {
        header.put(HeaderMetadataType.BASE_FILE_INSTANT_TIME_OF_RECORD_POSITIONS, "001");
    }
    HoodieLogBlock deleteBlock = new HoodieDeleteBlock(deleteRecordList, header);
    HoodieLogBlock dataBlock = new HoodieAvroDataBlock(recordList, header, "key");
    boolean hasPositions = (recordWithPositions && allValidPositions && addBaseFileInstantTimeOfPositions);
    String expectedInstantTime = hasPositions ? "001" : null;
    Set<Long> expectedPositions = hasPositions ? new HashSet<>(positions) : Collections.emptySet();
    assertEquals(expectedInstantTime, deleteBlock.getBaseFileInstantTimeOfPositions());
    TestLogReaderUtils.assertPositionEquals(expectedPositions, deleteBlock.getRecordPositions());
    assertEquals(expectedInstantTime, dataBlock.getBaseFileInstantTimeOfPositions());
    TestLogReaderUtils.assertPositionEquals(expectedPositions, dataBlock.getRecordPositions());
}

@Test
@Timeout(60)
public void testFailedToGetAppendStreamFromHDFSNameNode() throws IOException, URISyntaxException, InterruptedException, TimeoutException {
    // Use some fs like LocalFileSystem, that does not support appends
    String uuid = UUID.randomUUID().toString();
    StoragePath localPartitionPath = new StoragePath("/tmp/");
    HoodieStorage storage = new HoodieHadoopStorage(cluster.getFileSystem());
    StoragePath testPath = new StoragePath(localPartitionPath, uuid);
    storage.createDirectory(testPath);
    // Some data & append.
    List<HoodieRecord> records = SchemaTestUtil.generateTestRecords(0, 10).stream().map(HoodieAvroIndexedRecord::new).collect(Collectors.toList());
    Map<HoodieLogBlock.HeaderMetadataType, String> header = new HashMap<>(2);
    header.put(HoodieLogBlock.HeaderMetadataType.INSTANT_TIME, "100");
    header.put(HoodieLogBlock.HeaderMetadataType.SCHEMA, getSimpleSchema().toString());
    HoodieAvroDataBlock dataBlock = new HoodieAvroDataBlock(records, header, HoodieRecord.RECORD_KEY_METADATA_FIELD);
    Writer writer = HoodieLogFormat.newWriterBuilder().onParentPath(testPath).withFileExtension(HoodieArchivedLogFile.ARCHIVE_EXTENSION).withFileId("commits").withInstantTime("").withStorage(storage).build();
    writer.appendBlock(dataBlock);
    // get the current log file version to compare later
    int logFileVersion = writer.getLogFile().getLogVersion();
    StoragePath logFilePath = writer.getLogFile().getPath();
    writer.close();
    // Wait for 3 times replication of file
    FileSystem fs = (FileSystem) storage.getFileSystem();
    DFSTestUtil.waitReplication(fs, new Path(logFilePath.toUri()), (short) 3);
    // Shut down all DNs that have the last block location for the file
    LocatedBlocks lbs = cluster.getFileSystem().getClient().getNamenode().getBlockLocations("/tmp/" + uuid + "/" + logFilePath.getName(), 0, Long.MAX_VALUE);
    List<DataNode> dnsOfCluster = cluster.getDataNodes();
    DatanodeInfo[] dnsWithLocations = lbs.getLastLocatedBlock().getLocations();
    for (DataNode dn : dnsOfCluster) {
        for (DatanodeInfo loc : dnsWithLocations) {
            if (dn.getDatanodeId().equals(loc)) {
                dn.shutdown();
                cluster.stopDataNode(dn.getDisplayName());
                DFSTestUtil.waitForDatanodeDeath(dn);
            }
        }
    }
    // Wait for the replication of this file to go down to 0
    DFSTestUtil.waitReplication(fs, new Path(logFilePath.toUri()), (short) 0);
    // Opening a new Writer right now will throw IOException. The code should handle this, rollover the logfile and
    // return a new writer with a bumped up logVersion
    writer = HoodieLogFormat.newWriterBuilder().onParentPath(testPath).withFileExtension(HoodieArchivedLogFile.ARCHIVE_EXTENSION).withFileId("commits").withInstantTime("").withStorage(storage).build();
    header = new HashMap<>();
    header.put(HoodieLogBlock.HeaderMetadataType.COMMAND_BLOCK_TYPE, String.valueOf(HoodieCommandBlock.HoodieCommandBlockTypeEnum.ROLLBACK_BLOCK.ordinal()));
    writer.appendBlock(new HoodieCommandBlock(header));
    // The log version should be different for this new writer
    assertNotEquals(writer.getLogFile().getLogVersion(), logFileVersion);
    writer.close();
}

