@ParameterizedTest
@MethodSource
void testInferMergingConfigsForPreV9Table(RecordMergeMode inputMergeMode, String inputPayloadClass, String inputMergeStrategy, String orderingFieldName, String shouldThrowString, RecordMergeMode outputMergeMode, String outputPayloadClass, String outputMergeStrategy) throws IOException {
    Arrays.stream(new HoodieTableVersion[] { HoodieTableVersion.EIGHT, HoodieTableVersion.SIX }).forEach(tableVersion -> {
        boolean shouldThrow = "eight-only".equals(shouldThrowString) ? tableVersion.greaterThanOrEquals(HoodieTableVersion.EIGHT) : "six-only".equals(shouldThrowString) ? !tableVersion.greaterThanOrEquals(HoodieTableVersion.EIGHT) : Boolean.parseBoolean(shouldThrowString);
        RecordMergeMode expectedMergeMode = outputMergeMode;
        String expectedMergeStrategy = outputMergeStrategy;
        if (!shouldThrow && (outputMergeMode == null || outputMergeStrategy == null)) {
            expectedMergeMode = tableVersion.greaterThanOrEquals(HoodieTableVersion.EIGHT) ? CUSTOM : inferRecordMergeModeFromPayloadClass(outputPayloadClass);
            expectedMergeStrategy = getRecordMergeStrategyId(expectedMergeMode, outputPayloadClass, inputMergeStrategy, tableVersion);
        }
        if (shouldThrow) {
            assertThrows(IllegalArgumentException.class, () -> inferMergingConfigsForPreV9Table(inputMergeMode, inputPayloadClass, inputMergeStrategy, orderingFieldName, tableVersion));
        } else {
            Triple<RecordMergeMode, String, String> inferredConfigs = inferMergingConfigsForPreV9Table(inputMergeMode, inputPayloadClass, inputMergeStrategy, orderingFieldName, tableVersion);
            assertEquals(expectedMergeMode, inferredConfigs.getLeft());
            assertEquals(outputPayloadClass, inferredConfigs.getMiddle());
            assertEquals(expectedMergeStrategy, inferredConfigs.getRight());
        }
    });
}

@ParameterizedTest
@MethodSource
void testInferMergingConfigsForV9TableCreation(String testName, RecordMergeMode recordMergeMode, String payloadClassName, String recordMergeStrategyId, String orderingFieldName, HoodieTableVersion tableVersion, int expectedConfigSize, String expectedMergeMode, String expectedPayloadClass, String expectedMergeStrategyId, String expectedLegacyPayloadClass, String expectedPartialUpdateMode, String expectedDebeziumMarker, String expectedDeleteKey, String expectedDeleteMarker) {
    if (tableVersion.lesserThan(HoodieTableVersion.NINE)) {
        assertExceptionWithInferMergingConfigsForV9TableCreation(recordMergeMode, payloadClassName, recordMergeStrategyId, orderingFieldName, tableVersion);
    } else {
        Map<String, String> configs = HoodieTableConfig.inferMergingConfigsForV9TableCreation(recordMergeMode, payloadClassName, recordMergeStrategyId, orderingFieldName, tableVersion);
        assertEquals(expectedConfigSize, configs.size(), "Config size mismatch for: " + testName);
        if (expectedMergeMode != null) {
            assertEquals(expectedMergeMode, configs.get(RECORD_MERGE_MODE.key()), "Merge mode mismatch for: " + testName);
        } else {
            assertFalse(configs.containsKey(RECORD_MERGE_MODE.key()), "Record merge mode not expected to be set");
        }
        if (expectedPayloadClass != null) {
            assertEquals(expectedPayloadClass, configs.get(PAYLOAD_CLASS_NAME.key()), "Payload class mismatch for: " + testName);
        } else {
            assertFalse(configs.containsKey(PAYLOAD_CLASS_NAME.key()), "Payload class not expected to be set");
        }
        if (expectedMergeStrategyId != null) {
            assertEquals(expectedMergeStrategyId, configs.get(RECORD_MERGE_STRATEGY_ID.key()), "Merge strategy ID mismatch for: " + testName);
        } else {
            assertFalse(configs.containsKey(RECORD_MERGE_STRATEGY_ID.key()), "Record merge strategy id not expected to be set");
        }
        if (expectedLegacyPayloadClass != null) {
            assertEquals(expectedLegacyPayloadClass, configs.get(LEGACY_PAYLOAD_CLASS_NAME.key()), "Legacy payload class mismatch for: " + testName);
        } else {
            assertFalse(configs.containsKey(LEGACY_PAYLOAD_CLASS_NAME.key()), "Legacy payload class not expected to be set");
        }
        if (expectedPartialUpdateMode != null) {
            assertEquals(expectedPartialUpdateMode, configs.get(HoodieTableConfig.PARTIAL_UPDATE_MODE.key()), "Partial update mode mismatch for: " + testName);
        } else {
            assertFalse(configs.containsKey(HoodieTableConfig.PARTIAL_UPDATE_MODE.key()), HoodieTableConfig.PARTIAL_UPDATE_MODE.key() + " not expected to be set");
        }
        if (expectedDebeziumMarker != null) {
            assertEquals(expectedDebeziumMarker, configs.get(HoodieTableConfig.RECORD_MERGE_PROPERTY_PREFIX + HoodieTableConfig.PARTIAL_UPDATE_UNAVAILABLE_VALUE), "Debezium marker mismatch for: " + testName);
        } else {
            assertFalse(configs.containsKey(HoodieTableConfig.RECORD_MERGE_PROPERTY_PREFIX + HoodieTableConfig.PARTIAL_UPDATE_UNAVAILABLE_VALUE), "Custom merge property " + HoodieTableConfig.RECORD_MERGE_PROPERTY_PREFIX + HoodieTableConfig.PARTIAL_UPDATE_UNAVAILABLE_VALUE + " not expected to be set");
        }
        if (expectedDeleteKey != null || configs.containsKey(HoodieTableConfig.RECORD_MERGE_PROPERTY_PREFIX + DELETE_KEY)) {
            assertEquals(expectedDeleteKey, configs.get(HoodieTableConfig.RECORD_MERGE_PROPERTY_PREFIX + DELETE_KEY), "Delete key mismatch for: " + testName);
        } else {
            assertFalse(configs.containsKey(HoodieTableConfig.RECORD_MERGE_PROPERTY_PREFIX + DELETE_KEY), "Custom merge property " + HoodieTableConfig.RECORD_MERGE_PROPERTY_PREFIX + DELETE_KEY + "  not expected to be set");
        }
        if (expectedDeleteMarker != null) {
            assertEquals(expectedDeleteMarker, configs.get(HoodieTableConfig.RECORD_MERGE_PROPERTY_PREFIX + DELETE_MARKER), "Delete marker mismatch for: " + testName);
        } else {
            assertFalse(configs.containsKey(HoodieTableConfig.RECORD_MERGE_PROPERTY_PREFIX + DELETE_MARKER), "Custom merge property " + HoodieTableConfig.RECORD_MERGE_PROPERTY_PREFIX + DELETE_MARKER + "  not expected to be set");
        }
    }
}

