@Test
public void testDuplicateTimestampDifferentActions() throws Exception {
    // Two actions that share the very same commit time "30"
    HoodieInstant commit30 = createInstantV1(COMPLETED, HoodieTimeline.COMMIT_ACTION, "30");
    HoodieInstant clean30 = createInstantV1(COMPLETED, HoodieTimeline.CLEAN_ACTION, "30");
    HoodieInstant commit31 = createInstantV1(COMPLETED, HoodieTimeline.COMMIT_ACTION, "31");
    // Write them to a brand new archive log
    try (HoodieLogFormat.Writer writer = buildWriter(ArchivedTimelineV1.getArchiveLogPath(metaClient.getArchivePath()))) {
        List<IndexedRecord> records = new ArrayList<>();
        records.add(createArchivedMetaWrapper(commit30));
        records.add(createArchivedMetaWrapper(clean30));
        records.add(createArchivedMetaWrapper(commit31));
        writeArchiveLog(writer, records);
    }
    // Build timeline (no filters), should read the new archive
    HoodieArchivedTimeline dupTimeline = new ArchivedTimelineV1(metaClient);
    dupTimeline.loadCompletedInstantDetailsInMemory();
    // Both actions for 30 are present (positive case)
    assertTrue(dupTimeline.getInstantDetails(commit30).isPresent(), "commit metadata for ts=30 must be loaded");
    assertTrue(dupTimeline.getInstantDetails(clean30).isPresent(), "clean metadata for ts=30 must be loaded");
    assertFalse(Arrays.equals(dupTimeline.getInstantDetails(commit30).get(), dupTimeline.getInstantDetails(clean30).get()), "clean and commit metadata should have different payloads");
    // For ts=31 we only archived COMMIT, so CLEAN must be absent (negative case)
    HoodieInstant fakeClean31 = createInstantV1(COMPLETED, HoodieTimeline.CLEAN_ACTION, "31");
    assertTrue(dupTimeline.getInstantDetails(commit31).isPresent(), "commit metadata for ts=31 must be loaded");
    assertFalse(dupTimeline.getInstantDetails(fakeClean31).isPresent(), "clean metadata for ts=31 must NOT be loaded");
}

@Test
public void testLoadingInstantsFromFiles() throws IOException {
    InstantGenerator instantGenerator = INSTANT_GENERATOR;
    TimelineFactory timelineFactory = TIMELINE_FACTORY;
    HoodieInstant instant1 = instantGenerator.createNewInstant(State.REQUESTED, HoodieTimeline.COMMIT_ACTION, "1");
    HoodieInstant instant2 = instantGenerator.createNewInstant(State.REQUESTED, HoodieTimeline.COMMIT_ACTION, "3");
    HoodieInstant instant3 = instantGenerator.createNewInstant(State.REQUESTED, HoodieTimeline.COMMIT_ACTION, "5");
    HoodieInstant instant4 = instantGenerator.createNewInstant(State.REQUESTED, HoodieTimeline.COMMIT_ACTION, "8");
    HoodieInstant instant1Complete = instantGenerator.createNewInstant(State.COMPLETED, HoodieTimeline.COMMIT_ACTION, "1");
    HoodieInstant instant2Complete = instantGenerator.createNewInstant(State.COMPLETED, HoodieTimeline.COMMIT_ACTION, "3");
    HoodieInstant instant3Complete = instantGenerator.createNewInstant(State.COMPLETED, HoodieTimeline.COMMIT_ACTION, "5");
    HoodieInstant instant4Complete = instantGenerator.createNewInstant(State.COMPLETED, HoodieTimeline.COMMIT_ACTION, "8");
    HoodieInstant instant5 = instantGenerator.createNewInstant(State.INFLIGHT, HoodieTimeline.COMMIT_ACTION, "9");
    timeline = timelineFactory.createActiveTimeline(metaClient);
    timeline.createNewInstant(instant1);
    timeline.transitionRequestedToInflight(instant1, Option.empty());
    // Won't lock here since InProcessLockProvider is not in hudi-common
    timeline.saveAsComplete(instantGenerator.createNewInstant(State.INFLIGHT, instant1.getAction(), instant1.requestedTime()), Option.empty());
    timeline.createNewInstant(instant2);
    timeline.transitionRequestedToInflight(instant2, Option.empty());
    timeline.saveAsComplete(instantGenerator.createNewInstant(State.INFLIGHT, instant2.getAction(), instant2.requestedTime()), Option.empty());
    timeline.createNewInstant(instant3);
    timeline.transitionRequestedToInflight(instant3, Option.empty());
    timeline.saveAsComplete(instantGenerator.createNewInstant(State.INFLIGHT, instant3.getAction(), instant3.requestedTime()), Option.empty());
    timeline.createNewInstant(instant4);
    timeline.transitionRequestedToInflight(instant4, Option.empty());
    timeline.saveAsComplete(instantGenerator.createNewInstant(State.INFLIGHT, instant4.getAction(), instant4.requestedTime()), Option.empty());
    timeline.createNewInstant(instant5);
    timeline = timeline.reload();
    assertEquals(5, timeline.countInstants(), "Total instants should be 5");
    assertStreamEquals(Stream.of(instant1Complete, instant2Complete, instant3Complete, instant4Complete, instant5), timeline.getInstantsAsStream(), "Check the instants stream");
    assertStreamEquals(Stream.of(instant1Complete, instant2Complete, instant3Complete, instant4Complete, instant5), timeline.getCommitTimeline().getInstantsAsStream(), "Check the instants stream");
    assertStreamEquals(Stream.of(instant1Complete, instant2Complete, instant3Complete, instant4Complete, instant5), timeline.getCommitAndReplaceTimeline().getInstantsAsStream(), "Check the instants stream");
    assertStreamEquals(Stream.of(instant1Complete, instant2Complete, instant3Complete, instant4Complete), timeline.getCommitAndReplaceTimeline().filterCompletedInstants().getInstantsAsStream(), "Check the instants stream");
    assertStreamEquals(Stream.of(instant5), timeline.getCommitAndReplaceTimeline().filterPendingExcludingCompactionAndLogCompaction().getInstantsAsStream(), "Check the instants stream");
}

