@Test
public void testTimelineOperations() {
    timeline = new MockHoodieTimeline(Stream.of("01", "03", "05", "07", "09", "11", "13", "15", "17", "19"), Stream.of("21", "23"));
    assertStreamEquals(Stream.of("05", "07", "09", "11"), timeline.getCommitAndReplaceTimeline().filterCompletedInstants().findInstantsInRange("04", "11").getInstantsAsStream().map(HoodieInstant::requestedTime), "findInstantsInRange should return 4 instants");
    assertStreamEquals(Stream.of("03", "05", "07", "09", "11"), timeline.getCommitAndReplaceTimeline().filterCompletedInstants().findInstantsInClosedRange("03", "11").getInstantsAsStream().map(HoodieInstant::requestedTime), "findInstantsInClosedRange should return 5 instants");
    assertStreamEquals(Stream.of("09", "11"), timeline.getCommitAndReplaceTimeline().filterCompletedInstants().findInstantsAfter("07", 2).getInstantsAsStream().map(HoodieInstant::requestedTime), "findInstantsAfter 07 should return 2 instants");
    assertStreamEquals(Stream.of("01", "03", "05"), timeline.getCommitAndReplaceTimeline().filterCompletedInstants().findInstantsBefore("07").getInstantsAsStream().map(HoodieInstant::requestedTime), "findInstantsBefore 07 should return 3 instants");
    assertFalse(timeline.empty());
    assertFalse(timeline.getCommitAndReplaceTimeline().filterPendingExcludingCompactionAndLogCompaction().empty());
    assertEquals(12, timeline.countInstants());
    assertEquals("01", timeline.firstInstant(HoodieTimeline.COMMIT_ACTION, State.COMPLETED).get().requestedTime());
    assertEquals("21", timeline.firstInstant(HoodieTimeline.COMMIT_ACTION, State.INFLIGHT).get().requestedTime());
    assertFalse(timeline.firstInstant(HoodieTimeline.COMMIT_ACTION, State.REQUESTED).isPresent());
    assertFalse(timeline.firstInstant(HoodieTimeline.REPLACE_COMMIT_ACTION, State.COMPLETED).isPresent());
    HoodieTimeline activeCommitTimeline = timeline.getCommitAndReplaceTimeline().filterCompletedInstants();
    assertEquals(10, activeCommitTimeline.countInstants());
    assertEquals("01", activeCommitTimeline.firstInstant().get().requestedTime());
    assertEquals("11", activeCommitTimeline.nthInstant(5).get().requestedTime());
    assertEquals("19", activeCommitTimeline.lastInstant().get().requestedTime());
    assertEquals("09", activeCommitTimeline.nthFromLastInstant(5).get().requestedTime());
    assertTrue(activeCommitTimeline.containsInstant(INSTANT_GENERATOR.createNewInstant(State.COMPLETED, HoodieTimeline.COMMIT_ACTION, "09")));
    assertFalse(activeCommitTimeline.isBeforeTimelineStarts("02"));
    assertTrue(activeCommitTimeline.isBeforeTimelineStarts("00"));
}

