    saveAsCompleteCluster(commitTimeline, clusteringInstant4, (HoodieReplaceCommitMetadata) commitMetadata);
    refreshFsView();
    // Now create a scenario where archiving deleted replace commits (requested,inflight and replacecommit)
    StoragePath completeInstantPath = HoodieTestUtils.getCompleteInstantPath(metaClient.getStorage(), metaClient.getTimelinePath(), clusteringInstantTime3, HoodieTimeline.REPLACE_COMMIT_ACTION);
