    when(hfileReader.getMetaBlock(KEY_BLOOM_FILTER_META_BLOCK)).thenReturn(Option.of(ByteBuffer.wrap(getUTF8Bytes(bloomFilter.serializeToString()))));
    when(hfileReader.getMetaInfo(new UTF8StringKey(KEY_BLOOM_FILTER_TYPE_CODE))).thenReturn(Option.of(getUTF8Bytes(bloomFilter.getBloomFilterTypeCode().toString())));
    List<String> filterKeys = Collections.singletonList("key");
    try (HoodieNativeAvroHFileReader reader = HoodieNativeAvroHFileReader.builder().readerFactory(readerFactory).path(new StoragePath("dummy")).useBloomFilter(useBloomFilter).build()) {
