        reader.getRecordIterator();
        verify(hfileReader, never()).getMetaBlock(KEY_BLOOM_FILTER_META_BLOCK);
        reader.getRecordIterator(schema);
        verify(hfileReader, never()).getMetaBlock(KEY_BLOOM_FILTER_META_BLOCK);
        reader.getRecordIterator(schema, schema);
        verify(hfileReader, never()).getMetaBlock(KEY_BLOOM_FILTER_META_BLOCK);
        reader.getRecordKeyIterator();
