        // Note that backward seek is not expected to happen in production code
        try (ClosableIterator<IndexedRecord> iterator = hfileReader.getIndexedRecordsByKeysIterator(Arrays.asList("key00001", "key05", "key24", "key16", "key31", "key61"), avroSchema)) {
