    HoodieRecord<HoodieMetadataPayload> firstPartitionFilesRecord = HoodieMetadataPayload.createPartitionFilesRecord(PARTITION_NAME, firstCommitAddedFiles, Collections.emptyList());
    Map<String, Long> secondCommitAddedFiles = createImmutableMap(// NOTE: This is an append
    Pair.of("file3.parquet", 3333L), Pair.of("file4.parquet", 4000L), Pair.of("file5.parquet", 5000L));
    List<String> secondCommitDeletedFiles = Collections.singletonList("file1.parquet");
