    HoodieMetadataPayload expectedCombinedPartitionedFilesRecordPayload = HoodieMetadataPayload.createPartitionFilesRecord(PARTITION_NAME, createImmutableMap(Pair.of("file2.parquet", 2000L), Pair.of("file3.parquet", 3333L), Pair.of("file4.parquet", 4000L), Pair.of("file5.parquet", 5000L)), Collections.emptyList()).getData();
    assertEquals(expectedCombinedPartitionedFilesRecordPayload, combinedPartitionFilesRecordPayload);
}

