    expectedDeleteFileList.add("file3.parquet");
    expectedDeleteFileList.add("file4.parquet");
    assertEquals(HoodieMetadataPayload.createPartitionFilesRecord(PARTITION_NAME, Collections.emptyMap(), expectedDeleteFileList).getData(), deletionRecord2.getData().preCombine(deletionRecord1.getData()));
    assertEquals(HoodieMetadataPayload.createPartitionFilesRecord(PARTITION_NAME, createImmutableMap(Pair.of("file2.parquet", 2000L)), Collections.emptyList()).getData(), deletionRecord2.getData().preCombine(deletionRecord1.getData()).preCombine(additionRecord.getData()));
    assertEquals(HoodieMetadataPayload.createPartitionFilesRecord(PARTITION_NAME, createImmutableMap(Pair.of("file2.parquet", 2000L)), Collections.singletonList("file1.parquet")).getData(), deletionRecord2.getData().preCombine(deletionRecord1.getData().preCombine(additionRecord.getData())));
