@Test
public void testColumnStatsPayloadMerging() throws IOException {
    String fileName = "file.parquet";
    String targetColName = "c1";
    HoodieColumnRangeMetadata<Comparable> c1Metadata = HoodieColumnRangeMetadata.<Comparable>create(fileName, targetColName, 100, 1000, 5, 1000, 123456, 123456, ValueMetadata.V1EmptyMetadata.get());
    HoodieRecord<HoodieMetadataPayload> columnStatsRecord = HoodieMetadataPayload.createColumnStatsRecords(PARTITION_NAME, Collections.singletonList(c1Metadata), false).findFirst().get();
    ////////////////////////////////////////////////////////////////////////
    // Case 1: Combining proper (non-deleted) records
    ////////////////////////////////////////////////////////////////////////
    // NOTE: Column Stats record will only be merged in case existing file will be modified,
    //       which could only happen on storages schemes supporting appends
    HoodieColumnRangeMetadata<Comparable> c1AppendedBlockMetadata = HoodieColumnRangeMetadata.<Comparable>create(fileName, targetColName, 0, 500, 0, 100, 12345, 12345, ValueMetadata.V1EmptyMetadata.get());
    HoodieRecord<HoodieMetadataPayload> updatedColumnStatsRecord = HoodieMetadataPayload.createColumnStatsRecords(PARTITION_NAME, Collections.singletonList(c1AppendedBlockMetadata), false).findFirst().get();
    HoodieMetadataPayload combinedMetadataPayload = columnStatsRecord.getData().preCombine(updatedColumnStatsRecord.getData());
    HoodieColumnRangeMetadata<Comparable> expectedColumnRangeMetadata = HoodieColumnRangeMetadata.<Comparable>create(fileName, targetColName, 0, 1000, 5, 1100, 135801, 135801, ValueMetadata.V1EmptyMetadata.get());
    HoodieRecord<HoodieMetadataPayload> expectedColumnStatsRecord = HoodieMetadataPayload.createColumnStatsRecords(PARTITION_NAME, Collections.singletonList(expectedColumnRangeMetadata), false).findFirst().get();
    // Assert combined payload
    assertEquals(combinedMetadataPayload, expectedColumnStatsRecord.getData());
    Option<IndexedRecord> alternativelyCombinedMetadataPayloadAvro = columnStatsRecord.getData().combineAndGetUpdateValue(updatedColumnStatsRecord.getData().getInsertValue(null).get(), null);
    // Assert that using legacy API yields the same value
    assertEquals(combinedMetadataPayload.getInsertValue(null), alternativelyCombinedMetadataPayloadAvro);
    ////////////////////////////////////////////////////////////////////////
    // Case 2: Combining w/ deleted records
    ////////////////////////////////////////////////////////////////////////
    HoodieColumnRangeMetadata<Comparable> c1StubbedMetadata = HoodieColumnRangeMetadata.<Comparable>stub(fileName, targetColName, V1);
    HoodieRecord<HoodieMetadataPayload> deletedColumnStatsRecord = HoodieMetadataPayload.createColumnStatsRecords(PARTITION_NAME, Collections.singletonList(c1StubbedMetadata), true).findFirst().get();
    // NOTE: In this case, deleted (or tombstone) record will be therefore deleting
    //       previous state of the record
    HoodieMetadataPayload deletedCombinedMetadataPayload = deletedColumnStatsRecord.getData().preCombine(columnStatsRecord.getData());
    assertEquals(deletedColumnStatsRecord.getData(), deletedCombinedMetadataPayload);
    assertFalse(deletedCombinedMetadataPayload.getInsertValue(null).isPresent());
    assertTrue(deletedCombinedMetadataPayload.isDeleted());
    // NOTE: In this case, proper incoming record will be overwriting previously deleted
    //       record
    HoodieMetadataPayload overwrittenCombinedMetadataPayload = columnStatsRecord.getData().preCombine(deletedColumnStatsRecord.getData());
    assertEquals(columnStatsRecord.getData(), overwrittenCombinedMetadataPayload);
}

