@Test
void testToStringWithThreshold() {
    String str1 = "string_value1";
    String str2 = "string_value2";
    String str3 = "string_value3";
    assertEquals("", toStringWithThreshold(null, 10));
    assertEquals("", toStringWithThreshold(Collections.emptyList(), 10));
    assertEquals("..", toStringWithThreshold(Collections.singletonList(str1), 2));
    assertEquals("string_...", toStringWithThreshold(Collections.singletonList(str1), str1.length() - 3));
    assertEquals("[string_value1]", toStringWithThreshold(Collections.singletonList(str1), 0));
    assertEquals(str1, toStringWithThreshold(Collections.singletonList(str1), str1.length()));
    assertEquals(str1, toStringWithThreshold(Collections.singletonList(str1), str1.length() + 10));
    List<String> stringList = new ArrayList<>();
    stringList.add(str1);
    stringList.add(str2);
    stringList.add(str3);
    assertEquals("string_val...", toStringWithThreshold(stringList, str1.length()));
    assertEquals("string_valu...", toStringWithThreshold(stringList, str1.length() + 1));
    assertEquals("string_value1,string...", toStringWithThreshold(stringList, str1.length() + str2.length() - 3));
    assertEquals("string_value1,string_v...", toStringWithThreshold(stringList, str1.length() + str2.length() - 1));
    assertEquals("string_value1,string_value2,strin...", toStringWithThreshold(stringList, str1.length() + str2.length() + str3.length() - 3));
    assertEquals("string_value1,string_value2,string_value3", toStringWithThreshold(stringList, str1.length() + str2.length() + str3.length() + 2));
    assertEquals("[string_value1, string_value2, string_value3]", toStringWithThreshold(stringList, -1));
}

