@Test
public void testReadHFileWithNonUniqueKeys() throws IOException {
    try (HFileReader reader = getHFileReader("/hfile/hudi_1_0_hbase_2_4_9_16KB_GZ_200_20_non_unique.hfile")) {
        reader.initializeMetadata();
        verifyHFileMetadata(reader, 4200);
        assertFalse(reader.isSeeked());
        assertFalse(reader.next());
        assertTrue(reader.seekTo());
        int numKeys = 200;
        // Calling reader.next()
        for (int i = 0; i < numKeys; i++) {
            Option<KeyValue> keyValue = reader.getKeyValue();
            assertTrue(keyValue.isPresent());
            Key expectedKey = new UTF8StringKey(KEY_CREATOR.apply(i));
            String value = VALUE_CREATOR.apply(i);
            assertEquals(expectedKey, keyValue.get().getKey());
            assertEquals(value, getValue(keyValue.get()));
            assertTrue(reader.next());
            for (int j = 0; j < 20; j++) {
                keyValue = reader.getKeyValue();
                assertTrue(keyValue.isPresent());
                assertEquals(expectedKey, keyValue.get().getKey());
                assertEquals(value + "_" + j, getValue(keyValue.get()));
                if (i == numKeys - 1 && j == 19) {
                    assertFalse(reader.next());
                } else {
                    assertTrue(reader.next());
                }
            }
        }
        assertTrue(reader.seekTo());
        // Calling reader.seekTo(key) on each key
        for (int i = 0; i < numKeys; i++) {
            Key expectedKey = new UTF8StringKey(KEY_CREATOR.apply(i));
            for (int j = 0; j < 1; j++) {
                // seekTo twice and the results should be the same
                assertEquals(SEEK_TO_FOUND, reader.seekTo(expectedKey));
                Option<KeyValue> keyValue = reader.getKeyValue();
                assertTrue(keyValue.isPresent());
                String value = VALUE_CREATOR.apply(i);
                assertEquals(expectedKey, keyValue.get().getKey());
                assertEquals(value, getValue(keyValue.get()));
            }
            assertTrue(reader.next());
            for (int j = 0; j < 1; j++) {
                // seekTo twice and the results should be the same
                assertEquals(SEEK_TO_FOUND, reader.seekTo(expectedKey));
                Option<KeyValue> keyValue = reader.getKeyValue();
                assertTrue(keyValue.isPresent());
                String value = VALUE_CREATOR.apply(i);
                assertEquals(expectedKey, keyValue.get().getKey());
                assertEquals(value + "_0", getValue(keyValue.get()));
            }
        }
        verifyHFileSeekToReads(reader, // point and prefix lookups
        Arrays.asList(// before first key
        new KeyLookUpInfo("", SEEK_TO_BEFORE_FILE_FIRST_KEY, "hudi-key-000000000", "hudi-value-000000000"), new KeyLookUpInfo("a", SEEK_TO_BEFORE_FILE_FIRST_KEY, "hudi-key-000000000", "hudi-value-000000000"), new KeyLookUpInfo("hudi-key-0000000", SEEK_TO_BEFORE_FILE_FIRST_KEY, "hudi-key-000000000", "hudi-value-000000000"), // first key
        new KeyLookUpInfo("hudi-key-000000000", SEEK_TO_FOUND, "hudi-key-000000000", "hudi-value-000000000"), // key in the block 0
        new KeyLookUpInfo("hudi-key-000000005", SEEK_TO_FOUND, "hudi-key-000000005", "hudi-value-000000005"), // backward seek not supported
        new KeyLookUpInfo("hudi-key-000000004", SEEK_TO_THROW_EXCEPTION, "", ""), // prefix lookup, the pointer should move to the entry before
        new KeyLookUpInfo("hudi-key-000000006a", SEEK_TO_IN_RANGE, "hudi-key-000000006", "hudi-value-000000006_19"), new KeyLookUpInfo("hudi-key-000000006b", SEEK_TO_IN_RANGE, "hudi-key-000000006", "hudi-value-000000006_19"), // prefix lookup with a jump, the pointer should not go beyond the lookup key
        new KeyLookUpInfo("hudi-key-000000008a", SEEK_TO_IN_RANGE, "hudi-key-000000008", "hudi-value-000000008_19"), new KeyLookUpInfo("hudi-key-000000008b", SEEK_TO_IN_RANGE, "hudi-key-000000008", "hudi-value-000000008_19"), // last key of the block 0
        new KeyLookUpInfo("hudi-key-000000012", SEEK_TO_FOUND, "hudi-key-000000012", "hudi-value-000000012"), new KeyLookUpInfo("hudi-key-000000012a", SEEK_TO_IN_RANGE, "hudi-key-000000012", "hudi-value-000000012_19"), new KeyLookUpInfo("hudi-key-000000012b", SEEK_TO_IN_RANGE, "hudi-key-000000012", "hudi-value-000000012_19"), // first key of the block 1
        new KeyLookUpInfo("hudi-key-000000013", SEEK_TO_FOUND, "hudi-key-000000013", "hudi-value-000000013"), // prefix before the first key of the block 5
        new KeyLookUpInfo("hudi-key-000000064a", SEEK_TO_IN_RANGE, "hudi-key-000000064", "hudi-value-000000064_19"), new KeyLookUpInfo("hudi-key-000000064b", SEEK_TO_IN_RANGE, "hudi-key-000000064", "hudi-value-000000064_19"), // first key of the block 8
        new KeyLookUpInfo("hudi-key-000000104", SEEK_TO_FOUND, "hudi-key-000000104", "hudi-value-000000104"), // last key of the block 11
        new KeyLookUpInfo("hudi-key-000000155", SEEK_TO_FOUND, "hudi-key-000000155", "hudi-value-000000155"), // seeking again should not move the pointer
        new KeyLookUpInfo("hudi-key-000000155", SEEK_TO_FOUND, "hudi-key-000000155", "hudi-value-000000155"), // adjacent keys
        new KeyLookUpInfo("hudi-key-000000156", SEEK_TO_FOUND, "hudi-key-000000156", "hudi-value-000000156"), new KeyLookUpInfo("hudi-key-000000157", SEEK_TO_FOUND, "hudi-key-000000157", "hudi-value-000000157"), new KeyLookUpInfo("hudi-key-000000158", SEEK_TO_FOUND, "hudi-key-000000158", "hudi-value-000000158"), // prefix lookups in the block 14
        new KeyLookUpInfo("hudi-key-00000019", SEEK_TO_IN_RANGE, "hudi-key-000000189", "hudi-value-000000189_19"), new KeyLookUpInfo("hudi-key-000000190a", SEEK_TO_IN_RANGE, "hudi-key-000000190", "hudi-value-000000190_19"), // second to last key
        new KeyLookUpInfo("hudi-key-000000198", SEEK_TO_FOUND, "hudi-key-000000198", "hudi-value-000000198"), // last key
        new KeyLookUpInfo("hudi-key-000000199", SEEK_TO_FOUND, "hudi-key-000000199", "hudi-value-000000199"), // after last key
        new KeyLookUpInfo("hudi-key-000000199a", SEEK_TO_EOF, "", ""), new KeyLookUpInfo("hudi-key-000000199b", SEEK_TO_EOF, "", "")));
    }
