@Test
void testSameKeyLocation() throws IOException {
    // 165 bytes for data part limit.
    HFileContext context = new HFileContext.Builder().blockSize(165).build();
    String testFile = TEST_FILE;
    // CREATE 4 BLOCKs:
    // Block 1: 100 records, whose keys are the same: "key00".
    // Block 2: 5   records, whose first key is "key01"
    // Block 3: 5   records, whose first key is "key06"
    // Block 4: 1   record,  whose first key is "key11",
    //              whose length is larger than the block size.
    try (DataOutputStream outputStream = new DataOutputStream(Files.newOutputStream(Paths.get(testFile)));
        HFileWriter writer = new HFileWriterImpl(context, outputStream)) {
        // All entries for key00 are stored in the first block.
        for (int i = 0; i < 100; i++) {
            writer.append("key00", String.format("value%02d", i).getBytes());
        }
        // Otherwise, 5 records in each other blocks.
        for (int i = 1; i < 11; i++) {
            writer.append(String.format("key%02d", i), String.format("value%02d", i).getBytes());
        }
        // Adding a record whose size is larger than block size.
        String longValue = generateRandomStringStream(200);
        writer.append("key11", longValue.getBytes());
    } catch (IOException e) {
        throw new RuntimeException(e);
    }
    // Validate.
    try (FileChannel channel = FileChannel.open(Paths.get(testFile), StandardOpenOption.READ)) {
        ByteBuffer buf = channel.map(FileChannel.MapMode.READ_ONLY, 0, channel.size());
        SeekableDataInputStream inputStream = new ByteArraySeekableDataInputStream(new ByteBufferBackedInputStream(buf));
        HFileReaderImpl reader = new HFileReaderImpl(inputStream, channel.size());
        reader.initializeMetadata();
        // Totally 111 records.
        assertEquals(111, reader.getNumKeyValueEntries());
        HFileTrailer trailer = reader.getTrailer();
        // Totally 4 blocks.
        assertEquals(4, trailer.getDataIndexCount());
        int i = 0;
        for (Map.Entry<Key, BlockIndexEntry> entry : reader.getDataBlockIndexMap().entrySet()) {
            if (i == 0) {
                // first block: 100 records * 33 bytes + 37 bytes for header and checksum = 3337.
                assertEquals(3337, entry.getValue().getSize());
                assertEquals("key00", entry.getKey().getContentInString());
                i++;
            } else {
                if (i == 1 || i == 6) {
                    // second and third blocks: 5 records * 33 bytes + 37 bytes for header and checksum = 202.
                    assertEquals(202, entry.getValue().getSize());
                    assertEquals(String.format("key%02d", i), entry.getKey().getContentInString());
                    i += 5;
                } else {
                    // fourth block: 1 records * 226 bytes + 37 bytes for header and checksum = 263.
                    assertEquals(263, entry.getValue().getSize());
                    assertEquals(String.format("key%02d", i), entry.getKey().getContentInString());
                    i++;
                }
            }
        }
    }
}

@Test
void testUniqueKeyLocation() throws IOException {
    // 50 bytes for data part limit.
    HFileContext context = new HFileContext.Builder().blockSize(100).build();
    String testFile = TEST_FILE;
    try (DataOutputStream outputStream = new DataOutputStream(Files.newOutputStream(Paths.get(testFile)));
        HFileWriter writer = new HFileWriterImpl(context, outputStream)) {
        for (int i = 0; i < 50; i++) {
            writer.append(String.format("key%02d", i), String.format("value%02d", i).getBytes());
        }
    } catch (IOException e) {
        throw new RuntimeException(e);
    }
    // Validate.
    try (FileChannel channel = FileChannel.open(Paths.get(testFile), StandardOpenOption.READ)) {
        ByteBuffer buf = channel.map(FileChannel.MapMode.READ_ONLY, 0, channel.size());
        SeekableDataInputStream inputStream = new ByteArraySeekableDataInputStream(new ByteBufferBackedInputStream(buf));
        HFileReaderImpl reader = new HFileReaderImpl(inputStream, channel.size());
        reader.initializeMetadata();
        assertEquals(50, reader.getNumKeyValueEntries());
        HFileTrailer trailer = reader.getTrailer();
        assertEquals(17, trailer.getDataIndexCount());
        reader.seekTo();
        for (int i = 0; i < 50; i++) {
            KeyValue kv = reader.getKeyValue().get();
            assertArrayEquals(String.format("key%02d", i).getBytes(), kv.getKey().getContentInString().getBytes());
            assertArrayEquals(String.format("value%02d", i).getBytes(), Arrays.copyOfRange(kv.getBytes(), kv.getValueOffset(), kv.getValueOffset() + kv.getValueLength()));
            reader.next();
        }
    }
}

@Test
public void testConstructorNewInstanceUnwrapCopy() {
    T conf = getConf(prepareConfigs());
    StorageConfiguration<T> storageConf = getStorageConfiguration(conf);
    StorageConfiguration<T> newStorageConf = storageConf.newInstance();
    Class unwrapperConfClass = storageConf.unwrap().getClass();
    assertNotSame(storageConf, newStorageConf, "storageConf.newInstance() should return a different StorageConfiguration instance.");
    validateConfigs(newStorageConf);
    assertNotSame(storageConf.unwrap(), newStorageConf.unwrap(), "storageConf.newInstance() should contain a new copy of the underlying configuration instance.");
    assertSame(storageConf.unwrap(), storageConf.unwrap(), "storageConf.unwrap() should return the same underlying configuration instance.");
    assertSame(storageConf.unwrap(), storageConf.unwrapAs(unwrapperConfClass), "storageConf.unwrapAs(unwrapperConfClass) should return the same underlying configuration instance.");
    assertNotSame(storageConf.unwrap(), storageConf.unwrapCopy(), "storageConf.unwrapCopy() should return a new copy of the underlying configuration instance.");
    validateConfigs(getStorageConfiguration(storageConf.unwrapCopy()));
    assertNotSame(storageConf.unwrap(), storageConf.unwrapCopyAs(unwrapperConfClass), "storageConf.unwrapCopyAs(unwrapperConfClass) should return a new copy of the underlying configuration instance.");
    validateConfigs(getStorageConfiguration((T) storageConf.unwrapCopyAs(unwrapperConfClass)));
    assertThrows(IllegalArgumentException.class, () -> storageConf.unwrapAs(Integer.class));
    assertThrows(IllegalArgumentException.class, () -> storageConf.unwrapCopyAs(Integer.class));
}

