@Test
public void testPendingRestore() throws IOException {
    HoodieWriteConfig config = getConfigBuilder().withMetadataConfig(HoodieMetadataConfig.newBuilder().enable(false).build()).build();
    StoragePath completeRestoreFile = null;
    StoragePath backupCompletedRestoreFile = null;
    try (SparkRDDWriteClient client = getHoodieWriteClient(config)) {
        insertBatchRecords(client, "001", 100, 3, 2, SparkRDDWriteClient::insert);
        // inject a pending restore
        client.savepoint("001", "user1", "comment1");
        client.restoreToInstant("001", false);
        // remove completed restore instant from timeline to mimic pending restore.
        HoodieInstant restoreCompleted = metaClient.reloadActiveTimeline().getRestoreTimeline().filterCompletedInstants().getInstants().get(0);
        completeRestoreFile = new StoragePath(config.getBasePath() + StoragePath.SEPARATOR + HoodieTableMetaClient.METAFOLDER_NAME + StoragePath.SEPARATOR + HoodieTableMetaClient.TIMELINEFOLDER_NAME + StoragePath.SEPARATOR + INSTANT_FILE_NAME_GENERATOR.getFileName(restoreCompleted));
        backupCompletedRestoreFile = new StoragePath(config.getBasePath() + StoragePath.SEPARATOR + HoodieTableMetaClient.METAFOLDER_NAME + StoragePath.SEPARATOR + HoodieTableMetaClient.TIMELINEFOLDER_NAME + StoragePath.SEPARATOR + INSTANT_FILE_NAME_GENERATOR.getFileName(restoreCompleted) + ".backup");
        metaClient.getStorage().rename(completeRestoreFile, backupCompletedRestoreFile);
    }
    try (SparkRDDWriteClient client = getHoodieWriteClient(config)) {
        // since restore is pending, should fail the commit
        assertThrows(IllegalArgumentException.class, client::startCommit);
    }
    // add back the restore file.
    metaClient.getStorage().rename(backupCompletedRestoreFile, completeRestoreFile);
    // retrigger a new commit, should succeed.
    try (SparkRDDWriteClient client = getHoodieWriteClient(config)) {
        insertBatchRecords(client, "003", 100, 3, 2, SparkRDDWriteClient::insert);
    }
}

