    // setup clustering config with update strategy to allow updates during ingestion
    HoodieClusteringConfig clusteringConfig = createClusteringBuilder(true, 1).withClusteringUpdatesStrategy("org.apache.hudi.client.clustering.update.strategy.SparkAllowUpdateStrategy").withRollbackPendingClustering(rollbackPendingClustering).build();
