@Test
public void testCleanFunctionalityWhenCompactionRequestedInstantIsPresent() throws Exception {
    HoodieWriteConfig config = getConfigBuilder(HoodieTestDataGenerator.TRIP_EXAMPLE_SCHEMA, HoodieIndex.IndexType.INMEMORY).withCompactionConfig(HoodieCompactionConfig.newBuilder().withMaxNumDeltaCommitsBeforeCompaction(1).build()).withCleanConfig(HoodieCleanConfig.newBuilder().retainCommits(4).build()).build();
    SparkRDDWriteClient client = getHoodieWriteClient(config);
    // First insert. Here first file slice gets added to file group.
    String newCommitTime = WriteClientTestUtils.createNewInstantTime();
    insertBatch(config, client, newCommitTime, "000", 100, SparkRDDWriteClient::insert, false, false, 100, 100, 1, Option.empty(), INSTANT_GENERATOR);
    // Schedule and execute compaction. Here, second file slice gets added.
    Option<String> compactionTimeStamp = client.scheduleCompaction(Option.empty());
    assertTrue(compactionTimeStamp.isPresent());
    HoodieWriteMetadata result = client.compact(compactionTimeStamp.get());
    client.commitCompaction(compactionTimeStamp.get(), result, Option.empty());
    assertTrue(metaClient.reloadActiveTimeline().filterCompletedInstants().containsInstant(compactionTimeStamp.get()));
    String prevCommitTime = compactionTimeStamp.get();
    // First upsert on  second file slice.
    newCommitTime = WriteClientTestUtils.createNewInstantTime();
    updateBatch(config, client, newCommitTime, prevCommitTime, Option.of(Arrays.asList(prevCommitTime)), "000", 50, SparkRDDWriteClient::upsert, false, false, 50, 100, 2, config.populateMetaFields(), INSTANT_GENERATOR);
    prevCommitTime = newCommitTime;
    // Schedule compaction. Third file slice gets added, compaction is not complete so base file is not created yet.
    compactionTimeStamp = client.scheduleCompaction(Option.empty());
    assertTrue(compactionTimeStamp.isPresent());
    prevCommitTime = compactionTimeStamp.get();
    for (int i = 0; i < 6; i++) {
        // First upsert on third file slice.
        newCommitTime = WriteClientTestUtils.createNewInstantTime();
        updateBatch(config, client, newCommitTime, prevCommitTime, Option.of(Arrays.asList(prevCommitTime)), "000", 50, SparkRDDWriteClient::upsert, false, false, 50, 100, 2, config.populateMetaFields(), INSTANT_GENERATOR);
        prevCommitTime = newCommitTime;
        if (i == 2) {
            // Since retain commits is 4 exactly after 6th completed commit there will be some files to be cleaned,
            // since a version older than the earliest commit is also retained.
            HoodieInstant cleanInstant = metaClient.reloadActiveTimeline().lastInstant().get();
            assertEquals(HoodieTimeline.CLEAN_ACTION, cleanInstant.getAction());
        } else {
            // Make sure clean is never triggered for other commits. The cleaner is blocked due to pending compaction instant.
            assertEquals(HoodieTimeline.DELTA_COMMIT_ACTION, metaClient.reloadActiveTimeline().lastInstant().get().getAction());
        }
    }
}

@Test
public void testRollbackOnLogCompaction() throws Exception {
    HoodieCompactionConfig compactionConfig = HoodieCompactionConfig.newBuilder().withMaxNumDeltaCommitsBeforeCompaction(1).withLogCompactionBlocksThreshold(1).build();
    HoodieWriteConfig lcConfig = getConfigBuilder(HoodieTestDataGenerator.TRIP_EXAMPLE_SCHEMA, HoodieIndex.IndexType.INMEMORY).withCompactionConfig(compactionConfig).build();
    HoodieWriteConfig config = getConfigBuilder(HoodieTestDataGenerator.TRIP_EXAMPLE_SCHEMA, HoodieIndex.IndexType.INMEMORY).build();
    try (SparkRDDWriteClient lcClient = new SparkRDDWriteClient(context, lcConfig);
        SparkRDDWriteClient client = new SparkRDDWriteClient(context, config)) {
        // First insert
        String newCommitTime = WriteClientTestUtils.createNewInstantTime();
        insertBatch(config, client, newCommitTime, "000", 100, SparkRDDWriteClient::insert, false, false, 100, 100, 1, Option.empty(), INSTANT_GENERATOR);
        String prevCommitTime = newCommitTime;
        // Upsert
        newCommitTime = WriteClientTestUtils.createNewInstantTime();
        updateBatch(config, client, newCommitTime, prevCommitTime, Option.of(Arrays.asList(prevCommitTime)), "000", 10, SparkRDDWriteClient::upsert, false, false, 10, 100, 4, config.populateMetaFields(), INSTANT_GENERATOR);
        prevCommitTime = newCommitTime;
        // Schedule and execute log-compaction but do not commit.
        Option<String> logCompactionTimeStamp = lcClient.scheduleLogCompaction(Option.empty());
        assertTrue(logCompactionTimeStamp.isPresent());
        lcClient.logCompact(logCompactionTimeStamp.get());
        // Rollback the log compaction commit.
        HoodieInstant instant = INSTANT_GENERATOR.createNewInstant(HoodieInstant.State.INFLIGHT, HoodieTimeline.LOG_COMPACTION_ACTION, logCompactionTimeStamp.get());
        getHoodieTable(metaClient, config).rollbackInflightLogCompaction(instant, client.getTransactionManager());
        // Validate timeline.
        HoodieTimeline activeTimeline = metaClient.reloadActiveTimeline();
        HoodieInstant rollbackInstant = activeTimeline.lastInstant().get();
        assertEquals(3, activeTimeline.countInstants());
        assertEquals(HoodieTimeline.ROLLBACK_ACTION, rollbackInstant.getAction());
        // Validate block instant times.
        validateBlockInstantsBeforeAndAfterRollback(config, prevCommitTime, rollbackInstant.requestedTime());
        prevCommitTime = rollbackInstant.requestedTime();
        // Do one more upsert
        newCommitTime = WriteClientTestUtils.createNewInstantTime();
        updateBatch(config, client, newCommitTime, prevCommitTime, Option.of(Arrays.asList(prevCommitTime)), "000", 10, SparkRDDWriteClient::upsert, false, false, 10, 100, 4, config.populateMetaFields(), INSTANT_GENERATOR);
        prevCommitTime = newCommitTime;
        // Complete log-compaction now.
        logCompactionTimeStamp = lcClient.scheduleLogCompaction(Option.empty());
        assertTrue(logCompactionTimeStamp.isPresent());
        HoodieWriteMetadata metadata = lcClient.logCompact(logCompactionTimeStamp.get());
        lcClient.commitLogCompaction(logCompactionTimeStamp.get(), metadata, Option.empty());
        assertDataInMORTable(config, prevCommitTime, logCompactionTimeStamp.get(), storageConf, Arrays.asList(dataGen.getPartitionPaths()));
    }
}

@Test
public void testArchivalOnLogCompaction() throws Exception {
    HoodieCompactionConfig logCompactionConfig = HoodieCompactionConfig.newBuilder().withMaxNumDeltaCommitsBeforeCompaction(1).withLogCompactionBlocksThreshold(1).build();
    HoodieWriteConfig lcWriteConfig = getConfigBuilder(HoodieTestDataGenerator.TRIP_EXAMPLE_SCHEMA, HoodieIndex.IndexType.INMEMORY).withCompactionConfig(logCompactionConfig).build();
    HoodieCompactionConfig compactionConfig = HoodieCompactionConfig.newBuilder().withMaxNumDeltaCommitsBeforeCompaction(1).build();
    HoodieWriteConfig config = getConfigBuilder(HoodieTestDataGenerator.TRIP_EXAMPLE_SCHEMA, HoodieIndex.IndexType.INMEMORY).withCompactionConfig(compactionConfig).withCleanConfig(HoodieCleanConfig.newBuilder().retainCommits(2).build()).withArchivalConfig(HoodieArchivalConfig.newBuilder().archiveCommitsWith(4, 5).build()).withMetadataConfig(HoodieMetadataConfig.newBuilder().withMaxNumDeltaCommitsBeforeCompaction(2).build()).build();
    try (SparkRDDWriteClient lcWriteClient = new SparkRDDWriteClient(context, lcWriteConfig);
        SparkRDDWriteClient client = new SparkRDDWriteClient(context, config)) {
        // First insert
        String newCommitTime = WriteClientTestUtils.createNewInstantTime();
        insertBatch(config, client, newCommitTime, "000", 100, SparkRDDWriteClient::insert, false, false, 10, 100, 1, Option.empty(), INSTANT_GENERATOR);
        String prevCommitTime = newCommitTime;
        List<String> logCompactionInstantTimes = new ArrayList<>();
        for (int i = 0; i < 6; i++) {
            if (i % 4 == 0) {
                // Schedule compaction.
                Option<String> compactionTimeStamp = client.scheduleCompaction(Option.empty());
                assertTrue(compactionTimeStamp.isPresent());
                HoodieWriteMetadata result = client.compact(compactionTimeStamp.get());
                client.commitCompaction(compactionTimeStamp.get(), result, Option.empty());
                assertTrue(metaClient.reloadActiveTimeline().filterCompletedInstants().containsInstant(compactionTimeStamp.get()));
                prevCommitTime = compactionTimeStamp.get();
            }
            // Upsert
            newCommitTime = WriteClientTestUtils.createNewInstantTime();
            updateBatch(config, client, newCommitTime, prevCommitTime, Option.of(Arrays.asList(prevCommitTime)), "000", 50, SparkRDDWriteClient::upsert, false, false, 50, 10, 0, config.populateMetaFields(), INSTANT_GENERATOR);
            // Schedule log compaction.
            Option<String> logCompactionTimeStamp = lcWriteClient.scheduleLogCompaction(Option.empty());
            if (logCompactionTimeStamp.isPresent()) {
                logCompactionInstantTimes.add(logCompactionTimeStamp.get());
                HoodieWriteMetadata result = lcWriteClient.logCompact(logCompactionTimeStamp.get());
                lcWriteClient.commitLogCompaction(logCompactionTimeStamp.get(), result, Option.empty());
                prevCommitTime = logCompactionTimeStamp.get();
            }
        }
        boolean logCompactionInstantArchived = false;
        Map<String, List<HoodieInstant>> instantsMap = metaClient.getArchivedTimeline().getInstantsAsStream().collect(Collectors.groupingBy(HoodieInstant::requestedTime));
        for (String logCompactionTimeStamp : logCompactionInstantTimes) {
            List<HoodieInstant> instants = instantsMap.get(logCompactionTimeStamp);
            if (instants == null) {
                continue;
            }
            assertEquals(1, instants.size());
            assertEquals(HoodieTimeline.DELTA_COMMIT_ACTION, instants.get(0).getAction());
            logCompactionInstantArchived = true;
        }
        assertTrue(logCompactionInstantArchived);
    }
}

/**
 * Tests various methods used for RLI and SI record generation flows.
 * We test below methods
 * BaseFileRecordParsingUtils.generateRLIMetadataHoodieRecordsForBaseFile(...). This is used for RLI record generation.
 * BaseFileRecordParsingUtils.getRecordKeyStatuses(...) // This is used in both RLI and SI flow.
 *
 * @throws IOException
 */
@Test
public void testRecordGenerationAPIsForCOW() throws IOException {
    HoodieTableType tableType = HoodieTableType.COPY_ON_WRITE;
    cleanupClients();
    initMetaClient(tableType);
    cleanupTimelineService();
    initTimelineService();
    HoodieSparkEngineContext engineContext = new HoodieSparkEngineContext(jsc);
    HoodieWriteConfig writeConfig = getConfigBuilder(HoodieFailedWritesCleaningPolicy.EAGER).build();
    try (SparkRDDWriteClient client = new SparkRDDWriteClient(engineContext, writeConfig)) {
        // Insert
        String commitTime = client.startCommit();
        List<HoodieRecord> records1 = dataGen.generateInserts(commitTime, 100);
        List<WriteStatus> writeStatusList1 = client.insert(jsc.parallelize(records1, 1), commitTime).collect();
        client.commit(commitTime, jsc.parallelize(writeStatusList1));
        assertNoWriteErrors(writeStatusList1);
        // assert RLI records for a base file from 1st commit
        String finalCommitTime = commitTime;
        Map<String, String> recordKeyToPartitionMapping1 = new HashMap<>();
        Map<String, String> fileIdToFileNameMapping1 = new HashMap<>();
        writeStatusList1.forEach(writeStatus -> {
            assertEquals(writeStatus.getStat().getNumDeletes(), 0);
            // Fetch record keys for all
            String writeStatFileId = writeStatus.getFileId();
            if (!fileIdToFileNameMapping1.containsKey(writeStatFileId)) {
                fileIdToFileNameMapping1.put(writeStatFileId, writeStatus.getStat().getPath().substring(writeStatus.getStat().getPath().lastIndexOf("/") + 1));
            }
            // poll into generateRLIMetadataHoodieRecordsForBaseFile to fetch MDT RLI records for inserts and deletes.
            Iterator<HoodieRecord> rliRecordsItr = BaseFileRecordParsingUtils.generateRLIMetadataHoodieRecordsForBaseFile(metaClient.getBasePath().toString(), writeStatus.getStat(), writeConfig.getWritesFileIdEncoding(), finalCommitTime, metaClient.getStorage(), false);
            while (rliRecordsItr.hasNext()) {
                HoodieRecord rliRecord = rliRecordsItr.next();
                String key = rliRecord.getRecordKey();
                String partition = ((HoodieMetadataPayload) rliRecord.getData()).getDataPartition();
                recordKeyToPartitionMapping1.put(key, partition);
            }
        });
        Map<String, String> expectedRecordToPartitionMapping1 = new HashMap<>();
        records1.forEach(record -> expectedRecordToPartitionMapping1.put(record.getRecordKey(), record.getPartitionPath()));
        assertEquals(expectedRecordToPartitionMapping1, recordKeyToPartitionMapping1);
        // lets update some records and assert RLI records.
        commitTime = client.startCommit();
        String finalCommitTime2 = commitTime;
        List<HoodieRecord> deletes2 = dataGen.generateUniqueDeleteRecords(commitTime, 30);
        List<HoodieRecord> updates2 = dataGen.generateUniqueUpdates(commitTime, 30);
        List<HoodieRecord> inserts2 = dataGen.generateInserts(commitTime, 30);
        List<HoodieRecord> records2 = new ArrayList<>();
        records2.addAll(inserts2);
        records2.addAll(updates2);
        records2.addAll(deletes2);
        JavaRDD<WriteStatus> rawWriteStatuses2 = client.upsert(jsc.parallelize(records2, 1), commitTime);
        JavaRDD<WriteStatus> writeStatusesRDD2 = jsc.parallelize(rawWriteStatuses2.collect(), 1);
        List<WriteStatus> writeStatuses2 = writeStatusesRDD2.collect();
        assertNoWriteErrors(writeStatuses2);
        List<String> expectedInserts = inserts2.stream().map(record -> record.getKey().getRecordKey()).collect(Collectors.toList());
        List<String> expectedDeletes = deletes2.stream().map(record -> record.getKey().getRecordKey()).collect(Collectors.toList());
        List<String> actualInserts = new ArrayList<>();
        List<String> actualDeletes = new ArrayList<>();
        // only inserts and deletes will result in RLI records. lets validate that.
        generateRliRecordsAndAssert(writeStatuses2, fileIdToFileNameMapping1, finalCommitTime2, writeConfig, actualInserts, actualDeletes);
        assertListEquality(expectedInserts, actualInserts);
        assertListEquality(expectedDeletes, actualDeletes);
        // lets validate APIs in BaseFileParsingUtils directly
        actualInserts = new ArrayList<>();
        actualDeletes = new ArrayList<>();
        List<String> actualUpdates = new ArrayList<>();
        List<String> expectedUpdates = updates2.stream().map(record -> record.getKey().getRecordKey()).collect(Collectors.toList());
        parseRecordKeysFromBaseFiles(writeStatuses2, fileIdToFileNameMapping1, finalCommitTime2, writeConfig, actualInserts, actualDeletes, actualUpdates);
        assertListEquality(expectedInserts, actualInserts);
        assertListEquality(expectedDeletes, actualDeletes);
        // we can't really assert equality for updates. bcoz, w/ COW, we might just rewrite an existing parquet file. So, more records will be deduced as updates.
        // And so, we are validating using contains.
        expectedUpdates.forEach(entry -> assertTrue(actualUpdates.contains(entry)));
    }
}

