    // try setting multiple values as null
    // run it for 5 rounds
    for (int i = 0; i < 5; i++) {
        int numNullValues = 1 + RANDOM.nextInt(4);
        List<Integer> nullsSoFar = new ArrayList<>();
        while (nullsSoFar.size() < numNullValues) {
