    HoodieWriteConfig writeConfig1 = writeConfigBuilder.build();
    // clean every commit for writer2
    HoodieWriteConfig writeConfig2 = writeConfigBuilder.withCleanConfig(HoodieCleanConfig.newBuilder().withFailedWritesCleaningPolicy(HoodieFailedWritesCleaningPolicy.LAZY).withCleanerPolicy(HoodieCleaningPolicy.KEEP_LATEST_COMMITS).retainCommits(1).withAutoClean(false).build()).build();
    // Simulate the first commit with Writer 1
    final SparkRDDWriteClient client1 = getHoodieWriteClient(writeConfig1);
    final SparkRDDWriteClient client2 = getHoodieWriteClient(writeConfig2);
    createCommitWithInserts(writeConfig1, getHoodieWriteClient(writeConfig1), WriteClientTestUtils.createNewInstantTime(), WriteClientTestUtils.createNewInstantTime(), 200);
    // multi-writer setup
    final int threadCount = 2;
    final ExecutorService executors = Executors.newFixedThreadPool(threadCount);
    final CyclicBarrier cyclicBarrier = new CyclicBarrier(threadCount);
    final AtomicBoolean writer1Completed = new AtomicBoolean(false);
    final AtomicBoolean writer2Completed = new AtomicBoolean(false);
    // Writer 1 - Simulating the index update process
    Future future1 = executors.submit(() -> {
        try {
            final String nextCommitTime = WriteClientTestUtils.createNewInstantTime();
            final JavaRDD<WriteStatus> writeStatusList = startCommitForUpdate(writeConfig1, client1, nextCommitTime, 100);
            // Wait for Writer 2 to start cleaning
            cyclicBarrier.await(60, TimeUnit.SECONDS);
            // Commit the update including index update and assert no exceptions
            assertDoesNotThrow(() -> {
                client1.commit(nextCommitTime, writeStatusList);
            });
            // Signal Writer 2 to continue
            cyclicBarrier.await(60, TimeUnit.SECONDS);
            writer1Completed.set(true);
        } catch (Exception e) {
            writer1Completed.set(false);
        }
    });
    // Writer 2 - Simulating aggressive cleaning
    Future future2 = executors.submit(() -> {
        try {
            // Wait for Writer 1 to make progress
            cyclicBarrier.await(60, TimeUnit.SECONDS);
            // Simulate aggressive cleaning
            metaClient.reloadActiveTimeline();
            HoodieTable table = HoodieSparkTable.create(writeConfig2, context, metaClient);
            // clean old file slices
            table.clean(context, WriteClientTestUtils.createNewInstantTime());
            // Signal Writer 1 to complete its update
            cyclicBarrier.await(60, TimeUnit.SECONDS);
            writer2Completed.set(true);
        } catch (Exception e) {
            writer2Completed.set(false);
        }
    });
    // Wait for both writers to complete
    future1.get();
    future2.get();
    // Assertions to ensure both writers completed their operations
    assertTrue(writer1Completed.get() && writer2Completed.get());
    // Cleanup
    client1.close();
    client2.close();
}

@ParameterizedTest
@EnumSource(value = HoodieTableType.class, names = { "COPY_ON_WRITE", "MERGE_ON_READ" })
public void testMultiWriterWithAsyncTableServicesWithConflict(HoodieTableType tableType) throws Exception {
    // create inserts X 1
    if (tableType == HoodieTableType.MERGE_ON_READ) {
        setUpMORTestTable();
    }
    Properties properties = new Properties();
    properties.setProperty(FILESYSTEM_LOCK_PATH_PROP_KEY, basePath + "/.hoodie/.locks");
    // Disabling embedded timeline server, it doesn't work with multiwriter
    HoodieWriteConfig cfg = getConfigBuilder().withCompactionConfig(HoodieCompactionConfig.newBuilder().withInlineCompaction(false).withMaxNumDeltaCommitsBeforeCompaction(2).build()).withCleanConfig(HoodieCleanConfig.newBuilder().withAutoClean(false).withAsyncClean(true).withFailedWritesCleaningPolicy(HoodieFailedWritesCleaningPolicy.LAZY).build()).withEmbeddedTimelineServerEnabled(false).withFileSystemViewConfig(FileSystemViewStorageConfig.newBuilder().withStorageType(FileSystemViewStorageType.MEMORY).build()).withClusteringConfig(HoodieClusteringConfig.newBuilder().withInlineClusteringNumCommits(1).build()).withWriteConcurrencyMode(WriteConcurrencyMode.OPTIMISTIC_CONCURRENCY_CONTROL).withLockConfig(HoodieLockConfig.newBuilder().withLockProvider(InProcessLockProvider.class).withConflictResolutionStrategy(new PreferWriterConflictResolutionStrategy()).build()).withProperties(properties).build();
    Set<String> validInstants = new HashSet<>();
    // Create the first commit with inserts
    SparkRDDWriteClient client = getHoodieWriteClient(cfg);
    String instantTime1 = WriteClientTestUtils.createNewInstantTime();
    createCommitWithInserts(cfg, client, "000", instantTime1, 200);
    validInstants.add(instantTime1);
    // Create 2 commits with upserts
    String instantTime2 = WriteClientTestUtils.createNewInstantTime();
    createCommitWithUpserts(cfg, client, instantTime1, "000", instantTime2, 100);
    String instantTime3 = WriteClientTestUtils.createNewInstantTime();
    createCommitWithUpserts(cfg, client, instantTime2, "000", instantTime3, 100);
    validInstants.add(instantTime2);
    validInstants.add(instantTime3);
    ExecutorService executors = Executors.newFixedThreadPool(2);
    SparkRDDWriteClient client1 = getHoodieWriteClient(cfg);
    SparkRDDWriteClient<?> client2 = getHoodieWriteClient(cfg);
    // Create upserts, schedule cleaning, schedule compaction in parallel
    String instant4 = WriteClientTestUtils.createNewInstantTime();
    Future future1 = executors.submit(() -> {
        int numRecords = 100;
        String commitTimeBetweenPrevAndNew = instantTime2;
        try {
            // For both COW and MOR table types the commit should not be blocked, since we are giving preference to ingestion.
            createCommitWithUpserts(cfg, client1, instantTime3, commitTimeBetweenPrevAndNew, instant4, numRecords);
            validInstants.add(instant4);
        } catch (Exception e1) {
            throw new RuntimeException(e1);
        }
    });
    CompletableFuture<String> future2 = CompletableFuture.supplyAsync(() -> {
        try {
            return client2.scheduleTableService(Option.empty(), TableServiceType.COMPACT).get();
        } catch (Exception e2) {
            if (tableType == HoodieTableType.MERGE_ON_READ) {
                throw new RuntimeException(e2);
            }
            return null;
        }
    }, executors);
    CompletableFuture<String> future3 = CompletableFuture.supplyAsync(() -> {
        try {
            return client2.scheduleTableService(Option.empty(), TableServiceType.CLEAN).orElse(null);
        } catch (Exception e2) {
            throw new RuntimeException(e2);
        }
    });
    future1.get();
    String instant5 = future2.get();
    String instant6 = future3.get();
    // Create inserts, run cleaning, run compaction in parallel
    String instant7 = WriteClientTestUtils.createNewInstantTime();
    future1 = executors.submit(() -> {
        int numRecords = 100;
        try {
            createCommitWithInserts(cfg, client1, instantTime3, instant7, numRecords);
            validInstants.add(instant7);
        } catch (Exception e1) {
            throw new RuntimeException(e1);
        }
    });
    Future<?> future4 = executors.submit(() -> {
        try {
            HoodieWriteMetadata<JavaRDD<WriteStatus>> compactionMetadata = client2.compact(instant5);
            client2.commitCompaction(instant5, compactionMetadata, Option.empty());
            assertTrue(metaClient.reloadActiveTimeline().filterCompletedInstants().containsInstant(instant5));
            validInstants.add(instant5);
        } catch (Exception e2) {
            if (tableType == HoodieTableType.MERGE_ON_READ) {
                Assertions.assertTrue(e2 instanceof HoodieWriteConflictException);
            }
        }
    });
    Future<?> future5 = executors.submit(() -> {
        try {
            client2.clean();
            metaClient.reloadActiveTimeline().getCleanerTimeline().lastInstant().map(HoodieInstant::requestedTime).ifPresent(validInstants::add);
        } catch (Exception e2) {
            throw new RuntimeException(e2);
        }
    });
    future1.get();
    future4.get();
    future5.get();
    Set<String> completedInstants = metaClient.reloadActiveTimeline().getCommitsTimeline().filterCompletedInstants().getInstantsAsStream().map(HoodieInstant::requestedTime).collect(Collectors.toSet());
    Assertions.assertEquals(validInstants, completedInstants);
}

