@ParameterizedTest
@ValueSource(booleans = { true, false })
void testCustomMerging(boolean usePayload) throws IOException {
    // create a simple schema with _hoodie_is_delete field to track delete records
    Schema customSchema = Schema.createRecord("CustomRecord", null, null, false);
    Option<HoodieRecordMerger> recordMerger;
    Option<String> payloadClassName;
    if (usePayload) {
        recordMerger = Option.of(new HoodieAvroRecordMerger());
        payloadClassName = Option.of(CustomPayload.class.getName());
    } else {
        recordMerger = Option.of(new CustomMerger());
        payloadClassName = Option.empty();
    }
    customSchema.setFields(Arrays.asList(new Schema.Field("id", Schema.create(Schema.Type.STRING), null, null), new Schema.Field("name", Schema.create(Schema.Type.STRING), null, null), new Schema.Field("timestamp", Schema.create(Schema.Type.LONG), null, null), new Schema.Field(HoodieRecord.HOODIE_IS_DELETED_FIELD, Schema.create(Schema.Type.BOOLEAN))));
    // Configure reader context with custom schema
    props.setProperty(ORDERING_FIELDS.key(), "timestamp");
    HoodieAvroReaderContext avroReaderContext = new HoodieAvroReaderContext(storageConfig, tableConfig, Option.empty(), Option.empty());
    avroReaderContext.setHasLogFiles(false);
    avroReaderContext.setHasBootstrapBaseFile(false);
    HoodieTableMetaClient metaClient = mock(HoodieTableMetaClient.class);
    when(metaClient.getTableConfig()).thenReturn(tableConfig);
    avroReaderContext.setSchemaHandler(new FileGroupReaderSchemaHandler<>(avroReaderContext, customSchema, customSchema, Option.empty(), props, metaClient));
    avroReaderContext.getRecordContext().encodeAvroSchema(customSchema);
    BufferedRecordMerger<IndexedRecord> merger = BufferedRecordMergerFactory.create(avroReaderContext, RecordMergeMode.CUSTOM, false, recordMerger, payloadClassName, customSchema, props, Option.empty());
    GenericRecord record1 = createCustomRecord(customSchema, "1", "Alice", 1000L, false);
    BufferedRecord<IndexedRecord> bufferedRecord1 = new BufferedRecord<>("1", 1000L, record1, 0, null);
    GenericRecord record2 = createCustomRecord(customSchema, "1", "Bob", 2000L, false);
    BufferedRecord<IndexedRecord> bufferedRecord2 = new BufferedRecord<>("1", 2000L, record2, 0, null);
    GenericRecord record3 = createCustomRecord(customSchema, "1", "Charlie", 3000L, true);
    BufferedRecord<IndexedRecord> bufferedRecord3 = new BufferedRecord<>("1", 3000L, record3, 0, HoodieOperation.DELETE);
    GenericRecord record4 = createCustomRecord(customSchema, "1", "Dexter", 4000L, false);
    BufferedRecord<IndexedRecord> bufferedRecord4 = new BufferedRecord<>("1", 4000L, record4, 0, null);
    // Custom merger applies a reverse ordering so the earliest record is kept
    BufferedRecord<IndexedRecord> result = merger.finalMerge(bufferedRecord1, bufferedRecord2);
    assertEquals(bufferedRecord1, result);
    assertFalse(result.isDelete());
    result = merger.finalMerge(bufferedRecord2, bufferedRecord3);
    assertEquals(bufferedRecord2, result);
    assertFalse(result.isDelete());
    result = merger.finalMerge(bufferedRecord3, bufferedRecord4);
    assertEquals(bufferedRecord3, result);
    assertTrue(result.isDelete());
    // flip ordering with delete to ensure behavior is consistent
    result = merger.finalMerge(bufferedRecord4, bufferedRecord3);
    assertEquals(bufferedRecord3, result);
    assertTrue(result.isDelete());
    // Validate delta merge
    Option<BufferedRecord<IndexedRecord>> deltaMergeResult = merger.deltaMerge(bufferedRecord1, bufferedRecord2);
    assertTrue(deltaMergeResult.isPresent());
    assertEquals(bufferedRecord1, deltaMergeResult.get());
    assertFalse(deltaMergeResult.get().isDelete());
    deltaMergeResult = merger.deltaMerge(bufferedRecord2, bufferedRecord3);
    assertTrue(deltaMergeResult.isPresent());
    assertEquals(bufferedRecord2, deltaMergeResult.get());
    assertFalse(deltaMergeResult.get().isDelete());
    deltaMergeResult = merger.deltaMerge(bufferedRecord3, bufferedRecord4);
    assertTrue(deltaMergeResult.isPresent());
    assertEquals(bufferedRecord3, deltaMergeResult.get());
    assertTrue(deltaMergeResult.get().isDelete());
    // flip ordering and expect empty option
    assertTrue(merger.deltaMerge(bufferedRecord4, bufferedRecord3).isEmpty());
    assertTrue(merger.deltaMerge(bufferedRecord3, bufferedRecord2).isEmpty());
    assertTrue(merger.deltaMerge(bufferedRecord2, bufferedRecord1).isEmpty());
    // Validate merge with delete records
    DeleteRecord deleteRecordWithHigherOrderValue = DeleteRecord.create("1", "anyPath", 5000L);
    DeleteRecord deleteRecordWithLowerOrderValue = DeleteRecord.create("1", "anyPath", 1000L);
    Option<DeleteRecord> deleteResult = merger.deltaMerge(deleteRecordWithHigherOrderValue, bufferedRecord2);
    // delete is skipped because custom merger prefers lower ordering value
    assertFalse(deleteResult.isPresent());
    deleteResult = merger.deltaMerge(deleteRecordWithLowerOrderValue, bufferedRecord2);
    // delete is applied because lower ordering value is preferred
    assertTrue(deleteResult.isPresent());
    assertEquals(deleteRecordWithLowerOrderValue, deleteResult.get());
}

@Test
public void testColsStatsSerDe() throws Exception {
    Random random = new Random();
    // create a data table which will auto create mdt table as well
    HoodieWriteConfig cfg = getConfig();
    try (SparkRDDWriteClient client = getHoodieWriteClient(cfg)) {
        writeData(client, InProcessTimeGenerator.createNewInstantTime(), 100, false);
    }
    String fileName = "file.parquet";
    String targetColNamePrefix = "col";
    List<Pair<Comparable, Comparable>> minMaxValues = new ArrayList<>();
    // string
    minMaxValues.add(Pair.of("abcdec", "zyxwvu"));
    // Utf8
    minMaxValues.add(Pair.of(new Utf8(getUTF8Bytes("abcdec")), new Utf8(getUTF8Bytes("zyxwvu"))));
    // Int
    minMaxValues.add(Pair.of(new Integer(-1000), new Integer(999999)));
    // Long
    minMaxValues.add(Pair.of(new Long(-100000L), Long.MAX_VALUE));
    // boolean
    minMaxValues.add(Pair.of(false, true));
    // double
    minMaxValues.add(Pair.of(new Double(0.123), new Double(10.123)));
    // float
    minMaxValues.add(Pair.of(new Float(0.0123), new Float(200.123)));
    // Date
    minMaxValues.add(Pair.of(new Date(1000 * 60 * 60 * 10), new Date(1000 * 60 * 60 * 60)));
    // LocalDate
    minMaxValues.add(Pair.of(LocalDate.ofEpochDay(1000 * 60 * 60 * 10), LocalDate.ofEpochDay(1000 * 60 * 60 * 60)));
    // Timestamp
    minMaxValues.add(Pair.of(new Timestamp(1000 * 60 * 60 * 10), new Timestamp(1000 * 60 * 60 * 60)));
    minMaxValues.add(generateRandomMinMaxValue(random, (Functions.Function1<Random, Comparable>) random1 -> new Timestamp(random1.nextInt(1000) * 60 * 60 * 1000)));
    //Bytes
    byte[] bytes1 = new byte[10];
    byte[] bytes2 = new byte[10];
    random.nextBytes(bytes1);
    random.nextBytes(bytes2);
    ByteBuffer val1ByteBuffer = ByteBuffer.wrap(bytes1);
    ByteBuffer val2ByteBuffer = ByteBuffer.wrap(bytes2);
    Comparable minValue = val1ByteBuffer;
    Comparable maxValue = val2ByteBuffer;
    if (val1ByteBuffer.compareTo(val2ByteBuffer) >= 0) {
        minValue = val2ByteBuffer;
        maxValue = val1ByteBuffer;
    }
    minMaxValues.add(Pair.of(minValue, maxValue));
    // Big Decimal
    BigDecimal val1 = new BigDecimal(String.format(Locale.ENGLISH, "%5f", random.nextFloat()));
    BigDecimal val2 = new BigDecimal(String.format(Locale.ENGLISH, "%5f", random.nextFloat()));
    if (val1.compareTo(val2) > 0) {
        minMaxValues.add(Pair.of(val2, val1));
    } else {
        minMaxValues.add(Pair.of(val1, val2));
    }
    List<HoodieColumnRangeMetadata<Comparable>> columnRangeMetadata = new ArrayList<>();
    AtomicInteger counter = new AtomicInteger();
    AtomicInteger finalCounter1 = counter;
    minMaxValues.forEach(entry -> {
        columnRangeMetadata.add(HoodieColumnRangeMetadata.<Comparable>create(fileName, targetColNamePrefix + "_" + (finalCounter1.getAndIncrement()), entry.getKey(), entry.getValue(), 5, 1000, 123456, 123456, ValueMetadata.V1EmptyMetadata.get()));
    });
    // create mdt records
    List<HoodieRecord<HoodieMetadataPayload>> columnStatsRecords = HoodieMetadataPayload.createColumnStatsRecords("p1", columnRangeMetadata, false).map(record -> (HoodieRecord<HoodieMetadataPayload>) record).collect(Collectors.toList());
    Collections.sort(columnStatsRecords, new Comparator<HoodieRecord<HoodieMetadataPayload>>() {

        @Override
        public int compare(HoodieRecord<HoodieMetadataPayload> o1, HoodieRecord<HoodieMetadataPayload> o2) {
            return o1.getRecordKey().compareTo(o2.getRecordKey());
        }
    });
    List<HoodieRecord<HoodieMetadataPayload>> expectedColumnStatsRecords = HoodieMetadataPayload.createColumnStatsRecords("p1", columnRangeMetadata, false).map(record -> (HoodieRecord<HoodieMetadataPayload>) record).collect(Collectors.toList());
    Collections.sort(expectedColumnStatsRecords, new Comparator<HoodieRecord<HoodieMetadataPayload>>() {

        @Override
        public int compare(HoodieRecord<HoodieMetadataPayload> o1, HoodieRecord<HoodieMetadataPayload> o2) {
            return o1.getRecordKey().compareTo(o2.getRecordKey());
        }
    });
    HoodieWriteConfig mdtWriteConfig = HoodieMetadataWriteUtils.createMetadataWriteConfig(cfg, HoodieFailedWritesCleaningPolicy.EAGER, HoodieTableVersion.EIGHT);
    HoodieTableMetaClient mdtMetaClient = HoodieTableMetaClient.builder().setBasePath(mdtWriteConfig.getBasePath()).setConf(context.getStorageConf().newInstance()).build();
    HoodieTable table = HoodieSparkTable.create(mdtWriteConfig, context, mdtMetaClient);
    String newCommitTime = InProcessTimeGenerator.createNewInstantTime();
    HoodieCreateHandle handle = new HoodieCreateHandle(mdtWriteConfig, newCommitTime, table, COLUMN_STATS.getPartitionPath(), "col-stats-00001-0", new PhoneyTaskContextSupplier());
    // write the record to hfile.
    Schema writeSchema = AvroSchemaCache.intern(new Schema.Parser().parse(mdtWriteConfig.getSchema()));
    TypedProperties properties = new TypedProperties();
    columnStatsRecords.forEach(record -> handle.write(record, writeSchema, properties));
    WriteStatus writeStatus = (WriteStatus) handle.close().get(0);
    String filePath = writeStatus.getStat().getPath();
    // read the hfile using base file reader.
    StoragePath baseFilePath = new StoragePath(mdtMetaClient.getBasePath() + "/" + filePath);
    HoodieSeekingFileReader baseFileReader = (HoodieSeekingFileReader<?>) HoodieIOFactory.getIOFactory(mdtMetaClient.getStorage()).getReaderFactory(HoodieRecord.HoodieRecordType.AVRO).getFileReader(DEFAULT_HUDI_CONFIG_FOR_READER, baseFilePath);
    ClosableIterator itr = baseFileReader.getRecordIterator();
    List<HoodieRecord<HoodieMetadataPayload>> allRecords = new ArrayList<>();
    while (itr.hasNext()) {
        GenericRecord genericRecord = (GenericRecord) ((HoodieRecord) itr.next()).getData();
        HoodieRecord<HoodieMetadataPayload> mdtRec = SpillableMapUtils.convertToHoodieRecordPayload(genericRecord, mdtWriteConfig.getPayloadClass(), new String[0], Pair.of(mdtMetaClient.getTableConfig().getRecordKeyFieldProp(), mdtMetaClient.getTableConfig().getPartitionFieldProp()), false, Option.of(COLUMN_STATS.getPartitionPath()), Option.empty());
        allRecords.add(mdtRec);
    }
    assertEquals(columnStatsRecords.size(), allRecords.size());
    // validate the min and max values.
    counter = new AtomicInteger(0);
    AtomicInteger finalCounter = counter;
    allRecords.forEach(record -> {
        HoodieMetadataColumnStats actualColStatsMetadata = record.getData().getColumnStatMetadata().get();
        HoodieMetadataColumnStats expectedColStatsMetadata = expectedColumnStatsRecords.get(finalCounter.getAndIncrement()).getData().getColumnStatMetadata().get();
        LOG.info("Validating " + expectedColStatsMetadata.getColumnName() + ", " + expectedColStatsMetadata.getMinValue().getClass().getSimpleName());
        if (expectedColStatsMetadata.getMinValue().getClass().getSimpleName().equals(DecimalWrapper.class.getSimpleName())) {
            // Big decimal gets wrapped w/ Decimal wrapper and converts to bytes.
            assertEquals(expectedColStatsMetadata.getMinValue().toString(), actualColStatsMetadata.getMinValue().toString());
            assertEquals(expectedColStatsMetadata.getMaxValue().toString(), actualColStatsMetadata.getMaxValue().toString());
        } else {
            assertEquals(expectedColStatsMetadata.getMinValue(), actualColStatsMetadata.getMinValue());
            assertEquals(expectedColStatsMetadata.getMaxValue(), actualColStatsMetadata.getMaxValue());
        }
    });
}

