@Test
public void testGetColumnRangeInPartition() {
    String relativePartitionPath = "relativePartitionPath";
    String fileName = "file1";
    String colName = "colA";
    long nullCount = 10;
    long valueCount = 100;
    long totalSize = 10000;
    long totalUncompressedSize = 1000;
    // Integer vals
    HoodieColumnRangeMetadata aIntegerVal = HoodieColumnRangeMetadata.create(fileName, colName, (Integer) 1, (Integer) 1000, nullCount, valueCount, totalSize, totalUncompressedSize, ValueMetadata.V1EmptyMetadata.get());
    HoodieColumnRangeMetadata bIntegerVal = HoodieColumnRangeMetadata.create(fileName, colName, (Integer) (-1), (Integer) 10000, nullCount, valueCount, totalSize, totalUncompressedSize, ValueMetadata.V1EmptyMetadata.get());
    // Long vals
    HoodieColumnRangeMetadata aLongVal = HoodieColumnRangeMetadata.create(fileName, colName, (Long) 1L, (Long) 1000L, nullCount, valueCount, totalSize, totalUncompressedSize, ValueMetadata.V1EmptyMetadata.get());
    HoodieColumnRangeMetadata bLongVal = HoodieColumnRangeMetadata.create(fileName, colName, (Long) (-1L), (Long) 10000L, nullCount, valueCount, totalSize, totalUncompressedSize, ValueMetadata.V1EmptyMetadata.get());
    // Float vals
    HoodieColumnRangeMetadata aFloatVal = HoodieColumnRangeMetadata.create(fileName, colName, new Float(1), new Float(1000.0), nullCount, valueCount, totalSize, totalUncompressedSize, ValueMetadata.V1EmptyMetadata.get());
    HoodieColumnRangeMetadata bFloatVal = HoodieColumnRangeMetadata.create(fileName, colName, new Float(-1.0), new Float(10000.0), nullCount, valueCount, totalSize, totalUncompressedSize, ValueMetadata.V1EmptyMetadata.get());
    // Double vals
    HoodieColumnRangeMetadata aDoubleVal = HoodieColumnRangeMetadata.create(fileName, colName, new Double(0.1), new Double(1000.0), nullCount, valueCount, totalSize, totalUncompressedSize, ValueMetadata.V1EmptyMetadata.get());
    HoodieColumnRangeMetadata bDoubleVal = HoodieColumnRangeMetadata.create(fileName, colName, new Double(-1.0), new Double(10000.0), nullCount, valueCount, totalSize, totalUncompressedSize, ValueMetadata.V1EmptyMetadata.get());
    // String vals
    HoodieColumnRangeMetadata aStringVal = HoodieColumnRangeMetadata.create(fileName, colName, new String("1"), new String("1000"), nullCount, valueCount, totalSize, totalUncompressedSize, ValueMetadata.V1EmptyMetadata.get());
    HoodieColumnRangeMetadata bStringVal = HoodieColumnRangeMetadata.create(fileName, colName, new String("-1"), new String("10000"), nullCount, valueCount, totalSize, totalUncompressedSize, ValueMetadata.V1EmptyMetadata.get());
    // Merging Integer and Integer.
    HoodieColumnRangeMetadata actualColumnRange = mergeAndAssert(aIntegerVal, bIntegerVal, relativePartitionPath, colName, nullCount, totalSize, totalUncompressedSize, Schema.Type.INT);
    assertEquals(actualColumnRange.getMinValue(), (Integer) (-1));
    assertEquals(actualColumnRange.getMaxValue(), (Integer) (10000));
    // Merging Integer and Long.
    actualColumnRange = mergeAndAssert(aIntegerVal, bLongVal, relativePartitionPath, colName, nullCount, totalSize, totalUncompressedSize, Schema.Type.INT);
    assertEquals(actualColumnRange.getMinValue(), (Integer) (-1));
    assertEquals(actualColumnRange.getMaxValue(), (Integer) (10000));
    // Merging Integer and Float
    actualColumnRange = mergeAndAssert(aIntegerVal, bFloatVal, relativePartitionPath, colName, nullCount, totalSize, totalUncompressedSize, Schema.Type.INT);
    assertEquals(actualColumnRange.getMinValue(), (Integer) (-1));
    assertEquals(actualColumnRange.getMaxValue(), (Integer) (10000));
    // Merging Integer and Double
    actualColumnRange = mergeAndAssert(aIntegerVal, bDoubleVal, relativePartitionPath, colName, nullCount, totalSize, totalUncompressedSize, Schema.Type.INT);
    assertEquals(actualColumnRange.getMinValue(), (Integer) (-1));
    assertEquals(actualColumnRange.getMaxValue(), (Integer) (10000));
    // Merging Integer and String
    actualColumnRange = mergeAndAssert(aIntegerVal, bStringVal, relativePartitionPath, colName, nullCount, totalSize, totalUncompressedSize, Schema.Type.INT);
    assertEquals(actualColumnRange.getMinValue(), (Integer) (-1));
    assertEquals(actualColumnRange.getMaxValue(), (Integer) (10000));
    // Long and Long
    actualColumnRange = mergeAndAssert(aLongVal, bLongVal, relativePartitionPath, colName, nullCount, totalSize, totalUncompressedSize, Schema.Type.LONG);
    assertEquals(actualColumnRange.getMinValue(), (Long) (-1L));
    assertEquals(actualColumnRange.getMaxValue(), (Long) (10000L));
    // Merging Long and Integer
    actualColumnRange = mergeAndAssert(aLongVal, bIntegerVal, relativePartitionPath, colName, nullCount, totalSize, totalUncompressedSize, Schema.Type.LONG);
    assertEquals(actualColumnRange.getMinValue(), (Long) (-1L));
    assertEquals(actualColumnRange.getMaxValue(), (Long) (10000L));
    // Merging Long and Float
    actualColumnRange = mergeAndAssert(aLongVal, bFloatVal, relativePartitionPath, colName, nullCount, totalSize, totalUncompressedSize, Schema.Type.LONG);
    assertEquals(actualColumnRange.getMinValue(), (Long) (-1L));
    assertEquals(actualColumnRange.getMaxValue(), (Long) (10000L));
    // Merging Long and Double
    actualColumnRange = mergeAndAssert(aLongVal, bDoubleVal, relativePartitionPath, colName, nullCount, totalSize, totalUncompressedSize, Schema.Type.LONG);
    assertEquals(actualColumnRange.getMinValue(), (Long) (-1L));
    assertEquals(actualColumnRange.getMaxValue(), (Long) (10000L));
    // Merging Long and String
    actualColumnRange = mergeAndAssert(aLongVal, bStringVal, relativePartitionPath, colName, nullCount, totalSize, totalUncompressedSize, Schema.Type.LONG);
    assertEquals(actualColumnRange.getMinValue(), (Long) (-1L));
    assertEquals(actualColumnRange.getMaxValue(), (Long) (10000L));
    // Float and Float
    actualColumnRange = mergeAndAssert(aFloatVal, bFloatVal, relativePartitionPath, colName, nullCount, totalSize, totalUncompressedSize, Schema.Type.FLOAT);
    assertEquals(actualColumnRange.getMinValue(), new Float(-1));
    assertEquals(actualColumnRange.getMaxValue(), new Float(10000));
    // Merging Float and Integer
    actualColumnRange = mergeAndAssert(aFloatVal, bIntegerVal, relativePartitionPath, colName, nullCount, totalSize, totalUncompressedSize, Schema.Type.FLOAT);
    assertEquals(actualColumnRange.getMinValue(), new Float(-1));
    assertEquals(actualColumnRange.getMaxValue(), new Float(10000));
    // Merging Float and Long.
    actualColumnRange = mergeAndAssert(aFloatVal, bLongVal, relativePartitionPath, colName, nullCount, totalSize, totalUncompressedSize, Schema.Type.FLOAT);
    assertEquals(actualColumnRange.getMinValue(), new Float(-1));
    assertEquals(actualColumnRange.getMaxValue(), new Float(10000));
    // Merging Float and String
    actualColumnRange = mergeAndAssert(aFloatVal, bStringVal, relativePartitionPath, colName, nullCount, totalSize, totalUncompressedSize, Schema.Type.FLOAT);
    assertEquals(actualColumnRange.getMinValue(), new Float(-1));
    assertEquals(actualColumnRange.getMaxValue(), new Float(10000));
    // Double and Double
    actualColumnRange = mergeAndAssert(aDoubleVal, bDoubleVal, relativePartitionPath, colName, nullCount, totalSize, totalUncompressedSize, Schema.Type.DOUBLE);
    assertEquals(actualColumnRange.getMinValue(), new Double(-1));
    assertEquals(actualColumnRange.getMaxValue(), new Double(10000));
    // Merging Double and Integer
    actualColumnRange = mergeAndAssert(aDoubleVal, bIntegerVal, relativePartitionPath, colName, nullCount, totalSize, totalUncompressedSize, Schema.Type.DOUBLE);
    assertEquals(actualColumnRange.getMinValue(), new Double(-1));
    assertEquals(actualColumnRange.getMaxValue(), new Double(10000));
    // Merging Double and Long.
    actualColumnRange = mergeAndAssert(aDoubleVal, bLongVal, relativePartitionPath, colName, nullCount, totalSize, totalUncompressedSize, Schema.Type.DOUBLE);
    assertEquals(actualColumnRange.getMinValue(), new Double(-1));
    assertEquals(actualColumnRange.getMaxValue(), new Double(10000));
    // Merging Double and String
    actualColumnRange = mergeAndAssert(aDoubleVal, bStringVal, relativePartitionPath, colName, nullCount, totalSize, totalUncompressedSize, Schema.Type.DOUBLE);
    assertTrue(actualColumnRange.getMinValue().compareTo(new Double(-1)) == 0);
    assertTrue(actualColumnRange.getMaxValue().compareTo(new Double(10000)) == 0);
}

/**
 * Test bucket index tagging (always tag regardless of the write status)
 * Test bucket index tagging consistency, two tagging result should be same
 *
 * @param populateMetaFields
 * @param partitioned
 * @throws Exception
 */
@ParameterizedTest
@MethodSource("configParams")
public void testTagLocation(boolean populateMetaFields, boolean partitioned) throws Exception {
    setUp(populateMetaFields, partitioned);
    String newCommitTime = "001";
    int totalRecords = 20 + random.nextInt(20);
    List<HoodieRecord> records = dataGen.generateInserts(newCommitTime, totalRecords);
    JavaRDD<HoodieRecord> writeRecords = jsc.parallelize(records, 2);
    metaClient = HoodieTableMetaClient.reload(metaClient);
    HoodieTable hoodieTable = HoodieSparkTable.create(config, context, metaClient);
    // The records should be tagged anyway, even though it is the first time doing tagging
    List<HoodieRecord> taggedRecord = tagLocation(index, writeRecords, hoodieTable).collect();
    Assertions.assertTrue(taggedRecord.stream().allMatch(r -> r.isCurrentLocationKnown()));
    // Tag again, the records should get the same location (hashing metadata has been persisted after the first tagging)
    List<HoodieRecord> taggedRecord2 = tagLocation(index, writeRecords, hoodieTable).collect();
    for (HoodieRecord ref : taggedRecord) {
        for (HoodieRecord record : taggedRecord2) {
            if (ref.getRecordKey().equals(record.getRecordKey())) {
                Assertions.assertEquals(ref.getCurrentLocation(), record.getCurrentLocation());
                break;
            }
        }
    }
}

@ParameterizedTest
@MethodSource("configParams")
public void testWriteData(boolean populateMetaFields, boolean partitioned) throws Exception {
    setUp(populateMetaFields, partitioned);
    String newCommitTime = "001";
    int totalRecords = 20 + random.nextInt(20);
    List<HoodieRecord> records = dataGen.generateInserts(newCommitTime, totalRecords);
    JavaRDD<HoodieRecord> writeRecords = jsc.parallelize(records, 2);
    // Insert totalRecords records
    List<WriteStatus> writeStatues = writeData(writeRecords, newCommitTime, WriteOperationType.UPSERT, true);
    // The number of distinct fileId should be the same as total log file numbers
    Assertions.assertEquals(writeStatues.stream().map(WriteStatus::getFileId).distinct().count(), Arrays.stream(dataGen.getPartitionPaths()).mapToInt(p -> Objects.requireNonNull(listStatus(p, true)).length).sum());
    Assertions.assertEquals(totalRecords, readRecordsNum(dataGen.getPartitionPaths(), populateMetaFields));
    // Upsert the same set of records, the number of records should be same
    writeData(writeRecords, "002", WriteOperationType.UPSERT, true);
    // The number of log file should double after this insertion
    long numberOfLogFiles = Arrays.stream(dataGen.getPartitionPaths()).mapToInt(p -> {
        return Arrays.stream(listStatus(p, true)).mapToInt(fs -> fs instanceof RealtimeFileStatus ? ((RealtimeFileStatus) fs).getDeltaLogFiles().size() : 1).sum();
    }).sum();
    Assertions.assertEquals(writeStatues.stream().map(WriteStatus::getFileId).distinct().count() * 2, numberOfLogFiles);
    // The record number should remain same because of deduplication
    Assertions.assertEquals(totalRecords, readRecordsNum(dataGen.getPartitionPaths(), populateMetaFields));
    // Upsert new set of records, and validate the total number of records
    writeData("003", totalRecords, true);
    Assertions.assertEquals(totalRecords * 2, readRecordsNum(dataGen.getPartitionPaths(), populateMetaFields));
}

@ParameterizedTest
@MethodSource("configParams")
public void testWriteDataWithCompaction(boolean populateMetaFields, boolean partitioned) throws Exception {
    setUp(populateMetaFields, partitioned);
    writeData(WriteClientTestUtils.createNewInstantTime(), 200, true);
    config.setValue(INLINE_COMPACT_NUM_DELTA_COMMITS, "1");
    config.setValue(INLINE_COMPACT_TRIGGER_STRATEGY, CompactionTriggerStrategy.NUM_COMMITS.name());
    String compactionTime = (String) writeClient.scheduleCompaction(Option.empty()).get();
    Assertions.assertEquals(200, readRecordsNum(dataGen.getPartitionPaths(), populateMetaFields));
    writeData(WriteClientTestUtils.createNewInstantTime(), 200, true);
    Assertions.assertEquals(400, readRecordsNum(dataGen.getPartitionPaths(), populateMetaFields));
    HoodieWriteMetadata<JavaRDD<WriteStatus>> compactionMetadata = writeClient.compact(compactionTime);
    writeClient.commitCompaction(compactionTime, compactionMetadata, Option.empty());
    assertTrue(metaClient.reloadActiveTimeline().filterCompletedInstants().containsInstant(compactionTime));
    Assertions.assertEquals(400, readRecordsNum(dataGen.getPartitionPaths(), populateMetaFields));
}

@ParameterizedTest
@MethodSource("configParams")
public void testBulkInsertData(boolean populateMetaFields, boolean partitioned) throws Exception {
    setUp(populateMetaFields, partitioned);
    String newCommitTime = "001";
    int totalRecords = 20 + random.nextInt(20);
    List<HoodieRecord> records = dataGen.generateInserts(newCommitTime, totalRecords);
    JavaRDD<HoodieRecord> writeRecords = jsc.parallelize(records, 2);
    // Bulk insert totalRecords records
    List<WriteStatus> writeStatues = writeData(writeRecords, newCommitTime, WriteOperationType.BULK_INSERT, true);
    // The number of distinct fileId should be the same as total file group numbers
    long numFilesCreated = writeStatues.stream().map(WriteStatus::getFileId).distinct().count();
    Assertions.assertEquals(numFilesCreated, Arrays.stream(dataGen.getPartitionPaths()).mapToInt(p -> Objects.requireNonNull(listStatus(p, true)).length).sum());
    // Upsert Data
    writeData(writeRecords, "002", WriteOperationType.UPSERT, true);
    // The total number of file group should be the same, but each file group will have a log file.
    Assertions.assertEquals(numFilesCreated, Arrays.stream(dataGen.getPartitionPaths()).mapToInt(p -> Objects.requireNonNull(listStatus(p, true)).length).sum());
    long numberOfLogFiles = Arrays.stream(dataGen.getPartitionPaths()).mapToInt(p -> {
        return Arrays.stream(listStatus(p, true)).mapToInt(fs -> fs instanceof RealtimeFileStatus ? ((RealtimeFileStatus) fs).getDeltaLogFiles().size() : 1).sum();
    }).sum();
    Assertions.assertEquals(numFilesCreated, numberOfLogFiles);
    // The record number should be doubled if we disable the merge
    storageConf.set("hoodie.realtime.merge.skip", "true");
    Assertions.assertEquals(totalRecords * 2, readRecordsNum(dataGen.getPartitionPaths(), populateMetaFields));
}

