/**
 * First attempt at bootstrap failed but the file slices get created. The next bootstrap should continue successfully.
 */
@Test
public void testFailedBootstrap() throws Exception {
    init(HoodieTableType.COPY_ON_WRITE);
    HoodieSparkEngineContext engineContext = new HoodieSparkEngineContext(jsc);
    // Config with 5 fileGroups for record index
    HoodieWriteConfig writeConfig = getWriteConfigBuilder(true, true, false).withMetadataConfig(HoodieMetadataConfig.newBuilder().enable(true).withEnableRecordIndex(true).withRecordIndexFileGroupCount(5, 5).build()).build();
    try (SparkRDDWriteClient client = new SparkRDDWriteClient(engineContext, writeConfig)) {
        // Write
        String newCommitTime = client.startCommit();
        List<HoodieRecord> records = dataGen.generateInserts(newCommitTime, 100);
        List<WriteStatus> writeStatuses = client.insert(jsc.parallelize(records, 1), newCommitTime).collect();
        assertNoWriteErrors(writeStatuses);
        client.commit(newCommitTime, jsc.parallelize(writeStatuses));
        validateMetadata(client);
        // Metadata table should exist
        final StoragePath metadataTablePath = new StoragePath(getMetadataTableBasePath(writeConfig.getBasePath()));
        assertTrue(storage.exists(metadataTablePath));
        metaClient = HoodieTableMetaClient.reload(metaClient);
        assertTrue(metaClient.getTableConfig().isMetadataTableAvailable());
        // File groups should be created as in the config
        HoodieBackedTableMetadata metadataReader = (HoodieBackedTableMetadata) metadata(client, storage);
        assertEquals(HoodieTableMetadataUtil.getPartitionLatestFileSlices(metadataReader.getMetadataMetaClient(), Option.empty(), MetadataPartitionType.FILES.getPartitionPath()).size(), 1);
        assertEquals(HoodieTableMetadataUtil.getPartitionLatestFileSlices(metadataReader.getMetadataMetaClient(), Option.empty(), RECORD_INDEX.getPartitionPath()).size(), 5);
    }
    // remove the MDT partition from dataset to simulate failed bootstrap
    Properties updateProperties = new Properties();
    updateProperties.setProperty(HoodieTableConfig.TABLE_METADATA_PARTITIONS.key(), "");
    HoodieTableConfig.update(storage, new StoragePath(basePath + StoragePath.SEPARATOR + METAFOLDER_NAME), updateProperties);
    metaClient = HoodieTableMetaClient.reload(metaClient);
    assertFalse(metaClient.getTableConfig().isMetadataTableAvailable());
    // Config with 3 fileGroups for record index
    writeConfig = getWriteConfigBuilder(true, true, false).withMetadataConfig(HoodieMetadataConfig.newBuilder().enable(true).withEnableRecordIndex(true).withRecordIndexFileGroupCount(3, 3).build()).build();
    // Another commit which should bootstrap the MDT again
    try (SparkRDDWriteClient client = new SparkRDDWriteClient(engineContext, writeConfig)) {
        // Write
        String newCommitTime = client.startCommit();
        List<HoodieRecord> records = dataGen.generateInserts(newCommitTime, 100);
        List<WriteStatus> writeStatuses = client.insert(jsc.parallelize(records, 1), newCommitTime).collect();
        assertNoWriteErrors(writeStatuses);
        client.commit(newCommitTime, jsc.parallelize(writeStatuses));
        // Metadata table is recreated, during bootstrapping of metadata table.
        metaClient = HoodieTableMetaClient.reload(metaClient);
        assertTrue(metaClient.getTableConfig().isMetadataTableAvailable());
        validateMetadata(client);
        // File groups should be created as in the config
        HoodieBackedTableMetadata metadataReader = (HoodieBackedTableMetadata) metadata(client, storage);
        assertEquals(HoodieTableMetadataUtil.getPartitionLatestFileSlices(metadataReader.getMetadataMetaClient(), Option.empty(), MetadataPartitionType.FILES.getPartitionPath()).size(), 1);
        assertEquals(HoodieTableMetadataUtil.getPartitionLatestFileSlices(metadataReader.getMetadataMetaClient(), Option.empty(), RECORD_INDEX.getPartitionPath()).size(), 3);
    }
}

