@ParameterizedTest
@MethodSource("tableTypeMetadataFSVTypeArgs")
public void testFileSystemViewConsistency(HoodieTableType tableType, boolean enableMdt, FileSystemViewStorageType storageType, int writeVersion) throws IOException {
    metaClient.getStorage().deleteDirectory(new StoragePath(basePath));
    this.tableType = tableType;
    Properties properties = new Properties();
    properties.setProperty(HoodieWriteConfig.WRITE_TABLE_VERSION.key(), Integer.toString(writeVersion));
    properties.setProperty(HoodieTableConfig.VERSION.key(), Integer.toString(writeVersion));
    properties.setProperty(HoodieTableConfig.TIMELINE_LAYOUT_VERSION.key(), writeVersion == 6 ? Integer.toString(TimelineLayoutVersion.LAYOUT_VERSION_1.getVersion()) : Integer.toString(TimelineLayoutVersion.LAYOUT_VERSION_2.getVersion()));
    initMetaClient(tableType, properties);
    HoodieWriteConfig.Builder configBuilder = getConfigBuilder();
    if (tableType == HoodieTableType.MERGE_ON_READ) {
        configBuilder.withCompactionConfig(HoodieCompactionConfig.newBuilder().withInlineCompaction(true).withMaxNumDeltaCommitsBeforeCompaction(3).build());
    }
    configBuilder.withFileSystemViewConfig(FileSystemViewStorageConfig.newBuilder().withStorageType(storageType).build()).withMetadataConfig(HoodieMetadataConfig.newBuilder().enable(enableMdt).build()).withClusteringConfig(HoodieClusteringConfig.newBuilder().withInlineClustering(true).withInlineClusteringNumCommits(5).build()).withCleanConfig(HoodieCleanConfig.newBuilder().retainCommits(4).build()).// set aggressive values so that within 20 batches few iterations of cleaner and archival will kick in
    withArchivalConfig(HoodieArchivalConfig.newBuilder().archiveCommitsWith(6, 8).build()).withWriteTableVersion(writeVersion);
    HoodieWriteConfig config = configBuilder.build();
    try (SparkRDDWriteClient client = getHoodieWriteClient(config)) {
        insertRecords(client, 100, WriteOperationType.BULK_INSERT);
        insertRecords(client, 100, WriteOperationType.INSERT);
        metaClient = HoodieTableMetaClient.reload(metaClient);
        // base line file system view is in-memory for any combination.
        HoodieTableFileSystemView expectedFileSystemView = FileSystemViewManager.createInMemoryFileSystemView(context, metaClient, HoodieMetadataConfig.newBuilder().enable(false).build());
        // to be compared against.
        // if no mdt enabled, compare w/ spillable.
        // if mdt is enabled, depending on storage type, either it will be mdt fsv or spillable fsv w/ mdt enabled.
        FileSystemViewStorageConfig viewStorageConfig = FileSystemViewStorageConfig.newBuilder().fromProperties(config.getProps()).withStorageType(storageType).build();
        HoodieTableFileSystemView actualFileSystemView = (HoodieTableFileSystemView) FileSystemViewManager.createViewManager(context, config.getMetadataConfig(), viewStorageConfig, config.getCommonConfig(), (SerializableFunctionUnchecked<HoodieTableMetaClient, HoodieTableMetadata>) v1 -> metaClient.getTableFormat().getMetadataFactory().create(context, metaClient.getStorage(), config.getMetadataConfig(), config.getBasePath())).getFileSystemView(basePath);
        assertFileSystemViews(config, enableMdt, storageType);
        for (int i = 3; i < 10; i++) {
            upsertRecords(client, 50);
        }
        expectedFileSystemView.sync();
        actualFileSystemView.sync();
        assertForFSVEquality(expectedFileSystemView, actualFileSystemView, enableMdt, Option.empty());
        for (int i = 10; i < 23; i++) {
            upsertRecords(client, 50);
        }
        HoodieCommitMetadata commitMetadata = null;
        boolean rollbackExecuted = false;
        for (int i = 23; i < 26; i++) {
            // We want to rollback deltacommit and commit instant here. With table version 6 and 8,
            // the last instant can be compaction in MDT table at different instants due to change in how the
            // MDT tables are initialised. Therefore we need to take a range of commits and see at what instant rollback
            // is feasible
            upsertRecords(client, 50);
            HoodieInstant lastInstant = metaClient.reloadActiveTimeline().getWriteTimeline().lastInstant().get();
            if (!rollbackExecuted) {
                // rollback needs to be performed for delta commit or commit instant
                if (isRollbackPossible(enableMdt, lastInstant)) {
                    // rollback last completed deltacommit or commit operation and retry few more operations.
                    commitMetadata = metaClient.getActiveTimeline().readCommitMetadata(lastInstant);
                    client.rollback(lastInstant.requestedTime());
                    rollbackExecuted = true;
                }
            }
        }
        // validate rollback was executed
        assertTrue(rollbackExecuted);
        expectedFileSystemView.sync();
        actualFileSystemView.sync();
        // pass the commit metadata for the instant being deleted (mimic failure). so that we can account for during validation with table version 6.
        assertForFSVEquality(expectedFileSystemView, actualFileSystemView, enableMdt, metaClient.getTableConfig().getTableVersion().greaterThanOrEquals(HoodieTableVersion.EIGHT) ? Option.empty() : Option.of(commitMetadata));
        // add few more updates
        for (int i = 26; i < 28; i++) {
            upsertRecords(client, 50);
        }
        actualFileSystemView.close();
        expectedFileSystemView.close();
    }
    assertFileSystemViews(config, enableMdt, storageType);
}

@ParameterizedTest
@MethodSource("indexTypeParams")
public void testSimpleTagLocationAndUpdateWithRollback(IndexType indexType, boolean populateMetaFields, boolean enableMetadataIndex) throws Exception {
    setUp(indexType, populateMetaFields, enableMetadataIndex);
    final int totalRecords = 4;
    List<HoodieRecord> records = getInserts();
    JavaRDD<HoodieRecord> writtenRecords = jsc.parallelize(records, 1);
    metaClient = HoodieTableMetaClient.reload(metaClient);
    HoodieTable hoodieTable = HoodieSparkTable.create(config, context, metaClient);
    // Test tagLocation without any entries in index
    JavaRDD<HoodieRecord> javaRDD = tagLocation(index, writtenRecords, hoodieTable);
    assertTrue(javaRDD.filter(record -> record.isCurrentLocationKnown()).collect().isEmpty());
    // Insert totalRecords records
    String newCommitTime = writeClient.startCommit();
    JavaRDD<WriteStatus> writeStatusRdd = writeClient.upsert(writtenRecords, newCommitTime);
    List<WriteStatus> writeStatuses = writeStatusRdd.collect();
    assertNoWriteErrors(writeStatuses);
    String[] fileIdsFromWriteStatuses = writeStatuses.stream().map(WriteStatus::getFileId).sorted().toArray(String[]::new);
    // Now tagLocation for these records, index should not tag them since it was a failed
    // commit
    javaRDD = tagLocation(index, writtenRecords, hoodieTable);
    assertTrue(javaRDD.filter(record -> record.isCurrentLocationKnown()).collect().isEmpty());
    // Now commit this & update location of records inserted and validate no errors
    writeClient.commit(newCommitTime, writeStatusRdd);
    // Now tagLocation for these records, index should tag them correctly
    metaClient = HoodieTableMetaClient.reload(metaClient);
    hoodieTable = HoodieSparkTable.create(config, context, metaClient);
    javaRDD = tagLocation(index, writtenRecords, hoodieTable);
    Map<String, String> recordKeyToPartitionPathMap = new HashMap();
    List<HoodieRecord> hoodieRecords = writtenRecords.collect();
    hoodieRecords.forEach(entry -> recordKeyToPartitionPathMap.put(entry.getRecordKey(), entry.getPartitionPath()));
    String[] taggedFileIds = javaRDD.map(record -> record.getCurrentLocation().getFileId()).distinct().collect().stream().sorted().toArray(String[]::new);
    assertArrayEquals(taggedFileIds, fileIdsFromWriteStatuses);
    assertEquals(totalRecords, javaRDD.filter(record -> record.isCurrentLocationKnown()).collect().size());
    assertEquals(totalRecords, javaRDD.map(record -> record.getKey().getRecordKey()).distinct().count());
    assertEquals(totalRecords, javaRDD.filter(record -> (record.getCurrentLocation() != null && record.getCurrentLocation().getInstantTime().equals(newCommitTime))).distinct().count());
    javaRDD.foreach(entry -> assertEquals(recordKeyToPartitionPathMap.get(entry.getRecordKey()), entry.getPartitionPath(), "PartitionPath mismatch"));
    JavaRDD<HoodieKey> keysRdd = writtenRecords.map(entry -> entry.getKey());
