    HoodieWriteConfig hoodieWriteConfig = getHoodieWriteConfigAndInitializeTable(HoodieCompactionConfig.newBuilder().withMaxNumDeltaCommitsBeforeCompaction(// the 4th delta_commit triggers compaction
