@EnumSource(value = HoodieTableVersion.class, names = { "SIX", "NINE" })
void testMissingFileDoesNotFallRestore(HoodieTableVersion tableVersion) throws Exception {
    HoodieWriteConfig hoodieWriteConfig = getHoodieWriteConfigAndInitializeTable(HoodieCompactionConfig.newBuilder().withMaxNumDeltaCommitsBeforeCompaction(4).withInlineCompaction(false).compactionSmallFileSize(0).build(), tableVersion);
    try (SparkRDDWriteClient client = getHoodieWriteClient(hoodieWriteConfig)) {
        // establish base files
        String firstCommitTime = client.startCommit();
        int numRecords = 10;
        List<HoodieRecord> initialRecords = dataGen.generateInserts(firstCommitTime, numRecords);
        client.commit(firstCommitTime, client.insert(jsc.parallelize(initialRecords, 1), firstCommitTime));
        // add updates that go to log files
        String secondCommitTime = client.startCommit();
        List<HoodieRecord> updatedRecords = dataGen.generateUniqueUpdates(secondCommitTime, numRecords);
        client.commit(secondCommitTime, client.upsert(jsc.parallelize(updatedRecords, 1), secondCommitTime));
        client.savepoint(secondCommitTime, "user1", "Savepoint for commit that completed during compaction");
        // add a third delta commit with log and new base files
        String thirdCommitTime = client.startCommit();
        List<HoodieRecord> upsertRecords = Stream.concat(dataGen.generateUniqueUpdates(thirdCommitTime, numRecords).stream(), dataGen.generateInserts(thirdCommitTime, numRecords).stream()).collect(Collectors.toList());
        List<WriteStatus> writeStatuses = client.upsert(jsc.parallelize(upsertRecords, 1), thirdCommitTime).collect();
        client.commit(thirdCommitTime, jsc.parallelize(writeStatuses, 1));
        // delete one base file and one log file to validate both cases are handled gracefully
        boolean deletedLogFile = false;
        boolean deletedBaseFile = false;
        for (WriteStatus writeStatus : writeStatuses) {
            StoragePath path = FSUtils.constructAbsolutePath(basePath, writeStatus.getStat().getPath());
            if (deletedLogFile && deletedBaseFile) {
                break;
            }
            if (FSUtils.isLogFile(path)) {
                deletedLogFile = true;
                storage.deleteFile(path);
            } else {
                deletedBaseFile = true;
                storage.deleteFile(path);
            }
        }
        client.restoreToSavepoint(secondCommitTime);
        validateFilesMetadata(hoodieWriteConfig);
        assertEquals(Collections.singletonMap(secondCommitTime, numRecords), getRecordCountPerCommit());
    }
}

@Test
public void testAndValidateClusteringOutputFiles() throws IOException {
    String partitionPath = "2015/03/16";
    Properties properties = new Properties();
    properties.setProperty("hoodie.parquet.small.file.limit", "-1");
    HoodieWriteConfig.Builder cfgBuilder = new HoodieWriteConfig.Builder().withPath(basePath).withSchema(TRIP_NESTED_EXAMPLE_SCHEMA).withEmbeddedTimelineServerEnabled(false).withClusteringConfig(HoodieClusteringConfig.newBuilder().withInlineClustering(true).withAsyncClustering(false).withInlineClusteringNumCommits(2).withClusteringExecutionStrategyClass(SparkBinaryCopyClusteringExecutionStrategy.class.getName()).build()).withProps(properties);
    SparkRDDWriteClient client = getHoodieWriteClient(cfgBuilder.build());
    String newCommitTime1 = client.startCommit("commit");
    HoodieTestDataGenerator dataGen = new HoodieTestDataGenerator(HoodieTestDataGenerator.TRIP_NESTED_EXAMPLE_SCHEMA, 0xDEED, new String[] { partitionPath }, new HashMap<>());
    List<HoodieRecord> allRecord = new ArrayList<>();
    List<HoodieRecord> hoodieRecords1 = dataGen.generateInsertsNestedExample(newCommitTime1, 30);
    allRecord.addAll(hoodieRecords1);
    JavaRDD<HoodieRecord> insertRecordsRDD1 = jsc.parallelize(hoodieRecords1, 1);
    JavaRDD<WriteStatus> statuses1 = client.insert(insertRecordsRDD1, newCommitTime1);
    client.commit(newCommitTime1, statuses1);
    List<WriteStatus> statusList1 = statuses1.collect();
    // Trigger clustering
    String newCommitTime2 = client.startCommit("commit");
    List<HoodieRecord> hoodieRecords2 = dataGen.generateInsertsNestedExample(newCommitTime2, 30);
    allRecord.addAll(hoodieRecords2);
    JavaRDD<HoodieRecord> insertRecordsRDD2 = jsc.parallelize(hoodieRecords2, 1);
    JavaRDD<WriteStatus> statuses2 = client.insert(insertRecordsRDD2, newCommitTime2);
    client.commit(newCommitTime2, statuses2);
    List<WriteStatus> statusList2 = statuses2.collect();
    metaClient = HoodieTableMetaClient.reload(metaClient);
    HoodieInstant replaceCommitInstant = metaClient.getActiveTimeline().getCompletedReplaceTimeline().firstInstant().get();
    HoodieReplaceCommitMetadata replaceCommitMetadata = metaClient.getActiveTimeline().readReplaceCommitMetadata(replaceCommitInstant);
    List<String> filesFromReplaceCommit = new ArrayList<>();
    replaceCommitMetadata.getPartitionToWriteStats().forEach((k, v) -> v.forEach(entry -> filesFromReplaceCommit.add(entry.getPath())));
    // find all parquet files created as part of clustering. Verify it matces w/ whats found in replace commit metadata.
    FileStatus[] fileStatuses = fs.listStatus(new Path(basePath + "/" + partitionPath));
    List<String> replacedFiles = new ArrayList<>();
    List<String> clusteredFiles = new ArrayList<>();
    String clusteredFileName = "";
    for (FileStatus status : fileStatuses) {
        if (status.getPath().getName().contains(replaceCommitInstant.requestedTime())) {
            clusteredFiles.add(partitionPath + "/" + status.getPath().getName());
            clusteredFileName = status.getPath().getName();
        } else if (!status.getPath().getName().startsWith(".")) {
            replacedFiles.add(partitionPath + "/" + status.getPath().getName());
        }
    }
    assertEquals(clusteredFiles, filesFromReplaceCommit);
    // clusteredFiles check
    Set<String> commitTimeSet = new HashSet();
    commitTimeSet.add(newCommitTime1);
    commitTimeSet.add(newCommitTime2);
    checkFileFooter(clusteredFiles, allRecord, commitTimeSet, clusteredFileName);
}

@Test
public void testSupportBinaryStreamCopy() throws IOException {
    HoodieWriteConfig writeConfig = new HoodieWriteConfig.Builder().withPath(basePath).withSchema(TRIP_EXAMPLE_SCHEMA).withEmbeddedTimelineServerEnabled(false).build();
    HoodieSparkEngineContext engineContext = new HoodieSparkEngineContext(jsc);
    HoodieTable table = HoodieSparkTable.create(writeConfig, engineContext, metaClient);
    SparkBinaryCopyClusteringExecutionStrategy strategy = new SparkBinaryCopyClusteringExecutionStrategy(table, engineContext, writeConfig);
    MessageType legacySchema = new AvroSchemaConverter().convert(AVRO_SCHEMA);
    Configuration conf = new Configuration();
    conf.set("parquet.avro.write-old-list-structure", "false");
    MessageType standardSchema = new AvroSchemaConverter(conf).convert(AVRO_SCHEMA);
    BloomFilter simpleBloomFilter = BloomFilterFactory.createBloomFilter(1000, 0.0001, 10000, SIMPLE.name());
    BloomFilter dynmicBloomFilter = BloomFilterFactory.createBloomFilter(1000, 0.0001, 10000, DYNAMIC_V0.name());
    String file1 = makeTestFile("file-1.parquet", AVRO_SCHEMA, legacySchema, simpleBloomFilter);
    String file2 = makeTestFile("file-2.parquet", AVRO_SCHEMA, legacySchema, dynmicBloomFilter);
    String file3 = makeTestFile("file-3.parquet", AVRO_SCHEMA, standardSchema, dynmicBloomFilter);
    String file4 = makeTestFile("file-4.parquet", AVRO_SCHEMA, standardSchema, dynmicBloomFilter);
    // input file contains multiple bloom filter code type, should return false
    List<ClusteringGroupInfo> groups = makeClusteringGroup(file1, file2);
    Assertions.assertFalse(strategy.supportBinaryStreamCopy(groups, new HashMap<>()));
    // input file contains legacy schema, should return false
    groups = makeClusteringGroup(file2, file3);
    Assertions.assertFalse(strategy.supportBinaryStreamCopy(groups, new HashMap<>()));
    // otherwise should return true
    groups = makeClusteringGroup(file3, file4);
    Assertions.assertTrue(strategy.supportBinaryStreamCopy(groups, new HashMap<>()));
    metaClient = HoodieTestUtils.init(basePath, HoodieTableType.MERGE_ON_READ);
    table = HoodieSparkTable.create(writeConfig, engineContext, metaClient);
    strategy = new SparkBinaryCopyClusteringExecutionStrategy(table, engineContext, writeConfig);
    Assertions.assertFalse(strategy.supportBinaryStreamCopy(groups, new HashMap<>()));
}

