/**
 * Issue some corrupted or wrong schematized InternalRow after few valid InternalRows so that global error is thrown. write batch 1 of valid records write batch 2 of invalid records Global Error
 * should be thrown.
 */
@Test
public void testGlobalFailure() throws Exception {
    // init config and table
    HoodieWriteConfig cfg = SparkDatasetTestUtils.getConfigBuilder(basePath, timelineServicePort).build();
    HoodieTable table = HoodieSparkTable.create(cfg, context, metaClient);
    String partitionPath = HoodieTestDataGenerator.DEFAULT_PARTITION_PATHS[0];
    // init some args
    String fileId = UUID.randomUUID().toString();
    String instantTime = "000";
    HoodieRowCreateHandle handle = new HoodieRowCreateHandle(table, cfg, partitionPath, fileId, instantTime, RANDOM.nextInt(100000), RANDOM.nextLong(), RANDOM.nextLong(), SparkDatasetTestUtils.STRUCT_TYPE);
    int size = 10 + RANDOM.nextInt(1000);
    int totalFailures = 5;
    // Generate first batch of valid rows
    Dataset<Row> inputRows = SparkDatasetTestUtils.getRandomRows(sqlContext, size / 2, partitionPath, false);
    List<InternalRow> internalRows = SparkDatasetTestUtils.toInternalRows(inputRows, SparkDatasetTestUtils.ENCODER);
    // generate some failures rows
    for (int i = 0; i < totalFailures; i++) {
        internalRows.add(SparkDatasetTestUtils.getInternalRowWithError(partitionPath));
    }
    // generate 2nd batch of valid rows
    Dataset<Row> inputRows2 = SparkDatasetTestUtils.getRandomRows(sqlContext, size / 2, partitionPath, false);
    internalRows.addAll(SparkDatasetTestUtils.toInternalRows(inputRows2, SparkDatasetTestUtils.ENCODER));
    // issue writes
    try {
        for (InternalRow internalRow : internalRows) {
            handle.write(internalRow);
        }
        fail("Should have failed");
    } catch (Throwable e) {
        // expected
    }
    // close the create handle
    WriteStatus writeStatus = handle.close();
    List<String> fileNames = new ArrayList<>();
    fileNames.add(handle.getFileName());
    // verify write status
    assertNotNull(writeStatus.getGlobalError());
    String expectedError = getJavaVersion() == 11 || getJavaVersion() == 17 ? "class java.lang.String cannot be cast to class org.apache.spark.unsafe.types.UTF8String" : "java.lang.String cannot be cast to org.apache.spark.unsafe.types.UTF8String";
    assertTrue(writeStatus.getGlobalError() instanceof ClassCastException);
    assertTrue(writeStatus.getGlobalError().getMessage().contains(expectedError), "Expected error to contain: " + expectedError + ", the actual error message: " + writeStatus.getGlobalError());
    assertEquals(writeStatus.getFileId(), fileId);
    assertEquals(writeStatus.getPartitionPath(), partitionPath);
    // verify rows
    Dataset<Row> result = sqlContext.read().parquet(basePath + "/" + partitionPath);
    // passing only first batch of inputRows since after first batch global error would have been thrown
    assertRows(inputRows, result, instantTime, fileNames, true);
}

@Test
public void testAppendHandleRLIAndSIStats() throws Exception {
    // init config and table
    HoodieWriteConfig config = getConfigBuilder(basePath).withFileSystemViewConfig(FileSystemViewStorageConfig.newBuilder().withRemoteServerPort(timelineServicePort).build()).withMetadataConfig(HoodieMetadataConfig.newBuilder().enable(true).withEnableRecordIndex(true).withStreamingWriteEnabled(true).withSecondaryIndexEnabled(true).withSecondaryIndexName("sec-rider").withSecondaryIndexForColumn("rider").build()).build();
    config.setSchema(TRIP_EXAMPLE_SCHEMA);
    HoodieTable table = HoodieSparkTable.create(config, context, metaClient);
    // one round per partition
    String partitionPath = HoodieTestDataGenerator.DEFAULT_PARTITION_PATHS[0];
    // init some args
    HoodieTestDataGenerator dataGenerator = new HoodieTestDataGenerator(new String[] { partitionPath });
    SparkRDDWriteClient client = getHoodieWriteClient(config);
    String instantTime = writeClient.startCommit();
    List<HoodieRecord> records1 = dataGenerator.generateInserts(instantTime, 100);
    JavaRDD<HoodieRecord> writeRecords = jsc.parallelize(records1, 1);
    JavaRDD<WriteStatus> statuses = client.upsert(writeRecords, instantTime);
    client.commit(instantTime, statuses, Option.empty(), COMMIT_ACTION, Collections.emptyMap(), Option.empty());
    metaClient = HoodieTableMetaClient.reload(metaClient);
    table = (HoodieSparkCopyOnWriteTable) HoodieSparkCopyOnWriteTable.create(config, context, metaClient);
    HoodieFileGroup fileGroup = table.getFileSystemView().getAllFileGroups(partitionPath).collect(Collectors.toList()).get(0);
    String fileId = fileGroup.getFileGroupId().getFileId();
    // generate update and delete records
    instantTime = InProcessTimeGenerator.createNewInstantTime();
    int numUpdates = 20;
    List<HoodieRecord> records = dataGenerator.generateUniqueUpdates(instantTime, numUpdates);
    int numDeletes = generateDeleteRecords(records, dataGenerator, instantTime);
    assertTrue(numDeletes > 0);
    metaClient = HoodieTableMetaClient.reload(metaClient);
    table = HoodieSparkTable.create(config, context, metaClient);
    HoodieAppendHandle handle = new HoodieAppendHandle(config, instantTime, table, partitionPath, fileId, records.iterator(), new LocalTaskContextSupplier());
    Map<String, HoodieRecord> recordMap = new HashMap<>();
    for (int i = 0; i < records.size(); i++) {
        recordMap.put(String.valueOf(i), records.get(i));
    }
    // write the update records
    handle.write(recordMap);
    WriteStatus writeStatus = handle.writeStatus;
    handle.close();
    assertEquals(records.size(), writeStatus.getTotalRecords());
    assertEquals(numDeletes, writeStatus.getStat().getNumDeletes());
    assertEquals(0, writeStatus.getTotalErrorRecords());
    // validate write status has all record delegates
    assertEquals(records.size(), writeStatus.getIndexStats().getWrittenRecordDelegates().size());
    int numDeletedRecordDelegates = 0;
    for (HoodieRecordDelegate recordDelegate : writeStatus.getIndexStats().getWrittenRecordDelegates()) {
        if (!recordDelegate.getNewLocation().isPresent()) {
            numDeletedRecordDelegates++;
        } else {
            assertTrue(recordDelegate.getNewLocation().isPresent());
            assertEquals(fileId, recordDelegate.getNewLocation().get().getFileId());
            assertEquals(instantTime, recordDelegate.getNewLocation().get().getInstantTime());
        }
    }
    assertEquals(numDeletes, numDeletedRecordDelegates);
    // validate SI stats
    assertEquals(1, writeStatus.getIndexStats().getSecondaryIndexStats().size());
    // secondary index records size is same twice the number of updates and number of deletes
    // Two records for every update - delete old record and insert new record
    assertEquals(2 * numUpdates + numDeletes, writeStatus.getIndexStats().getSecondaryIndexStats().values().stream().findFirst().get().size());
    validateSecondaryIndexStatsContent(writeStatus, numUpdates, numDeletes);
}

