            // After rollback, there should be no base file with the failed commit time
            List<String> remainingFiles = allFiles.stream().filter(file -> file.getPath().getName().contains("_" + commitTime2)).map(fileStatus -> fileStatus.getPath().toString()).collect(Collectors.toList());
            assertEquals(0, remainingFiles.size(), "These files should have been rolled-back " + "when rolling back commit " + commitTime2 + " but are still remaining. Files: " + remainingFiles);
            metaClient = HoodieTableMetaClient.reload(metaClient);
