@Test
void testRestoreWithCleanedUpCommits() throws Exception {
    boolean populateMetaFields = true;
    HoodieWriteConfig.Builder cfgBuilder = getConfigBuilder(false).// Timeline-server-based markers are not used for multi-rollback tests
    withMarkersType(MarkerType.DIRECT.name());
