        schemaMap.put(type, createRecord("rec", createPrimitiveField("simpleField", type), createArrayField("arrayField", type), createMapField("mapField", type), createNestedField("nestedField", type)));
    }
    for (int i = 0; i < promotionTypes.length; i++) {
