        Schema expected = createRecord("missingComplexField", createPrimitiveField("field1", Schema.Type.INT), createPrimitiveField("field2", Schema.Type.INT), createNullableArrayField("field3", createRecord("nestedRecord", createPrimitiveField("nestedField1", Schema.Type.INT), createPrimitiveField("nestedField2", Schema.Type.INT), createPrimitiveField("nestedField3", Schema.Type.INT))), createPrimitiveField("field4", Schema.Type.INT));
        assertEquals(expected, actual);
        assertTrue(allowDroppedColumns);
    } catch (MissingSchemaFieldException e) {
        assertFalse(allowDroppedColumns);
        assertTrue(e.getMessage().contains("missingComplexField.field3"));
    }
    //partial missing field
    end = createRecord("missingComplexField", createPrimitiveField("field1", Schema.Type.INT), createArrayField("field3", createRecord("nestedRecord", createPrimitiveField("nestedField2", Schema.Type.INT), createPrimitiveField("nestedField3", Schema.Type.INT))), createPrimitiveField("field4", Schema.Type.INT));
    try {
        Schema actual = deduceWriterSchema(end, start, allowDroppedColumns);
        Schema expected = createRecord("missingComplexField", createPrimitiveField("field1", Schema.Type.INT), createNullablePrimitiveField("field2", Schema.Type.INT), createArrayField("field3", createRecord("nestedRecord", createNullablePrimitiveField("nestedField1", Schema.Type.INT), createPrimitiveField("nestedField2", Schema.Type.INT), createPrimitiveField("nestedField3", Schema.Type.INT))), createPrimitiveField("field4", Schema.Type.INT));
        assertEquals(expected, actual);
        assertTrue(allowDroppedColumns);
    } catch (MissingSchemaFieldException e) {
        assertFalse(allowDroppedColumns);
        assertTrue(e.getMessage().contains("missingComplexField.field3.element.nestedRecord.nestedField1"));
        assertTrue(e.getMessage().contains("missingComplexField.field2"));
    }
}

@Test
void testFieldReordering() {
    // field order changes and incoming schema is missing an existing field
    Schema start = createRecord("reorderFields", createPrimitiveField("field1", Schema.Type.INT), createPrimitiveField("field2", Schema.Type.INT), createPrimitiveField("field3", Schema.Type.INT));
    Schema end = createRecord("reorderFields", createPrimitiveField("field3", Schema.Type.INT), createPrimitiveField("field1", Schema.Type.INT));
    Schema expected = createRecord("reorderFields", createPrimitiveField("field1", Schema.Type.INT), createNullablePrimitiveField("field2", Schema.Type.INT), createPrimitiveField("field3", Schema.Type.INT));
    assertEquals(expected, deduceWriterSchema(end, start, true));
    // nested field ordering changes and new field is added
    start = createRecord("reorderNestedFields", createPrimitiveField("field1", Schema.Type.INT), createPrimitiveField("field2", Schema.Type.INT), createArrayField("field3", createRecord("reorderNestedFields.field3", createPrimitiveField("nestedField1", Schema.Type.INT), createPrimitiveField("nestedField2", Schema.Type.INT), createPrimitiveField("nestedField3", Schema.Type.INT))), createPrimitiveField("field4", Schema.Type.INT));
    end = createRecord("reorderNestedFields", createPrimitiveField("field1", Schema.Type.INT), createPrimitiveField("field2", Schema.Type.INT), createPrimitiveField("field5", Schema.Type.INT), createArrayField("field3", createRecord("reorderNestedFields.field3", createPrimitiveField("nestedField2", Schema.Type.INT), createPrimitiveField("nestedField1", Schema.Type.INT), createPrimitiveField("nestedField3", Schema.Type.INT), createPrimitiveField("nestedField4", Schema.Type.INT))), createPrimitiveField("field4", Schema.Type.INT));
    expected = createRecord("reorderNestedFields", createPrimitiveField("field1", Schema.Type.INT), createPrimitiveField("field2", Schema.Type.INT), createArrayField("field3", createRecord("reorderNestedFields.field3", createPrimitiveField("nestedField1", Schema.Type.INT), createPrimitiveField("nestedField2", Schema.Type.INT), createPrimitiveField("nestedField3", Schema.Type.INT), createNullablePrimitiveField("nestedField4", Schema.Type.INT))), createPrimitiveField("field4", Schema.Type.INT), createNullablePrimitiveField("field5", Schema.Type.INT));
    assertEquals(expected, deduceWriterSchema(end, start, true));
}

