void testGetPartitionEvents_droppedStoragePartitionNotPresentInMetastore(String syncMode, String enablePushDown) throws Exception {
    hiveSyncProps.setProperty(HIVE_SYNC_MODE.key(), syncMode);
    hiveSyncProps.setProperty(HIVE_SYNC_FILTER_PUSHDOWN_ENABLED.key(), enablePushDown);
    // Create a table with 1 partition
