    MessageType fileSchema = new MessageType("file_schema", Types.primitive(PrimitiveType.PrimitiveTypeName.INT32, OPTIONAL).named("col_a"), Types.primitive(PrimitiveType.PrimitiveTypeName.BINARY, OPTIONAL).as(LogicalTypeAnnotation.stringType()).named("col_b"), Types.primitive(PrimitiveType.PrimitiveTypeName.BOOLEAN, OPTIONAL).named("col_c"), Types.primitive(PrimitiveType.PrimitiveTypeName.DOUBLE, OPTIONAL).named("col_d"));
    // Requested Columns (subset and different order)
    List<HiveColumnHandle> requestedColumns = List.of(createDummyHandle("col_d", 1, HiveType.HIVE_DOUBLE, DOUBLE), createDummyHandle("col_a", 0, HiveType.HIVE_INT, INTEGER));
    // Perform remapping (case-insensitive)
    List<HiveColumnHandle> remapped = remapColumnIndicesToPhysical(fileSchema, requestedColumns, false);
    assertThat(remapped).hasSize(2);
    // First requested "col_d" -> physical index 3
    assertHandle(remapped.get(0), "col_d", 3, HiveType.HIVE_DOUBLE, DOUBLE);
    // Second requested "col_a" -> physical index 0
    assertHandle(remapped.get(1), "col_a", 0, HiveType.HIVE_INT, INTEGER);
}

