    new Thread(() -> {
        try {
            Thread.sleep(10000);
            LOG.info("Shutdown the table services");
            main.cancel();
        } catch (InterruptedException e) {
            LOG.warn("InterruptedException: ", e);
        }
    }).start();
    try {
