    Pair<Option<String>, Checkpoint> nextFilePathsAndCheckpoint = selector.getNextFilePathsAndMaxModificationTime(jsc, Option.empty(), 20);
    List<String> fileNames1stRead = Arrays.stream(nextFilePathsAndCheckpoint.getLeft().get().split(",")).map(p -> Paths.get(p).toFile().getName()).sorted().collect(Collectors.toList());
