@ParameterizedTest
@MethodSource("getArgumentsForHoodieIncrSource")
public void testHoodieIncrSource(HoodieTableType tableType, boolean useSourceProfile, HoodieTableVersion sourceTableVersion) throws IOException {
    this.tableType = tableType;
    Properties properties = getPropertiesForKeyGen(true);
    properties.setProperty(HoodieWriteConfig.WRITE_TABLE_VERSION.key(), Integer.toString(sourceTableVersion.versionCode()));
    metaClient = getHoodieMetaClient(storageConf(), basePath(), properties);
    HoodieWriteConfig writeConfig = getConfigBuilder(basePath(), metaClient).withWriteTableVersion(sourceTableVersion.versionCode()).withAutoUpgradeVersion(false).withArchivalConfig(HoodieArchivalConfig.newBuilder().archiveCommitsWith(4, 5).build()).withCleanConfig(HoodieCleanConfig.newBuilder().retainCommits(1).build()).withCompactionConfig(HoodieCompactionConfig.newBuilder().withInlineCompaction(tableType == MERGE_ON_READ).withMaxNumDeltaCommitsBeforeCompaction(3).build()).withMetadataConfig(HoodieMetadataConfig.newBuilder().enable(false).build()).build();
    if (useSourceProfile) {
        when(sourceProfile.get().getSourceProfile()).thenReturn(new TestSourceProfile(Long.MAX_VALUE, 4, 500));
    } else {
        when(sourceProfile.get().getSourceProfile()).thenReturn(null);
    }
    try (SparkRDDWriteClient writeClient = getHoodieWriteClient(writeConfig)) {
        // WriteResult is a Pair<HoodieInstant, Records>
        WriteResult insert1 = writeRecords(writeClient, tableType, INSERT, null, 98);
        WriteResult insert2 = writeRecords(writeClient, tableType, INSERT, null, 106);
        WriteResult insert3 = writeRecords(writeClient, tableType, INSERT, null, 114);
        WriteResult insert4 = writeRecords(writeClient, tableType, INSERT, null, 122);
        WriteResult insert5 = writeRecords(writeClient, tableType, INSERT, null, 130);
        // read everything upto latest
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.empty(), 570, insert5.getInstant(), sourceTableVersion);
        StreamerCheckpointV2 instant5CheckpointV2 = new StreamerCheckpointV2(insert5.getCompletionTime());
        StreamerCheckpointV1 instant5CheckpointV1 = new StreamerCheckpointV1(insert5.getInstantTime());
        boolean sourceTableVersion8OrAbove = sourceTableVersion.greaterThanOrEquals(HoodieTableVersion.EIGHT);
        readAndAssertCheckpointTranslation(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, HoodieTableVersion.EIGHT, Option.empty(), 570, sourceTableVersion8OrAbove ? instant5CheckpointV2 : instant5CheckpointV1);
        readAndAssertCheckpointTranslation(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, HoodieTableVersion.SIX, Option.empty(), 570, instant5CheckpointV1);
        // even if the start completion timestamp is archived (100), full table scan should kick in, but should filter for records having commit time > 100
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.of(insert1.getInstant()), 472, insert5.getInstant(), sourceTableVersion);
        readAndAssertCheckpointTranslation(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, HoodieTableVersion.EIGHT, Option.of(new StreamerCheckpointV1(insert1.getInstant().requestedTime())), 472, sourceTableVersion8OrAbove ? instant5CheckpointV2 : instant5CheckpointV1);
        readAndAssertCheckpointTranslation(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, HoodieTableVersion.SIX, Option.of(new StreamerCheckpointV2(insert1.getInstant().getCompletionTime())), 472, instant5CheckpointV1);
        readAndAssertCheckpointTranslation(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, HoodieTableVersion.SIX, Option.of(new StreamerCheckpointV1(insert1.getInstant().requestedTime())), 472, instant5CheckpointV1);
        // even if the read upto latest is set, if start completion timestamp is in active timeline, only incremental should kick in.
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.of(insert4.getInstant()), 130, insert5.getInstant(), sourceTableVersion);
        readAndAssertCheckpointTranslation(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, HoodieTableVersion.EIGHT, Option.of(new StreamerCheckpointV1(insert4.getInstant().requestedTime())), 130, sourceTableVersion8OrAbove ? instant5CheckpointV2 : instant5CheckpointV1);
        readAndAssertCheckpointTranslation(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, HoodieTableVersion.SIX, Option.of(new StreamerCheckpointV2(insert4.getInstant().getCompletionTime())), 130, instant5CheckpointV1);
        readAndAssertCheckpointTranslation(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, HoodieTableVersion.SIX, Option.of(new StreamerCheckpointV1(insert4.getInstant().requestedTime())), 130, instant5CheckpointV1);
        // read just the latest
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_LATEST, Option.empty(), 130, insert5.getInstant(), sourceTableVersion);
        readAndAssertCheckpointTranslation(IncrSourceHelper.MissingCheckpointStrategy.READ_LATEST, HoodieTableVersion.EIGHT, Option.empty(), 130, sourceTableVersion8OrAbove ? instant5CheckpointV2 : instant5CheckpointV1);
        readAndAssertCheckpointTranslation(IncrSourceHelper.MissingCheckpointStrategy.READ_LATEST, HoodieTableVersion.SIX, Option.empty(), 130, instant5CheckpointV1);
        // ensure checkpoint does not move
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_LATEST, Option.of(insert5.getInstant()), 0, insert5.getInstant(), sourceTableVersion);
        readAndAssertCheckpointTranslation(IncrSourceHelper.MissingCheckpointStrategy.READ_LATEST, HoodieTableVersion.EIGHT, Option.of(instant5CheckpointV1), 0, instant5CheckpointV1);
        readAndAssertCheckpointTranslation(IncrSourceHelper.MissingCheckpointStrategy.READ_LATEST, HoodieTableVersion.SIX, Option.of(instant5CheckpointV2), 0, instant5CheckpointV1);
        readAndAssertCheckpointTranslation(IncrSourceHelper.MissingCheckpointStrategy.READ_LATEST, HoodieTableVersion.SIX, Option.of(instant5CheckpointV1), 0, instant5CheckpointV1);
        WriteResult insert6 = writeRecords(writeClient, tableType, INSERT, null, 168);
        // insert new batch and ensure the checkpoint moves
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_LATEST, Option.of(insert5.getInstant()), 168, insert6.getInstant(), sourceTableVersion);
        StreamerCheckpointV2 instant6CheckpointV2 = new StreamerCheckpointV2(insert6.getCompletionTime());
        StreamerCheckpointV1 instant6CheckpointV1 = new StreamerCheckpointV1(insert6.getInstantTime());
        readAndAssertCheckpointTranslation(IncrSourceHelper.MissingCheckpointStrategy.READ_LATEST, HoodieTableVersion.EIGHT, Option.of(instant5CheckpointV1), 168, sourceTableVersion8OrAbove ? instant6CheckpointV2 : instant6CheckpointV1);
        readAndAssertCheckpointTranslation(IncrSourceHelper.MissingCheckpointStrategy.READ_LATEST, HoodieTableVersion.SIX, Option.of(instant5CheckpointV2), 168, instant6CheckpointV1);
        readAndAssertCheckpointTranslation(IncrSourceHelper.MissingCheckpointStrategy.READ_LATEST, HoodieTableVersion.SIX, Option.of(instant5CheckpointV1), 168, instant6CheckpointV1);
        if (useSourceProfile) {
            // TODO(yihua): fix this
            //verify(metrics, times(5)).updateStreamerSourceBytesToBeIngestedInSyncRound(Long.MAX_VALUE);
            //verify(metrics, times(5)).updateStreamerSourceParallelism(4);
        }
    }
}

@ParameterizedTest
@EnumSource(HoodieTableType.class)
public void testHoodieIncrSourceInflightCommitBeforeCompletedCommit(HoodieTableType tableType) throws IOException {
    this.tableType = tableType;
    metaClient = getHoodieMetaClient(storageConf(), basePath());
    HoodieWriteConfig writeConfig = getConfigBuilder(basePath(), metaClient).withArchivalConfig(HoodieArchivalConfig.newBuilder().archiveCommitsWith(4, 5).build()).withCleanConfig(HoodieCleanConfig.newBuilder().retainCommits(2).build()).withCompactionConfig(HoodieCompactionConfig.newBuilder().withInlineCompaction(false).withMaxNumDeltaCommitsBeforeCompaction(3).build()).withMetadataConfig(HoodieMetadataConfig.newBuilder().enable(false).build()).build();
    try (SparkRDDWriteClient writeClient = getHoodieWriteClient(writeConfig)) {
        List<WriteResult> inserts = new ArrayList<>();
        for (int i = 0; i < 6; i++) {
            inserts.add(writeRecords(writeClient, tableType, INSERT, null));
        }
        // Emulates a scenario where an inflight commit is before a completed commit
        // The checkpoint should not go past this commit
        HoodieActiveTimeline activeTimeline = metaClient.getActiveTimeline();
        HoodieInstant instant4 = activeTimeline.filter(instant -> instant.requestedTime().equals(inserts.get(4).getInstantTime())).firstInstant().get();
        HoodieCommitMetadata instant4CommitData = metaClient.reloadActiveTimeline().readCommitMetadata(instant4);
        activeTimeline.revertToInflight(instant4);
        metaClient.reloadActiveTimeline();
        // instant 0
        // instant 1
        // instant 2
        // instant 3
        // instant 4_inflight
        // instant 5
        // Reads everything up to latest
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.empty(), 500, inserts.get(5).getInstant());
        // Even if the start completion timestamp is archived, full table scan should kick in, but should filter for records having commit time > first instant
        // time
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.of(inserts.get(0).getInstant()), 400, inserts.get(5).getInstant());
        // Even if the read upto latest is set, if start completion timestamp is in active timeline, only incremental should kick in.
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.of(inserts.get(2).getInstant()), 200, inserts.get(5).getInstant());
        // Reads just the latest
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_LATEST, Option.empty(), 100, inserts.get(5).getInstant());
        // Ensures checkpoint does not move
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_LATEST, Option.of(inserts.get(5).getInstant()), 0, inserts.get(5).getInstant());
        activeTimeline.reload().saveAsComplete(INSTANT_GENERATOR.createNewInstant(HoodieInstant.State.INFLIGHT, instant4.getAction(), inserts.get(4).getInstantTime()), Option.of(instant4CommitData));
        instant4 = activeTimeline.reload().filter(instant -> instant.requestedTime().equals(inserts.get(4).getInstantTime())).firstInstant().get();
        // After the inflight commit completes, the checkpoint should move on after incremental pull
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_LATEST, Option.of(inserts.get(3).getInstant()), 200, instant4);
    }
}

@ParameterizedTest
@EnumSource(HoodieTableType.class)
public void testHoodieIncrSourceWithPendingTableServices(HoodieTableType tableType) throws IOException {
    metaClient = getHoodieMetaClient(storageConf(), basePath(), getPropertiesForKeyGen(true), tableType);
    HoodieWriteConfig writeConfig = getConfigBuilder(basePath(), metaClient).withArchivalConfig(HoodieArchivalConfig.newBuilder().archiveCommitsWith(10, 12).build()).withCleanConfig(HoodieCleanConfig.newBuilder().retainCommits(9).build()).withCompactionConfig(HoodieCompactionConfig.newBuilder().withScheduleInlineCompaction(tableType == MERGE_ON_READ).withMaxNumDeltaCommitsBeforeCompaction(1).build()).withMetadataConfig(HoodieMetadataConfig.newBuilder().enable(false).build()).build();
    try (SparkRDDWriteClient writeClient = getHoodieWriteClient(writeConfig)) {
        List<WriteResult> dataBatches = new ArrayList<>();
        // For COW:
        //   0: bulk_insert of 100 records
        //   1: bulk_insert of 100 records
        //   2: bulk_insert of 100 records
        //      schedule clustering
        //   3: bulk_insert of 100 records
        //   4: upsert of 100 records (updates only based on round 3)
        //   5: upsert of 100 records (updates only based on round 3)
        //   6: bulk_insert of 100 records
        // For MOR:
        //   0: bulk_insert of 100 records
        //   1: bulk_insert of 100 records
        //   2: bulk_insert of 100 records
        //   3: bulk_insert of 100 records
        //   4: upsert of 100 records (updates only based on round 3)
        //      schedule compaction
        //   5: upsert of 100 records (updates only based on round 3)
        //      schedule clustering
        //   6: bulk_insert of 100 records
        for (int i = 0; i < 6; i++) {
            WriteOperationType opType = i < 4 ? BULK_INSERT : UPSERT;
            List<HoodieRecord> recordsForUpdate = i < 4 ? null : dataBatches.get(3).getRecords();
            dataBatches.add(writeRecords(writeClient, tableType, opType, recordsForUpdate));
            if (tableType == COPY_ON_WRITE) {
                if (i == 2) {
                    writeClient.scheduleClustering(Option.empty());
                }
            } else if (tableType == MERGE_ON_READ) {
                if (i == 4) {
                    writeClient.scheduleCompaction(Option.empty());
                }
                if (i == 5) {
                    writeClient.scheduleClustering(Option.empty());
                }
            }
        }
        dataBatches.add(writeRecords(writeClient, tableType, BULK_INSERT, null));
        String latestCommitTimestamp = dataBatches.get(dataBatches.size() - 1).getInstantTime();
        // Pending clustering exists
        Option<HoodieInstant> clusteringInstant = metaClient.getActiveTimeline().filterPendingClusteringTimeline().filter(instant -> ClusteringUtils.getClusteringPlan(metaClient, instant).isPresent()).firstInstant();
        assertTrue(clusteringInstant.isPresent());
        assertTrue(clusteringInstant.get().requestedTime().compareTo(latestCommitTimestamp) < 0);
        if (tableType == MERGE_ON_READ) {
            // Pending compaction exists
            Option<HoodieInstant> compactionInstant = metaClient.getActiveTimeline().filterPendingCompactionTimeline().firstInstant();
            assertTrue(compactionInstant.isPresent());
            assertTrue(compactionInstant.get().requestedTime().compareTo(latestCommitTimestamp) < 0);
        }
        // test SnapshotLoadQuerySplitter to split snapshot query .
        // Reads only first commit
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.empty(), 100, dataBatches.get(0).getInstant(), Option.of(TestSnapshotQuerySplitterImpl.class.getName()), new TypedProperties(), HoodieTableVersion.EIGHT);
        // The pending tables services should not block the incremental pulls
        // Reads everything up to latest
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.empty(), 500, dataBatches.get(6).getInstant());
        // Even if the read upto latest is set, if start completion timestamp is in active timeline, only incremental should kick in.
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.of(dataBatches.get(2).getInstant()), 200, dataBatches.get(6).getInstant());
        // Reads just the latest
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_LATEST, Option.empty(), 100, dataBatches.get(6).getInstant());
        // Ensures checkpoint does not move
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_LATEST, Option.of(dataBatches.get(6).getInstant()), 0, dataBatches.get(6).getInstant());
    }
}

