          Arguments.of("100", 101, "300", 200, 2),
          Arguments.of("200", 101, "300", 100, 1),
          Arguments.of("300", 101, "300", 0, 0)
      */
        TypedProperties extraProps = new TypedProperties();
        extraProps.setProperty(TestSnapshotQuerySplitterImpl.MAX_ROWS_PER_BATCH, String.valueOf(1));
        readAndAssert(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.empty(), 100, new StreamerCheckpointV2(inserts.get(0).getCompletionTime()), Option.of(TestSnapshotQuerySplitterImpl.class.getName()), extraProps, Option.ofNullable(1));
        extraProps.setProperty(TestSnapshotQuerySplitterImpl.MAX_ROWS_PER_BATCH, String.valueOf(101));
        readAndAssert(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.empty(), 200, new StreamerCheckpointV2(inserts.get(1).getCompletionTime()), Option.of(TestSnapshotQuerySplitterImpl.class.getName()), extraProps, Option.ofNullable(3));
        extraProps.setProperty(TestSnapshotQuerySplitterImpl.MAX_ROWS_PER_BATCH, String.valueOf(10001));
        readAndAssert(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.empty(), 300, new StreamerCheckpointV2(inserts.get(2).getCompletionTime()), Option.of(TestSnapshotQuerySplitterImpl.class.getName()), extraProps, Option.ofNullable(3));
        // even if TestSnapshotQuerySplitterImpl is configured, it shouldn't be used if it's not a snapshot query
        // Conditions to determine if HoodieIncrSource should run a snapshot query
        //   1. checkpoint exists or checkpoint is missing but the MissingCheckpointStrategy is set to READ_LATEST
        //   2. start completion time/checkpoint is archived
        // The tests below do not meet either of one of the condition, so they should run normal incremental queries
        extraProps.setProperty(TestSnapshotQuerySplitterImpl.MAX_ROWS_PER_BATCH, String.valueOf(101));
        readAndAssert(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.of(new StreamerCheckpointV2(inserts.get(0).getCompletionTime())), 200, new StreamerCheckpointV2(inserts.get(2).getCompletionTime()), Option.of(TestSnapshotQuerySplitterImpl.class.getName()), extraProps, Option.ofNullable(2));
        extraProps.setProperty(TestSnapshotQuerySplitterImpl.MAX_ROWS_PER_BATCH, String.valueOf(101));
        readAndAssert(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.of(new StreamerCheckpointV2(inserts.get(1).getCompletionTime())), 100, new StreamerCheckpointV2(inserts.get(2).getCompletionTime()), Option.of(TestSnapshotQuerySplitterImpl.class.getName()), extraProps, Option.ofNullable(1));
        extraProps.setProperty(TestSnapshotQuerySplitterImpl.MAX_ROWS_PER_BATCH, String.valueOf(101));
        readAndAssert(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.of(new StreamerCheckpointV2(inserts.get(2).getCompletionTime())), 0, new StreamerCheckpointV2(inserts.get(2).getCompletionTime()), Option.of(TestSnapshotQuerySplitterImpl.class.getName()), extraProps, Option.ofNullable(0));
    }
}

@Test
void testFileIndexLogicalPlanSize() throws Exception {
    this.tableType = MERGE_ON_READ;
    metaClient = getHoodieMetaClient(storageConf(), basePath());
    HoodieWriteConfig writeConfig = getConfigBuilder(basePath(), metaClient).withArchivalConfig(HoodieArchivalConfig.newBuilder().archiveCommitsWith(10, 12).build()).withCleanConfig(HoodieCleanConfig.newBuilder().retainCommits(9).build()).withCompactionConfig(HoodieCompactionConfig.newBuilder().withScheduleInlineCompaction(true).withMaxNumDeltaCommitsBeforeCompaction(1).build()).withMetadataConfig(HoodieMetadataConfig.newBuilder().enable(true).build()).build();
    // Write a hudi table with 20 file slices.
    int numFileSlices = 20;
    try (SparkRDDWriteClient writeClient = getHoodieWriteClient(writeConfig)) {
        for (int i = 0; i < numFileSlices; i++) {
            writeRecordsForPartition(writeClient, tableType, BULK_INSERT, "100" + i, String.format("2016/03/%s", i));
        }
    }
    // Arguments are in order -> fileSlicesCachedInMemory, spillableMemory, useSpillableMap
    getArgsForLogicalPlanSizeValidation().forEach(argumentsStream -> {
        Object[] arguments = argumentsStream.get();
        int fileSlicesCachedInMemory = (int) arguments[0];
        long spillableMemoryBytes = (long) arguments[1];
        boolean useSpillableMap = (boolean) arguments[2];
        Dataset<Row> dataset = spark().read().option(HoodieCommonConfig.HOODIE_FILE_INDEX_USE_SPILLABLE_MAP.key(), useSpillableMap).option(HoodieCommonConfig.HOODIE_FILE_INDEX_SPILLABLE_MEMORY.key(), spillableMemoryBytes).format("hudi").load(basePath());
        dataset.persist(StorageLevel.MEMORY_AND_DISK_SER());
        dataset.count();
        List<LogicalPlan> logicalPlanChildren = JavaConverters.seqAsJavaList(dataset.queryExecution().commandExecuted().children().toSeq());
        BaseHoodieTableFileIndex hoodieTableFileIndex = (BaseHoodieTableFileIndex) (((HadoopFsRelation) ((LogicalRelation) logicalPlanChildren.get(0)).relation()).location());
        if (useSpillableMap) {
            ExternalSpillableMap<BaseHoodieTableFileIndex.PartitionPath, List<FileSlice>> cachedAllInputFileSlices = getSpillableMap(hoodieTableFileIndex);
            Assertions.assertEquals(fileSlicesCachedInMemory, cachedAllInputFileSlices.getInMemoryMapNumEntries());
            Assertions.assertEquals(numFileSlices - fileSlicesCachedInMemory, cachedAllInputFileSlices.getDiskBasedMapNumEntries());
            Assertions.assertTrue(cachedAllInputFileSlices.getCurrentInMemoryMapSize() < 2 * spillableMemoryBytes, "In-memory map size is greater than expected " + cachedAllInputFileSlices.getCurrentInMemoryMapSize());
        } else {
            HashMap<BaseHoodieTableFileIndex.PartitionPath, List<FileSlice>> cachedAllInputFileSlices = getHashMap(hoodieTableFileIndex);
            Assertions.assertEquals(fileSlicesCachedInMemory, cachedAllInputFileSlices.size());
            Assertions.assertTrue(ObjectSizeCalculator.getObjectSize(cachedAllInputFileSlices) > spillableMemoryBytes);
        }
        dataset.unpersist();
    });
}

@ParameterizedTest
@EnumSource(HoodieTableType.class)
public void testIncrSourceQueryWithIntersectingCommits(HoodieTableType tableType) throws IOException {
    this.tableType = tableType;
    metaClient = getHoodieMetaClient(storageConf(), basePath());
    HoodieWriteConfig writeConfig = getConfigBuilder(basePath(), metaClient).withArchivalConfig(HoodieArchivalConfig.newBuilder().archiveCommitsWith(4, 5).build()).withCleanConfig(HoodieCleanConfig.newBuilder().retainCommits(2).build()).withCompactionConfig(HoodieCompactionConfig.newBuilder().withInlineCompaction(false).withMaxNumDeltaCommitsBeforeCompaction(3).build()).withMetadataConfig(HoodieMetadataConfig.newBuilder().enable(false).build()).build();
    try (SparkRDDWriteClient writeClient = getHoodieWriteClient(writeConfig)) {
        List<WriteResult> inserts = new ArrayList<>();
        // Create commits following the pattern: start1, start2, end2, [query time], end1
        // 0: start1 commit (will be made inflight)
        // 1: start2 commit
        // 2: end2
        // 3: [query time]
        // 4: end1
        for (int i = 0; i < 2; i++) {
            inserts.add(writeRecords(writeClient, tableType, INSERT, null, 100));
        }
        // Emulates a scenario where an inflight commit intersects with query time
        // We'll make the first commit inflight, query time will be between completion time of 2nd commit
        // and the later completion time of 1st commit.
        HoodieActiveTimeline activeTimeline = metaClient.getActiveTimeline();
        HoodieInstant instant0 = activeTimeline.filter(instant -> instant.requestedTime().equals(inserts.get(0).getInstantTime())).firstInstant().get();
        HoodieCommitMetadata instant0CommitData = metaClient.reloadActiveTimeline().readCommitMetadata(instant0);
        activeTimeline.revertToInflight(instant0);
        metaClient.reloadActiveTimeline();
        // Complete the inflight commit
        activeTimeline.reload().saveAsComplete(INSTANT_GENERATOR.createNewInstant(HoodieInstant.State.INFLIGHT, instant0.getAction(), inserts.get(0).getInstantTime()), Option.of(instant0CommitData));
        instant0 = activeTimeline.reload().filter(instant -> instant.requestedTime().equals(inserts.get(0).getInstantTime())).firstInstant().get();
        assertNotNull(instant0.getCompletionTime());
        // When querying from instant1 (end2) with READ_UPTO_LATEST_COMMIT,
        // the query should only read up to the completion time of 1st commit (end1)
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.of(inserts.get(1).getInstant()), // Only records from instant 1 (which is inflight but was committed before becoming inflight)
        100, instant0);
    }
}

@Test
void testIncrSourceSameResultWithPendingAndCompletedCompaction() throws IOException {
    metaClient = getHoodieMetaClient(storageConf(), basePath(), getPropertiesForKeyGen(true), MERGE_ON_READ);
    HoodieWriteConfig writeConfig = getConfigBuilder(basePath(), metaClient).withArchivalConfig(HoodieArchivalConfig.newBuilder().archiveCommitsWith(10, 12).build()).withCleanConfig(HoodieCleanConfig.newBuilder().retainCommits(9).build()).withCompactionConfig(HoodieCompactionConfig.newBuilder().withScheduleInlineCompaction(true).withMaxNumDeltaCommitsBeforeCompaction(1).build()).withMetadataConfig(HoodieMetadataConfig.newBuilder().enable(false).build()).build();
    try (SparkRDDWriteClient writeClient = getHoodieWriteClient(writeConfig)) {
        List<WriteResult> dataBatches = new ArrayList<>();
        //   0: bulk_insert of 100 records
        //   1: bulk_insert of 100 records
        //   2: bulk_insert of 100 records
        //   3: bulk_insert of 100 records
        //   4: upsert of 100 records (updates only based on round 3)
        //      schedule compaction
        //   5: upsert of 100 records (updates only based on round 3)
        //   6: bulk_insert of 100 records
        for (int i = 0; i < 6; i++) {
            WriteOperationType opType = i < 4 ? BULK_INSERT : UPSERT;
            List<HoodieRecord> recordsForUpdate = i < 4 ? null : dataBatches.get(3).getRecords();
            dataBatches.add(writeRecords(writeClient, MERGE_ON_READ, opType, recordsForUpdate));
            if (i == 4) {
                writeClient.scheduleCompaction(Option.empty());
            }
        }
        dataBatches.add(writeRecords(writeClient, MERGE_ON_READ, BULK_INSERT, null));
        String latestCommitTimestamp = dataBatches.get(dataBatches.size() - 1).getInstantTime();
        // Pending compaction exists
        Option<HoodieInstant> compactionInstant = metaClient.getActiveTimeline().filterPendingCompactionTimeline().firstInstant();
        assertTrue(compactionInstant.isPresent());
        assertTrue(compactionInstant.get().requestedTime().compareTo(latestCommitTimestamp) < 0);
        // The pending tables services should not block the incremental pulls
        // Reads everything up to latest
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.empty(), 500, dataBatches.get(6).getInstant());
        // set start completion timestamp in active timeline
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.of(dataBatches.get(2).getInstant()), 200, dataBatches.get(6).getInstant());
        // complete the compaction
        String compactionRequestTime = compactionInstant.get().requestedTime();
        writeClient.compact(compactionRequestTime, true);
        compactionInstant = metaClient.reloadActiveTimeline().filterCompletedAndCompactionInstants().filter(instant -> instant.requestedTime().equals(compactionRequestTime)).firstInstant();
        assertTrue(compactionInstant.isPresent());
        assertTrue(compactionInstant.get().getCompletionTime().compareTo(latestCommitTimestamp) > 0);
        // Reads everything up to latest with completed compaction
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.empty(), 500, compactionInstant.get());
        // set start completion timestamp in active timeline
        readAndAssertWithLatestTableVersion(IncrSourceHelper.MissingCheckpointStrategy.READ_UPTO_LATEST_COMMIT, Option.of(dataBatches.get(2).getInstant()), 200, compactionInstant.get());
    }
}

