        Exception exception = assertThrows(HoodieException.class, () -> {
            runSource(Option.of(batch.getCheckpointForNextBatch()), -1);
        });
        assertTrue(exception.getMessage().contains("Failed to checkpoint"));
    } catch (Exception e) {
        fail(e.getMessage());
    }
}

