    assertEquals(20, fetch2.getBatch().get().filter("decfield < 10000.0").filter("decfield > 1000.0").filter("lowprecision < 100.0").filter("lowprecision > 10.0").filter("highprecision < 100000000000000000000.0").filter("highprecision > 10000000000000000000.0").count());
}

