@ParameterizedTest
@MethodSource("testCreateHoodieRecords")
void testCreateValidHoodieRecords(HoodieRecordType recordType, boolean enableErrorTableWriter, String recordKeyField) {
    Schema schema = new Schema.Parser().parse(SCHEMA_STRING);
    JavaRDD<GenericRecord> recordRdd = jsc.parallelize(Collections.singletonList(1)).map(i -> {
        GenericRecord genericRecord = new GenericData.Record(schema);
        genericRecord.put(0, i * 1000L);
        genericRecord.put(1, "key" + i);
        genericRecord.put(2, "path" + i);
        genericRecord.put(3, "rider1");
        genericRecord.put(4, "driver1");
        return genericRecord;
    });
    HoodieStreamer.Config cfg = new HoodieStreamer.Config();
    cfg.payloadClassName = DefaultHoodieRecordPayload.class.getName();
    TypedProperties props = new TypedProperties();
    props.put(KeyGeneratorOptions.PARTITIONPATH_FIELD_NAME.key(), "partition_path");
    props.put(KeyGeneratorOptions.RECORDKEY_FIELD_NAME.key(), recordKeyField);
    Option<BaseErrorTableWriter> errorTableWriter = enableErrorTableWriter ? Option.of(Mockito.mock(BaseErrorTableWriter.class)) : Option.empty();
    ArgumentCaptor<JavaRDD<?>> errorEventCaptor = ArgumentCaptor.forClass(JavaRDD.class);
    if (errorTableWriter.isPresent()) {
        doNothing().when(errorTableWriter.get()).addErrorEvents(errorEventCaptor.capture());
    }
    Option<JavaRDD<HoodieRecord>> recordOpt = HoodieStreamerUtils.createHoodieRecords(cfg, props, Option.of(recordRdd), new SimpleSchemaProvider(jsc, schema, props), recordType, false, "000", errorTableWriter);
    if (errorTableWriter.isPresent()) {
        assertEquals(0, errorEventCaptor.getValue().collect().size());
    }
    assertTrue(recordOpt.isPresent());
    List<HoodieRecord> records = recordOpt.get().collect();
    assertEquals(1, records.size());
    Object[] columnValues = records.get(0).getColumnValues(schema, new String[] { "timestamp", "_row_key", "partition_path", "rider", "driver" }, false);
    Object[] expectedValues = recordType == HoodieRecordType.SPARK ? new Object[] { 1000L, UTF8String.fromString("key1"), UTF8String.fromString("path1"), UTF8String.fromString("rider1"), UTF8String.fromString("driver1") } : new Object[] { 1000L, new Utf8("key1"), new Utf8("path1"), new Utf8("rider1"), new Utf8("driver1") };
    assertArrayEquals(expectedValues, columnValues);
}

@ParameterizedTest
@MethodSource("testCreateHoodieRecords")
void testCreateHoodieRecordsWithError(HoodieRecordType recordType, boolean enableErrorTableWriter, String recordKeyField) {
    Schema schema = new Schema.Parser().parse(SCHEMA_STRING);
    JavaRDD<GenericRecord> recordRdd = jsc.parallelize(Collections.singletonList(1)).map(i -> {
        GenericRecord genericRecord = new GenericData.Record(schema);
        genericRecord.put(0, i * 1000L);
        genericRecord.put(1, "key" + i);
        genericRecord.put(2, "path" + i);
        // The field is non-null in schema but the value is null, so this fails the Hudi record creation
        genericRecord.put(3, null);
        genericRecord.put(4, "driver");
        return genericRecord;
    });
    HoodieStreamer.Config cfg = new HoodieStreamer.Config();
    cfg.payloadClassName = DefaultHoodieRecordPayload.class.getName();
    TypedProperties props = new TypedProperties();
    props.put(KeyGeneratorOptions.PARTITIONPATH_FIELD_NAME.key(), "partition_path");
    props.put(KeyGeneratorOptions.RECORDKEY_FIELD_NAME.key(), recordKeyField);
    SchemaProvider schemaProvider = new SimpleSchemaProvider(jsc, schema, props);
    Option<BaseErrorTableWriter> errorTableWriter = enableErrorTableWriter ? Option.of(Mockito.mock(BaseErrorTableWriter.class)) : Option.empty();
    ArgumentCaptor<JavaRDD<?>> errorEventCaptor = ArgumentCaptor.forClass(JavaRDD.class);
    if (errorTableWriter.isPresent()) {
        doNothing().when(errorTableWriter.get()).addErrorEvents(errorEventCaptor.capture());
    }
    Option<JavaRDD<HoodieRecord>> records = HoodieStreamerUtils.createHoodieRecords(cfg, props, Option.of(recordRdd), schemaProvider, recordType, false, "000", errorTableWriter);
    assertTrue(records.isPresent());
    if (enableErrorTableWriter) {
        List<ErrorEvent<String>> actualErrorEvents = (List<ErrorEvent<String>>) errorEventCaptor.getValue().collect();
        ErrorEvent<String> expectedErrorEvent = new ErrorEvent<>("{\"timestamp\": 1000, \"_row_key\": \"key1\", \"partition_path\": \"path1\", \"rider\": null, \"driver\": \"driver\"}", ErrorEvent.ErrorReason.RECORD_CREATION);
        assertEquals(Collections.singletonList(expectedErrorEvent), actualErrorEvents);
    } else {
        SparkException sparkException = assertThrows(SparkException.class, () -> records.get().collect());
        if (recordType == HoodieRecordType.SPARK) {
            // With SPARK record type, the exception should be thrown from HoodieStreamerUtils.createHoodieRecords
            assertEquals(HoodieRecordCreationException.class, sparkException.getCause().getClass());
            assertEquals("Failed to create Hoodie Record", sparkException.getCause().getMessage());
            assertEquals(recordKeyField.equals("rider") ? IllegalArgumentException.class : NullPointerException.class, sparkException.getCause().getCause().getClass());
            assertEquals(recordKeyField.equals("rider") ? "Found null value for the field that is declared as non-nullable: StructField(rider,StringType,false)" : null, sparkException.getCause().getCause().getMessage());
        } else {
            // With AVRO record type, the HoodieAvroIndexedRecord is successfully created
            // by HoodieStreamerUtils.createHoodieRecords because of lazy Avro encoding;
            // when collecting the record to the driver, the Avro encoding is triggered,
            // which is expected to throw an exception
            assertEquals(recordKeyField.equals("rider") ? HoodieKeyException.class : NullPointerException.class, sparkException.getCause().getClass());
            assertEquals(recordKeyField.equals("rider") ? "recordKey value: \"null\" for field: \"rider\" cannot be null or empty." : "null value for (non-nullable) string at rec.rider", sparkException.getCause().getMessage());
        }
    }
}

