@Test
void testValidateFileSlicesWithInstantInRollback() throws IOException {
    HoodieMetadataTableValidator.Config config = new HoodieMetadataTableValidator.Config();
    config.basePath = basePath;
    config.validateLatestFileSlices = true;
    config.validateAllFileGroups = true;
    MockHoodieMetadataTableValidator validator = new MockHoodieMetadataTableValidator(jsc, config);
    String partition = "partition10";
    String label = "metadata item";
    TimeGenerator timeGenerator = TimeGenerators.getTimeGenerator(HoodieTimeGeneratorConfig.defaultConfig(basePath), HadoopFSUtils.getStorageConf(jsc.hadoopConfiguration()));
    // Base file list
    Pair<List<FileSlice>, List<FileSlice>> filelistPair = generateTwoEqualFileSliceList(5, timeGenerator);
    List<FileSlice> listMdt = filelistPair.getLeft();
    List<FileSlice> listFs = filelistPair.getRight();
    // Size mismatch
    FileSlice extraFileSlice = generateRandomFileSlice(TimelineUtils.generateInstantTime(true, timeGenerator), TimelineUtils.generateInstantTime(true, timeGenerator), TimelineUtils.generateInstantTime(true, timeGenerator)).getLeft();
    listFs.add(extraFileSlice);
    // Mock the rollback timeline
    HoodieTableMetaClient spyMetaClient = spy(metaClient);
    HoodieActiveTimeline spyTimeline = spy(metaClient.getActiveTimeline());
    doReturn(spyTimeline).when(spyMetaClient).getActiveTimeline();
    HoodieTimeline mockRollbackTimeline = mock(HoodieTimeline.class, RETURNS_DEEP_STUBS);
    doReturn(mockRollbackTimeline).when(spyTimeline).getRollbackTimeline();
    HoodieInstant rollbackInstant = new HoodieInstant(HoodieInstant.State.COMPLETED, HoodieTimeline.ROLLBACK_ACTION, "001", InstantComparatorV2.REQUESTED_TIME_BASED_COMPARATOR);
    HoodieInstant rollbackRequestedInstant = new HoodieInstant(HoodieInstant.State.REQUESTED, HoodieTimeline.ROLLBACK_ACTION, "001", InstantComparatorV2.REQUESTED_TIME_BASED_COMPARATOR);
    HoodieInstant matchingRollbackInstant = new HoodieInstant(HoodieInstant.State.COMPLETED, HoodieTimeline.ROLLBACK_ACTION, "002", InstantComparatorV2.REQUESTED_TIME_BASED_COMPARATOR);
    HoodieInstant matchingRollbackRequestedInstant = new HoodieInstant(HoodieInstant.State.REQUESTED, HoodieTimeline.ROLLBACK_ACTION, "002", InstantComparatorV2.REQUESTED_TIME_BASED_COMPARATOR);
    when(mockRollbackTimeline.getInstantsAsStream()).thenReturn(Stream.of(rollbackInstant, matchingRollbackInstant));
    HoodieRollbackPlan rollbackPlan = new HoodieRollbackPlan();
    rollbackPlan.setInstantToRollback(HoodieInstantInfo.newBuilder().setCommitTime("000").setAction("commit").build());
    doReturn(rollbackPlan).when(spyTimeline).readInstantContent(rollbackRequestedInstant, HoodieRollbackPlan.class);
    HoodieRollbackPlan matchingRollbackPlan = new HoodieRollbackPlan();
    matchingRollbackPlan.setInstantToRollback(HoodieInstantInfo.newBuilder().setCommitTime(extraFileSlice.getBaseInstantTime()).setAction("commit").build());
    doReturn(matchingRollbackPlan).when(spyTimeline).readInstantContent(matchingRollbackRequestedInstant, HoodieRollbackPlan.class);
    Exception exception = assertThrows(HoodieValidationException.class, () -> validator.validateFileSlices(listMdt, listFs, partition, spyMetaClient, label));
    assertEquals(String.format("Validation of %s for partition %s failed for table: %s. " + "Number of file slices based on the file system does not match that based on the " + "metadata table. File system-based listing: %d & MDT-based listing: %d. %s", label, partition, basePath, listFs.size(), listMdt.size(), computeDiffSummary(listMdt, listFs, metaClient, logDetailMaxLength)), exception.getMessage());
    verify(spyTimeline, times(2)).readInstantContent(any(), any());
}

@ParameterizedTest
@ValueSource(booleans = { true, false })
void testValidateFileSlices(boolean oversizeList) throws Exception {
    SparkRDDValidationUtils.withRDDPersistenceValidation(sparkSession, () -> {
        HoodieMetadataTableValidator.Config config = new HoodieMetadataTableValidator.Config();
        config.basePath = basePath;
        config.validateLatestFileSlices = true;
        config.validateAllFileGroups = true;
        TimeGenerator timeGenerator = TimeGenerators.getTimeGenerator(HoodieTimeGeneratorConfig.defaultConfig(basePath), HadoopFSUtils.getStorageConf(jsc.hadoopConfiguration()));
        MockHoodieMetadataTableValidator validator = new MockHoodieMetadataTableValidator(jsc, config);
        int listSize = oversizeList ? 500 : 50;
        String partition = "partition10";
        String label = "metadata item";
        // Base file list
        Pair<List<FileSlice>, List<FileSlice>> filelistPair = generateTwoEqualFileSliceList(listSize, timeGenerator);
        List<FileSlice> listMdt = filelistPair.getLeft();
        List<FileSlice> listFs = filelistPair.getRight();
        // Equal case
        assertDoesNotThrow(() -> validator.validateFileSlices(listMdt, listFs, partition, metaClient, label));
        // Size mismatch
        listFs.add(generateRandomFileSlice(TimelineUtils.generateInstantTime(true, timeGenerator), TimelineUtils.generateInstantTime(true, timeGenerator), TimelineUtils.generateInstantTime(true, timeGenerator)).getLeft());
        assertEquals(oversizeList, toStringWithThreshold(listMdt, Integer.MAX_VALUE).length() > logDetailMaxLength);
        assertEquals(oversizeList, toStringWithThreshold(listFs, Integer.MAX_VALUE).length() > logDetailMaxLength);
        Exception exception = assertThrows(HoodieValidationException.class, () -> validator.validateFileSlices(listMdt, listFs, partition, metaClient, label));
        assertEquals(String.format("Validation of %s for partition %s failed for table: %s. " + "Number of file slices based on the file system does not match that based on the " + "metadata table. File system-based listing: %d & MDT-based listing: %d. %s", label, partition, basePath, listFs.size(), listMdt.size(), computeDiffSummary(listMdt, listFs, metaClient, logDetailMaxLength)), exception.getMessage());
        listFs.remove(listFs.size() - 1);
        // Item mismatch
        int i = 35;
        // Instant time mismatch
        FileSlice originalFileSlice = listMdt.get(i);
        FileSlice mismatchFileSlice = new FileSlice(originalFileSlice.getFileGroupId(), TimelineUtils.generateInstantTime(true, timeGenerator), originalFileSlice.getBaseFile().get(), originalFileSlice.getLogFiles().collect(Collectors.toList()));
        listMdt.set(i, mismatchFileSlice);
        exception = assertThrows(HoodieValidationException.class, () -> validator.validateFileSlices(listMdt, listFs, partition, metaClient, label));
        assertEquals(String.format("Validation of %s for partition %s failed for table: %s. " + "File group ID (missing a file group in MDT) " + "or base instant time mismatches. File slice from file system-based listing: %s; " + "File slice from MDT-based listing: %s.", label, partition, basePath, listFs.get(i), listMdt.get(i)), exception.getMessage());
        // base file mismatch
        mismatchFileSlice = new FileSlice(originalFileSlice.getFileGroupId(), originalFileSlice.getBaseInstantTime(), generateRandomBaseFile().getLeft(), originalFileSlice.getLogFiles().collect(Collectors.toList()));
        listMdt.set(i, mismatchFileSlice);
        exception = assertThrows(HoodieValidationException.class, () -> validator.validateFileSlices(listMdt, listFs, partition, metaClient, label));
        assertEquals(String.format("Validation of %s for partition %s failed for table: %s. " + "Base files mismatch. " + "File slice from file system-based listing: %s; " + "File slice from MDT-based listing: %s.", label, partition, basePath, listFs.get(i), listMdt.get(i)), exception.getMessage());
    });
}

