}

@Test
void testValidateFileSlicesTruncation() {
    // Setup mock objects
    HoodieMetadataTableValidator.Config config = new HoodieMetadataTableValidator.Config();
    config.basePath = basePath;
    // Small length to force truncation
    config.logDetailMaxLength = 100;
    MockHoodieMetadataTableValidator validator = new MockHoodieMetadataTableValidator(jsc, config);
    // Generate large lists of file slices that will exceed truncation threshold
    String partition = "partition_" + generateRandomString(10);
    List<FileSlice> mdtFileSlices = new ArrayList<>();
    List<FileSlice> fsFileSlices = new ArrayList<>();
    // Generate 20 file slices for MDT and 15 for FS to ensure they're different
    TimeGenerator timeGenerator = TimeGenerators.getTimeGenerator(HoodieTimeGeneratorConfig.defaultConfig(basePath), HadoopFSUtils.getStorageConf(jsc.hadoopConfiguration()));
    for (int i = 0; i < 20; i++) {
        String fileId = UUID.randomUUID().toString();
        String baseInstantTime = WriteClientTestUtils.createNewInstantTime();
        // Create file slice with base file and log files
        HoodieBaseFile baseFile = new HoodieBaseFile(FSUtils.makeBaseFileName(baseInstantTime, "1-0-1", fileId, HoodieFileFormat.PARQUET.getFileExtension()));
        List<HoodieLogFile> logFiles = Arrays.asList(new HoodieLogFile(FSUtils.makeLogFileName(fileId, HoodieLogFile.DELTA_EXTENSION, baseInstantTime, 1, "1-0-1")), new HoodieLogFile(FSUtils.makeLogFileName(fileId, HoodieLogFile.DELTA_EXTENSION, baseInstantTime, 2, "1-0-1")));
        FileSlice slice = new FileSlice(new HoodieFileGroupId(partition, fileId), baseInstantTime);
        slice.setBaseFile(baseFile);
        logFiles.forEach(slice::addLogFile);
        mdtFileSlices.add(slice);
        // Add to FS list for first 15 entries
        if (i < 15) {
            fsFileSlices.add(new FileSlice(slice));
        }
    }
    // Test validation with truncation
    HoodieValidationException exception = assertThrows(HoodieValidationException.class, () -> validator.validateFileSlices(mdtFileSlices, fsFileSlices, partition, metaClient, "test"));
    String errorMsg = exception.getMessage();
    // Verify truncation behavior
    // Should contain truncation indicator
    assertTrue(errorMsg.contains("..."));
    // Account for both lists and additional message text
    assertTrue(errorMsg.length() <= config.logDetailMaxLength * 2 + 1000);
    // Verify error message contains file slice counts
    assertTrue(errorMsg.contains(String.format("Number of file slices based on the file system does not match that based on the metadata table. File system-based listing: %d & MDT-based listing: %d.", fsFileSlices.size(), mdtFileSlices.size())));
}

